# ============================================================================
# [BUG 诊断] 全局异常日志 — 把任何未捕获的异常写入用户家目录的日志文件
#  方便用户在软件卡退后,把日志文件发给开发者用于精准定位问题。
#  日志路径: %USERPROFILE%/spine_cobb_crash.log (Windows)
#           或  ~/spine_cobb_crash.log (Linux/Mac)
# ============================================================================
def _crash_log_path():
    try:
        return os.path.join(os.path.expanduser('~'), 'spine_cobb_crash.log')
    except Exception:
        return 'spine_cobb_crash.log'

def _crash_log(tag, err=None):
    """写入崩溃/错误日志,带时间戳和堆栈"""
    try:
        import time as _t
        ts = _t.strftime('%Y-%m-%d %H:%M:%S', _t.localtime())
        with open(_crash_log_path(), 'a', encoding='utf-8') as f:
            f.write(f'\n[{ts}] {tag}\n')
            if err is not None:
                f.write(f'  Error: {type(err).__name__}: {err}\n')
            f.write(traceback.format_exc())
            f.write('-' * 60 + '\n')
    except Exception:
        pass

def _global_excepthook(exctype, value, tb):
    """所有未捕获的异常都写入崩溃日志,然后调用默认处理"""
    try:
        import time as _t
        ts = _t.strftime('%Y-%m-%d %H:%M:%S', _t.localtime())
        with open(_crash_log_path(), 'a', encoding='utf-8') as f:
            f.write(f'\n[{ts}] [UNHANDLED]\n')
            f.write(f'  {exctype.__name__}: {value}\n')
            for line in traceback.format_exception(exctype, value, tb):
                f.write(line)
            f.write('=' * 60 + '\n')
    except Exception:
        pass
    sys.__excepthook__(exctype, value, tb)

sys.excepthook = _global_excepthook


