# ----------------------------------------------------------------------------
#  激活密钥模式 (License Key Activation)
#
#  设计: 完全替代账号注册/登录, 改为"密钥激活"模式
#    1. 管理员生成一个 30 天密钥发给对方
#    2. 对方在软件中输入密钥 -> 验证通过 -> 进入软件 + 保存激活态
#    3. 30 天内打开软件直接进入 (免密钥免账号免密码)
#    4. 30 天后激活到期 -> 弹密钥输入窗 -> 输入新密钥 -> 再 30 天
#
#  密钥格式 (3 段或 4 段):
#    3 段: <role>.<expiry_yyyymmdd>.<sig>           # 不含身份标识
#    4 段: <role>.<identity>.<expiry_yyyymmdd>.<sig>  # 含身份标识(便于追溯)
#  role: 'U' = 普通用户, 'A' = 管理员
#  例: U.zhangsan.20260626.A7F2B8D4
#  例: A.21260101.B5C8D2F1
# ----------------------------------------------------------------------------
LICENSE_SECRET       = b'CHANGE_ME_license_secret_before_distributing'

# 普通用户密钥默认有效期 (天)
LICENSE_DEFAULT_DAYS = 30

# 管理员密钥默认有效期 (天) — 100 年, 等于永久
ADMIN_LICENSE_DAYS   = 36500
# Hardcoded "管理员注册口令"
# 只有知道这个口令的人才能注册成为管理员
# 即使数据库被删除重建, 也只有知道这个口令的人才能恢复管理员权限
ADMIN_REG_TOKEN     = 'CHANGE_ME_admin_register_token'

# 自动登录 token 派生密钥所用的硬编码盐 (固定不变)
# 与设备指纹一起派生 token 密钥, 实现"跨机器自动失效"
APP_SECRET_SALT     = b'CHANGE_ME_app_secret_salt'

# 自动登录有效期 (60 天)
AUTO_LOGIN_DAYS     = 60

# scrypt 哈希参数 (OWASP 推荐: n=2^14, r=8, p=1, dklen=32)
SCRYPT_N            = 2 ** 14
SCRYPT_R            = 8
SCRYPT_P            = 1
SCRYPT_DKLEN        = 32

# 用户状态常量
STATUS_ACTIVE       = 'active'        # 正常使用
STATUS_PENDING      = 'pending'       # 等待管理员批准
STATUS_DISABLED     = 'disabled'      # 已被禁用


def _data_dir():
    """获取数据目录: %APPDATA%\\SpineCobbAnalyzer  /  ~/.spine_cobb_data"""
    try:
        if sys.platform.startswith('win'):
            base = os.environ.get('APPDATA', os.path.expanduser('~'))
        else:
            base = os.path.expanduser('~')
        d = os.path.join(base, APP_NAME)
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        return os.path.expanduser('~')


def _db_path():
    return os.path.join(_data_dir(), 'spineusers.db')


def _session_path():
    return os.path.join(_data_dir(), 'session.dat')


# ----------------------------------------------------------------------------
#  设备指纹 (机器码)
#  原理: 采集 CPU + 主板 UUID + 用户名, SHA256 哈希
# ----------------------------------------------------------------------------
_DEVICE_FP_CACHE = None

def get_device_fingerprint():
    """获取设备指纹 (32 字符 hex)。失败时退化到 platform.node()。

    [v15 性能修复]
    旧版在 Windows 启动时连续调用 3 个 wmic 命令, 每个最长等待 5 秒。
    在很多 Win10/Win11 电脑上 WMIC 被移除或响应很慢, 会直接造成启动慢。
    新版优先读取注册表 MachineGuid + MAC/主机信息, 只有在确实缺少标识时
    才用短超时 wmic 兜底; 结果仍缓存到 _DEVICE_FP_CACHE。
    """
    global _DEVICE_FP_CACHE
    if _DEVICE_FP_CACHE:
        return _DEVICE_FP_CACHE

    parts = []

    # Windows 快路径: 注册表 MachineGuid (毫秒级, Unicode 安全)
    if sys.platform.startswith('win'):
        try:
            import winreg
            with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r'SOFTWARE\Microsoft\Cryptography') as k:
                guid, _ = winreg.QueryValueEx(k, 'MachineGuid')
            if guid:
                parts.append(str(guid).strip())
        except Exception:
            pass

    # 跨平台快路径: MAC / 主机名 / 用户名 / 平台信息
    try:
        import uuid as _uuid
        node = _uuid.getnode()
        if node:
            parts.append(hex(int(node)))
    except Exception:
        pass
    parts.append(platform.node())
    parts.append(platform.system())
    parts.append(platform.machine())
    try:
        parts.append(os.environ.get('USERNAME', '') or
                     os.environ.get('USER', ''))
    except Exception:
        pass

    # 兜底: 仅当可用信息太少时才短超时调用 wmic, 避免启动被卡住
    if sys.platform.startswith('win') and len([p for p in parts if p]) < 2:
        try:
            import shutil as _shutil
            if _shutil.which('wmic'):
                for cmd in (['wmic', 'csproduct', 'get', 'UUID'],
                            ['wmic', 'cpu', 'get', 'ProcessorId'],
                            ['wmic', 'baseboard', 'get', 'SerialNumber']):
                    try:
                        proc = subprocess.run(
                            cmd,
                            capture_output=True, text=True, timeout=1.2,
                            creationflags=0x08000000)  # CREATE_NO_WINDOW
                        if proc.returncode == 0:
                            out = proc.stdout.strip().splitlines()
                            if len(out) >= 2:
                                val = out[1].strip()
                                if val and val.upper() not in (
                                        'UUID', 'PROCESSORID', 'SERIALNUMBER',
                                        'TO BE FILLED BY O.E.M.', 'NONE',
                                        'DEFAULT STRING'):
                                    parts.append(val)
                    except Exception:
                        pass
        except Exception:
            pass

    raw = '||'.join(str(p) for p in parts if p).encode('utf-8', errors='ignore')
    if not raw:
        raw = b'SpineCobbAnalyzer::fallback-device'
    fp = hashlib.sha256(raw).hexdigest()[:32]
    _DEVICE_FP_CACHE = fp
    return fp


def _token_secret_key():
    """token 签名密钥 = SHA256(设备指纹 + 硬编码盐)。"""
    fp = get_device_fingerprint().encode('utf-8')
    return hashlib.sha256(fp + APP_SECRET_SALT).digest()


# ----------------------------------------------------------------------------
#  密码哈希 (scrypt)
# ----------------------------------------------------------------------------
def hash_password(password: str) -> str:
    """生成密码哈希字符串: 'scrypt$<salt_b64>$<hash_b64>'"""
    salt = secrets.token_bytes(16)
    dk = hashlib.scrypt(
        password.encode('utf-8'),
        salt=salt,
        n=SCRYPT_N, r=SCRYPT_R, p=SCRYPT_P, dklen=SCRYPT_DKLEN,
        maxmem=64 * 1024 * 1024)
    return 'scrypt${}${}'.format(
        base64.b64encode(salt).decode('ascii'),
        base64.b64encode(dk).decode('ascii'))


def verify_password(password: str, hashed: str) -> bool:
    """常时间比较验证密码"""
    try:
        if not hashed or not hashed.startswith('scrypt$'):
            return False
        _, salt_b64, hash_b64 = hashed.split('$', 2)
        salt = base64.b64decode(salt_b64)
        expected = base64.b64decode(hash_b64)
        actual = hashlib.scrypt(
            password.encode('utf-8'),
            salt=salt,
            n=SCRYPT_N, r=SCRYPT_R, p=SCRYPT_P, dklen=SCRYPT_DKLEN,
            maxmem=64 * 1024 * 1024)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False


# ----------------------------------------------------------------------------
#  邀请码生成与验证 (HMAC-SHA256 签名, 本地无状态验证)
#
#  格式: <identity>.<expiry_yyyymmdd>.<8 位 hex 签名>
#  示例: zhangsan.20260626.A7F2B8D4
#
#  原理: 管理员调 generate_invite_code() 生成 -> 发给对方 -> 对方注册时
#        提供, 软件用同一个 INVITE_SECRET 重新计算签名比对。
# ----------------------------------------------------------------------------
def generate_invite_code(identity: str,
                         valid_days: int = INVITE_DEFAULT_DAYS) -> str:
    """生成签名邀请码。
    identity: 接收人标识 (建议: 对方的微信号/姓名/QQ号, 用于追溯)
    valid_days: 有效天数, 默认 30 天
    返回: 形如 'zhangsan.20260626.A7F2B8D4' 的字符串, 失败返回 None
    """
    if not identity:
        return None
    identity = str(identity).strip()
    # 替换会与分隔符冲突的字符
    identity = identity.replace('.', '_').replace(' ', '_')
    if not identity:
        return None
    if valid_days <= 0:
        valid_days = 1
    expiry_ts = int(time.time()) + int(valid_days) * 86400
    expiry_str = time.strftime('%Y%m%d', time.localtime(expiry_ts))
    payload = f'{identity}.{expiry_str}'
    sig = hmac.new(INVITE_SECRET, payload.encode('utf-8'),
                   hashlib.sha256).hexdigest()[:8].upper()
    return f'{payload}.{sig}'


def verify_invite_code(code: str):
    """验证邀请码合法性。
    返回: (ok: bool, identity_or_msg: str)
    """
    if not code:
        return False, '邀请码不能为空'
    code = str(code).strip()
    parts = code.split('.')
    if len(parts) != 3:
        return False, '邀请码格式不正确 (应包含 2 个点号)'
    identity, expiry_str, sig = parts
    if not (identity and expiry_str and sig):
        return False, '邀请码内容不完整'
    # 检查日期格式与过期
    try:
        expiry_t = time.strptime(expiry_str, '%Y%m%d')
        expiry_ts = time.mktime(expiry_t) + 86400  # 给一天宽限
    except Exception:
        return False, '邀请码格式不正确 (日期解析失败)'
    if time.time() > expiry_ts:
        return False, f'邀请码已过期 (有效期至 {expiry_str[:4]}-' \
                      f'{expiry_str[4:6]}-{expiry_str[6:]})'
    # 重新计算签名比对
    payload = f'{identity}.{expiry_str}'
    expected = hmac.new(INVITE_SECRET, payload.encode('utf-8'),
                        hashlib.sha256).hexdigest()[:8].upper()
    if not hmac.compare_digest(sig.upper().strip(), expected):
        return False, '邀请码无效 (签名不匹配, 可能输错或已被篡改)'
    return True, identity


# ----------------------------------------------------------------------------
#  激活密钥 (License Key) 生成与验证
#
#  接收一个 license key, 验证签名 + 检查过期。验证通过返回密钥含有的信息:
#      role: 'U' or 'A'
#      identity: 接收人标识 (可能为 '')
#      expiry_ts: 过期时间戳 (秒)
#      is_admin: bool
# ----------------------------------------------------------------------------
def generate_license_key(role='U',
                         valid_days=LICENSE_DEFAULT_DAYS,
                         identity=''):
    """生成激活密钥
    role: 'U' = 普通用户, 'A' = 管理员
    valid_days: 有效天数
    identity: 接收人标识 (可选, 用于追溯)
    返回: 形如 'U.zhangsan.20260626.A7F2B8D4' 或 'A.21260101.B5C8D2F1'
    """
    role = (role or 'U').upper()
    if role not in ('U', 'A'):
        role = 'U'
    if valid_days <= 0:
        valid_days = 1
    expiry_ts = int(time.time()) + int(valid_days) * 86400
    expiry_str = time.strftime('%Y%m%d', time.localtime(expiry_ts))
    identity = (str(identity).strip()
                .replace('.', '_').replace(' ', '_')) if identity else ''
    if identity:
        payload = f'{role}.{identity}.{expiry_str}'
    else:
        payload = f'{role}.{expiry_str}'
    sig = hmac.new(LICENSE_SECRET, payload.encode('utf-8'),
                   hashlib.sha256).hexdigest()[:8].upper()
    return f'{payload}.{sig}'


def verify_license_key(key):
    """验证激活密钥
    返回: (ok, info_dict_or_msg)
    """
    if not key:
        return False, '密钥不能为空'
    key = str(key).strip()
    parts = key.split('.')
    if len(parts) == 3:
        role, expiry_str, sig = parts
        identity = ''
        payload = f'{role}.{expiry_str}'
    elif len(parts) == 4:
        role, identity, expiry_str, sig = parts
        payload = f'{role}.{identity}.{expiry_str}'
    else:
        return False, '密钥格式不正确'
    if role not in ('U', 'A'):
        return False, '密钥格式不正确 (角色字段错误)'
    try:
        expiry_t = time.strptime(expiry_str, '%Y%m%d')
        # Windows 的 time.mktime() 对超大年份 (如 9999) 会溢出
        # 年份超过 2200 年时直接视为"永不过期"
        if expiry_t.tm_year > 2200:
            expiry_ts = 9999999999999
        else:
            expiry_ts = int(time.mktime(expiry_t)) + 86400
    except Exception:
        return False, '密钥格式不正确 (日期解析失败)'
    if time.time() > expiry_ts:
        return False, (f'密钥已过期 (有效期至 {expiry_str[:4]}-'
                       f'{expiry_str[4:6]}-{expiry_str[6:]})')
    expected = hmac.new(LICENSE_SECRET, payload.encode('utf-8'),
                        hashlib.sha256).hexdigest()[:8].upper()
    if not hmac.compare_digest(sig.upper().strip(), expected):
        return False, '密钥无效 (签名不匹配, 可能输错或被篡改)'
    return True, {
        'role':       role,
        'identity':   identity,
        'expiry_ts':  expiry_ts,
        'expiry_str': expiry_str,
        'is_admin':   role == 'A',
    }


def _activation_path():
    return os.path.join(_data_dir(), 'activation.dat')


def save_activation(license_info, original_key=''):
    """保存激活态到 activation.dat (用于免密钥启动)。
    用 HMAC + 设备指纹双重防护: 文件复制到别的电脑会失效。
    """
    try:
        device_fp = get_device_fingerprint()
        payload = {
            'role':         license_info.get('role', 'U'),
            'identity':     license_info.get('identity', ''),
            'expiry_ts':    int(license_info.get('expiry_ts', 0)),
            'expiry_str':   license_info.get('expiry_str', ''),
            'device_fp':    device_fp,
            'original_key': original_key or '',
        }
        msg = (f"{payload['role']}|{payload['expiry_ts']}|"
               f"{payload['device_fp']}")
        payload['sig'] = hmac.new(_token_secret_key(),
                                   msg.encode('utf-8'),
                                   hashlib.sha256).hexdigest()
        token = base64.urlsafe_b64encode(
            json.dumps(payload, separators=(',', ':')).encode('utf-8')
        ).decode('ascii')
        with open(_activation_path(), 'w', encoding='utf-8') as f:
            f.write(token)
        return True
    except Exception:
        return False


def load_activation():
    """读取并验证本地激活态。返回 dict 或 None。"""
    try:
        path = _activation_path()
        if not os.path.isfile(path):
            return None
        with open(path, 'r', encoding='utf-8') as f:
            token = f.read().strip()
        if not token:
            return None
        raw = base64.urlsafe_b64decode(token.encode('ascii')).decode('utf-8')
        payload = json.loads(raw)
        # 设备指纹必须匹配
        if payload.get('device_fp') != get_device_fingerprint():
            return None
        # 必须未过期
        if int(time.time()) >= int(payload.get('expiry_ts', 0)):
            return None
        # 验证签名
        msg = (f"{payload.get('role', 'U')}|"
               f"{payload.get('expiry_ts', 0)}|"
               f"{payload.get('device_fp', '')}")
        expected = hmac.new(_token_secret_key(),
                            msg.encode('utf-8'),
                            hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, payload.get('sig', '')):
            return None
        return payload
    except Exception:
        return None


def clear_activation():
    """清除本地激活态"""
    try:
        path = _activation_path()
        if os.path.isfile(path):
            os.remove(path)
    except Exception:
        pass


# ----------------------------------------------------------------------------
#  数据库 (保留, 供审计日志使用)
# ----------------------------------------------------------------------------
# [BUG 修复 - 严重死锁] 原代码用 threading.Lock() (不可重入锁)。
#   死锁路径: create_user / admin_set_status / admin_delete_user /
#             admin_reset_password / change_password 在 with _DB_LOCK 内
#             调用 log_audit, 而 log_audit 自己也 with _DB_LOCK ->
#             同一线程二次 acquire 永久阻塞 -> 整个 Tk mainloop 卡死 ->
#             用户看到 "卡退死机"。
#   修复  : 改为 threading.RLock() 可重入锁, 同一线程多次 acquire 不阻塞,
#           对其它线程的互斥语义保持不变。
_DB_LOCK = threading.RLock()
# [BUG 修复] 让 init_db() 仅执行一次的标志位 (避免每次调用 get_user / list_users
#            都重新做 CREATE TABLE 与列迁移检查, 这是新增用户后卡顿的潜在根因)
_DB_INITED = False


def _conn():
    db = sqlite3.connect(_db_path(), timeout=10.0,
                         isolation_level=None,  # autocommit
                         check_same_thread=False)
    db.row_factory = sqlite3.Row
    try:
        db.execute('PRAGMA journal_mode=WAL')
        db.execute('PRAGMA synchronous=NORMAL')
    except Exception: pass
    return db


def _migrate_table(c, table_name, expected_cols):
    """检查表的列, 缺失就 ALTER TABLE ADD COLUMN 自动补齐。
    expected_cols: [(col_name, sql_def), ...]
    SQLite 的 ALTER TABLE ADD COLUMN 不允许添加 PRIMARY KEY / UNIQUE,
    但允许 NOT NULL DEFAULT, 这正是我们需要的。
    """
    try:
        rows = c.execute(f"PRAGMA table_info({table_name})").fetchall()
        existing = {r['name'] for r in rows}
    except Exception:
        return  # 表不存在或其它错误, 跳过迁移
    for col, sql_def in expected_cols:
        if col not in existing:
            try:
                c.execute(
                    f'ALTER TABLE {table_name} ADD COLUMN {col} {sql_def}')
            except Exception:
                # 退化策略: 移除 NOT NULL 后再试
                try:
                    simple = sql_def.replace('NOT NULL', '').strip()
                    c.execute(
                        f'ALTER TABLE {table_name} ADD COLUMN {col} {simple}')
                except Exception:
                    pass  # 实在不行就跳过, 让上层用 try/except 兜底


def init_db():
    """初始化数据库表结构 + 自动迁移旧版本 schema。
    [BUG 修复 / 性能加固]
    原行为: 每次 get_user / list_users / create_user 都会调用 init_db(),
            每次都要 acquire _DB_LOCK + 执行 N 个 CREATE TABLE IF NOT EXISTS
            + N 个 PRAGMA + N 个 _migrate_table 检查。在 SQLite WAL 模式下,
            这些都是写事务, 会和 INSERT/UPDATE 互斥, 导致 "新增用户后卡顿"。
    修复  : 用 _DB_INITED 全局标志, init_db() 只执行一次。
    """
    global _DB_INITED
    if _DB_INITED:
        return
    with _DB_LOCK:
        if _DB_INITED:  # 双重检查锁
            return
        c = _conn()
        try:
            # ---- 1) 创建表 (如果不存在) ----
            c.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    username        TEXT UNIQUE NOT NULL,
                    password_hash   TEXT NOT NULL,
                    is_admin        INTEGER NOT NULL DEFAULT 0,
                    status          TEXT NOT NULL DEFAULT 'active',
                    full_name       TEXT,
                    contact         TEXT,
                    note            TEXT,
                    created_at      INTEGER NOT NULL DEFAULT 0,
                    last_login_at   INTEGER,
                    device_fp       TEXT
                )
            ''')
            c.execute('''
                CREATE TABLE IF NOT EXISTS login_logs (
                    id          INTEGER PRIMARY KEY AUTOINCREMENT,
                    username    TEXT NOT NULL DEFAULT '',
                    login_time  INTEGER NOT NULL DEFAULT 0,
                    success     INTEGER NOT NULL DEFAULT 0,
                    device_fp   TEXT,
                    note        TEXT
                )
            ''')
            c.execute('''
                CREATE TABLE IF NOT EXISTS audit_logs (
                    id          INTEGER PRIMARY KEY AUTOINCREMENT,
                    username    TEXT NOT NULL DEFAULT '',
                    action      TEXT NOT NULL DEFAULT '',
                    detail      TEXT,
                    time        INTEGER NOT NULL DEFAULT 0
                )
            ''')

            # ---- 2) 自动迁移旧 schema (兼容历史数据库) ----
            #   如果旧表是其它版本创建的, 缺哪列补哪列
            _migrate_table(c, 'users', [
                ('is_admin',      "INTEGER NOT NULL DEFAULT 0"),
                ('status',        "TEXT NOT NULL DEFAULT 'active'"),
                ('full_name',     "TEXT"),
                ('contact',       "TEXT"),
                ('note',          "TEXT"),
                ('created_at',    "INTEGER NOT NULL DEFAULT 0"),
                ('last_login_at', "INTEGER"),
                ('device_fp',     "TEXT"),
                ('password_hash', "TEXT NOT NULL DEFAULT ''"),
            ])
            _migrate_table(c, 'login_logs', [
                ('username',   "TEXT NOT NULL DEFAULT ''"),
                ('login_time', "INTEGER NOT NULL DEFAULT 0"),
                ('success',    "INTEGER NOT NULL DEFAULT 0"),
                ('device_fp',  "TEXT"),
                ('note',       "TEXT"),
            ])
            _migrate_table(c, 'audit_logs', [
                ('username', "TEXT NOT NULL DEFAULT ''"),
                ('action',   "TEXT NOT NULL DEFAULT ''"),
                ('detail',   "TEXT"),
                ('time',     "INTEGER NOT NULL DEFAULT 0"),
            ])

            # ---- 3) 创建索引 ----
            c.execute('CREATE INDEX IF NOT EXISTS ix_login_logs_user '
                      'ON login_logs(username, login_time DESC)')
            c.execute('CREATE INDEX IF NOT EXISTS ix_audit_logs_user '
                      'ON audit_logs(username, time DESC)')
            _DB_INITED = True  # 标记初始化完成
        finally:
            c.close()


def has_any_admin():
    """数据库中是否已有管理员账号"""
    init_db()
    c = _conn()
    try:
        row = c.execute(
            'SELECT COUNT(*) AS n FROM users WHERE is_admin=1'
        ).fetchone()
        return (row['n'] or 0) > 0
    finally:
        c.close()


def has_any_user():
    """数据库中是否已有任意账号"""
    init_db()
    c = _conn()
    try:
        row = c.execute('SELECT COUNT(*) AS n FROM users').fetchone()
        return (row['n'] or 0) > 0
    finally:
        c.close()


def get_user(username: str):
    """根据用户名查找用户, 返回 dict 或 None"""
    init_db()
    if not username: return None
    c = _conn()
    try:
        row = c.execute(
            'SELECT * FROM users WHERE username=? LIMIT 1',
            (username,)).fetchone()
        return dict(row) if row else None
    finally:
        c.close()


def list_users():
    """返回所有用户列表 (供管理员查看)"""
    init_db()
    c = _conn()
    try:
        rows = c.execute('SELECT * FROM users ORDER BY id').fetchall()
        return [dict(r) for r in rows]
    finally:
        c.close()


def create_user(username, password, *,
                is_admin=False, status=STATUS_ACTIVE,
                full_name='', contact='', note=''):
    """创建新用户。返回 (ok, msg)。
    [BUG 修复 v2 - 二次防线] 把 log_audit 调用移到 with _DB_LOCK 之外,
    避免嵌套锁 + 嵌套 SQLite 连接造成卡顿/死锁 (即使 RLock 允许重入,
    SQLite 同线程双连接仍可能有 BUSY)。这是 "新增用户后死机" 的最终修复。
    """
    if not username or not username.strip():
        return False, '用户名不能为空'
    username = username.strip()
    if len(username) > 64:
        return False, '用户名过长 (最多 64 字符)'
    if not password or len(password) < 6:
        return False, '密码至少 6 位'
    if len(password) > 256:
        return False, '密码过长'
    if get_user(username):
        return False, '该用户名已被注册'
    init_db()
    pw_hash = hash_password(password)
    now = int(time.time())
    fp = get_device_fingerprint()
    err_msg = None
    integrity_err = False
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute(
                'INSERT INTO users '
                '(username, password_hash, is_admin, status, '
                ' full_name, contact, note, created_at, device_fp) '
                'VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
                (username, pw_hash, 1 if is_admin else 0,
                 status, full_name or '', contact or '', note or '',
                 now, fp))
        except sqlite3.IntegrityError:
            integrity_err = True
        except Exception as e:
            err_msg = f'数据库错误: {e}'
        finally:
            c.close()

    if integrity_err:
        return False, '该用户名已被注册'
    if err_msg:
        return False, err_msg
    # 日志在锁外调用 - 失败不影响主操作
    try:
        log_audit(username, 'register',
                  f'is_admin={is_admin}, status={status}')
    except Exception: pass
    return True, '注册成功'


def authenticate(username, password):
    """验证用户名+密码。返回 (ok, user_dict_or_msg)。"""
    if not username or not password:
        return False, '请输入用户名和密码'
    u = get_user(username.strip())
    if u is None:
        log_login_attempt(username, False, note='用户不存在')
        return False, '用户名或密码错误'
    if u.get('status') == STATUS_DISABLED:
        log_login_attempt(username, False, note='账号已被禁用')
        return False, '该账号已被管理员禁用，请联系管理员'
    if u.get('status') == STATUS_PENDING:
        log_login_attempt(username, False, note='账号待批准')
        return False, '账号正在等待管理员审批，请耐心等待'
    if not verify_password(password, u['password_hash']):
        log_login_attempt(username, False, note='密码错误')
        return False, '用户名或密码错误'
    # 通过
    update_last_login(username)
    log_login_attempt(username, True, note='密码登录')
    return True, u


def update_last_login(username):
    init_db()
    now = int(time.time())
    fp = get_device_fingerprint()
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute(
                'UPDATE users SET last_login_at=?, device_fp=? '
                'WHERE username=?',
                (now, fp, username))
        except Exception: pass
        finally: c.close()


def change_password(username, new_password):
    """修改密码
    [BUG 修复 v2] log_audit 移出锁, 避免嵌套连接造成 SQLite BUSY
    """
    if not new_password or len(new_password) < 6:
        return False, '新密码至少 6 位'
    u = get_user(username)
    if not u:
        return False, '用户不存在'
    init_db()
    pw_hash = hash_password(new_password)
    err_msg = None
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute(
                'UPDATE users SET password_hash=? WHERE username=?',
                (pw_hash, username))
        except Exception as e:
            err_msg = f'修改失败: {e}'
        finally:
            c.close()
    if err_msg:
        return False, err_msg
    try: log_audit(username, 'change_password', '密码已修改')
    except Exception: pass
    return True, '密码修改成功'


def admin_set_status(username, status, operator):
    """管理员修改用户状态
    [BUG 修复 v2] log_audit 移出锁, 这是 "禁用/启用用户卡退" 的根本修复
    """
    if status not in (STATUS_ACTIVE, STATUS_PENDING, STATUS_DISABLED):
        return False, '无效状态'
    u = get_user(username)
    if not u:
        return False, '用户不存在'
    if u.get('is_admin'):
        return False, '不能修改管理员状态'
    err_msg = None
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute('UPDATE users SET status=? WHERE username=?',
                      (status, username))
        except Exception as e:
            err_msg = f'失败: {e}'
        finally:
            c.close()
    if err_msg:
        return False, err_msg
    try:
        log_audit(operator, f'set_status:{status}',
                  f'target={username}')
    except Exception: pass
    return True, '状态已更新'


def admin_delete_user(username, operator):
    """管理员删除用户
    [BUG 修复 v2] log_audit 移出锁
    """
    u = get_user(username)
    if not u:
        return False, '用户不存在'
    if u.get('is_admin'):
        return False, '不能删除管理员账号'
    err_msg = None
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute('DELETE FROM users WHERE username=?', (username,))
        except Exception as e:
            err_msg = f'失败: {e}'
        finally:
            c.close()
    if err_msg:
        return False, err_msg
    try: log_audit(operator, 'delete_user', f'target={username}')
    except Exception: pass
    return True, '已删除'


def admin_reset_password(username, new_password, operator):
    """管理员重置用户密码
    [BUG 修复 v2] log_audit 移出锁
    """
    if not new_password or len(new_password) < 6:
        return False, '新密码至少 6 位'
    u = get_user(username)
    if not u:
        return False, '用户不存在'
    if u.get('is_admin') and u['username'] != operator:
        return False, '不能重置其他管理员的密码'
    pw_hash = hash_password(new_password)
    err_msg = None
    with _DB_LOCK:
        c = _conn()
        try:
            c.execute('UPDATE users SET password_hash=? WHERE username=?',
                      (pw_hash, username))
        except Exception as e:
            err_msg = f'失败: {e}'
        finally:
            c.close()
    if err_msg:
        return False, err_msg
    try: log_audit(operator, 'reset_password', f'target={username}')
    except Exception: pass
    return True, '密码已重置'


