# ----------------------------------------------------------------------------
#  自动登录 token (60 天 "记住我")
#
#  token 格式: base64(json({
#      'u': username,
#      'e': expiry_timestamp,
#      'd': device_fp,
#      's': hex(hmac_sha256(secret, u + e + d))
#  }))
#
#  关键: secret = SHA256(设备指纹 + APP_SECRET_SALT)
#  -> 把 session.dat 复制到别的电脑, 由于设备指纹不同, secret 不同, 验签必败
# ----------------------------------------------------------------------------
def _sign_token(payload: dict) -> str:
    msg = '{}|{}|{}'.format(
        payload.get('u', ''), payload.get('e', 0), payload.get('d', ''))
    sig = hmac.new(_token_secret_key(),
                   msg.encode('utf-8'),
                   hashlib.sha256).hexdigest()
    payload['s'] = sig
    return base64.urlsafe_b64encode(
        json.dumps(payload, separators=(',', ':')).encode('utf-8')
    ).decode('ascii')


def _verify_token(token_str: str):
    """验证 token, 通过则返回 payload, 否则返回 None。"""
    try:
        raw = base64.urlsafe_b64decode(token_str.encode('ascii')).decode('utf-8')
        payload = json.loads(raw)
        u = payload.get('u', ''); e = payload.get('e', 0)
        d = payload.get('d', ''); s = payload.get('s', '')
        if not (u and e and d and s): return None
        # 设备指纹必须匹配 (防止 session 文件被复制)
        if d != get_device_fingerprint(): return None
        # 必须未过期
        if int(time.time()) >= int(e): return None
        # 重新计算签名
        msg = f'{u}|{e}|{d}'
        expected = hmac.new(_token_secret_key(),
                            msg.encode('utf-8'),
                            hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, s): return None
        return payload
    except Exception:
        return None


def save_session(username):
    """登录成功后保存 60 天有效的自动登录 token。"""
    try:
        expiry = int(time.time()) + AUTO_LOGIN_DAYS * 86400
        token = _sign_token({
            'u': username,
            'e': expiry,
            'd': get_device_fingerprint(),
        })
        path = _session_path()
        with open(path, 'w', encoding='utf-8') as f:
            f.write(token)
        # Windows 文件权限: 仅当前用户可读
        try:
            if sys.platform.startswith('win'):
                # 用 icacls 限制权限 (尽力而为)
                subprocess.run(
                    ['icacls', path, '/inheritance:r',
                     f'/grant:r', f'{os.environ.get("USERNAME", "")}:F'],
                    capture_output=True, timeout=3,
                    creationflags=0x08000000)
        except Exception: pass
        return True
    except Exception:
        return False


def load_session():
    """读取并验证 session token。
    返回: 通过验证的用户名 (且账号在数据库中仍有效) 或 None。"""
    try:
        path = _session_path()
        if not os.path.isfile(path): return None
        with open(path, 'r', encoding='utf-8') as f:
            token_str = f.read().strip()
        if not token_str: return None
        payload = _verify_token(token_str)
        if not payload: return None
        # 验证用户在数据库中仍存在且未被禁用
        u = get_user(payload['u'])
        if not u: return None
        if u.get('status') != STATUS_ACTIVE: return None
        return u
    except Exception:
        return None


def clear_session():
    """清除 session token (退出登录)"""
    try:
        path = _session_path()
        if os.path.isfile(path):
            os.remove(path)
    except Exception: pass


# ----------------------------------------------------------------------------
#  注册接口 (区分普通用户和管理员)
# ----------------------------------------------------------------------------
def register_normal_user(username, password, *,
                         full_name='', contact='', note='',
                         invite_code=''):
    """注册普通用户 (默认强制要求邀请码, 由 INVITE_REQUIRED 控制)。
    返回 (ok, msg)。
    note 字段会自动追加邀请人标识, 便于追溯。
    """
    invite_identity = ''
    if INVITE_REQUIRED:
        ok, msg = verify_invite_code(invite_code)
        if not ok:
            return False, msg  # 错误信息直接返给 UI
        invite_identity = msg  # 验证通过时, msg 是被签名的身份标识
    else:
        # 即使关闭强制, 用户填了码也尝试解析记录
        if invite_code:
            ok, msg = verify_invite_code(invite_code)
            if ok:
                invite_identity = msg
    final_note = note or ''
    if invite_identity:
        final_note = (final_note + ' ' if final_note else '') \
                     + f'[invite:{invite_identity}]'
    ok, msg = create_user(username, password,
                          is_admin=False, status=STATUS_ACTIVE,
                          full_name=full_name, contact=contact,
                          note=final_note)
    if ok and invite_identity:
        try:
            log_audit(username, 'register_with_invite',
                      f'invite_identity={invite_identity}')
        except Exception: pass
    return ok, msg


def register_admin_user(username, password, admin_token, *,
                        full_name='', contact=''):
    """注册管理员账号。需要正确的 ADMIN_REG_TOKEN。"""
    if admin_token != ADMIN_REG_TOKEN:
        return False, '管理员注册口令错误'
    return create_user(username, password,
                       is_admin=True, status=STATUS_ACTIVE,
                       full_name=full_name, contact=contact,
                       note='[ADMIN]')


# ----------------------------------------------------------------------------
#  辅助: 格式化时间
# ----------------------------------------------------------------------------
def fmt_time(ts):
    if not ts: return ''
    try:
        return time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(int(ts)))
    except Exception:
        return str(ts)


