def _en_clean_spaces(x):
    try:
        x = str(x)
        x = x.replace('【', '[').replace('】', ']')
        x = x.replace('（', '(').replace('）', ')')
        x = x.replace('，', ', ').replace('。', '. ')
        x = x.replace('；', '; ').replace('：', ': ')
        x = x.replace('、', ', ').replace('“', '"').replace('”', '"')
        x = x.replace('‘', "'").replace('’', "'")
        x = re.sub(r'[ \t]+', ' ', x)
        x = re.sub(r' +\n', '\n', x)
        x = re.sub(r'\n +', '\n', x)
        x = re.sub(r' {2,}', ' ', x)
        return x.strip()
    except Exception:
        return x

def _en_lookup_exact(s):
    try:
        if s in _EN_EXTRA_MAP:
            return _EN_EXTRA_MAP[s]
        if s in _ZH2EN_UI:
            return _ZH2EN_UI[s]
        ns = re.sub(r'\s+', ' ', str(s).strip())
        for mp in (_EN_EXTRA_MAP, _ZH2EN_UI):
            for k, v in mp.items():
                if re.sub(r'\s+', ' ', str(k).strip()) == ns:
                    return v
    except Exception:
        pass
    return None

def _par_force_english_report(text):
    """Best-effort conversion of generated recommendation / AI panel text to English.

    It intentionally preserves numbers, units, Greek letters, brackets and file/model IDs,
    while removing any remaining CJK characters so the English build never displays
    Chinese-only analysis text.
    """
    if not isinstance(text, str):
        return text
    if _LANG != 'en':
        return text
    try:
        out = text
        # Longest phrases first: do not let short generic words break larger phrases.
        merged = {}
        try: merged.update(_ZH2EN_UI)
        except Exception: pass
        merged.update(_EN_EXTRA_MAP)
        for k in sorted(merged, key=lambda x: len(str(x)), reverse=True):
            if not isinstance(k, str) or not k:
                continue
            if len(k) < 2 and k not in out:
                continue
            v = str(merged[k])
            if k in out:
                out = out.replace(k, v)
        # Regex cleanups for common generated fragments.
        regex_pairs = [
            (r'CR\s*∈', 'CR ∈'),
            (r'←\s*被\s*([^\n]+?)\s*dominated', r'← dominated by \1'),
            (r'←\s*by\s*', '← dominated by '),
            (r'→\s*优先\s*', '→ prefer '),
            (r'→\s*仅\s*', '→ only '),
            (r'→\s*用', '→ use '),
            (r'CR\s*≤', 'CR ≤'),
            (r'CR\s*>', 'CR >'),
            (r'\s+×10⁻³\s+MPa', ' ×10⁻³ MPa'),
            (r'\s+%', '%'),
        ]
        for pat, rep in regex_pairs:
            out = re.sub(pat, rep, out)
        # Translate line-by-line again for any newly exposed fragments.
        lines = []
        for ln in out.splitlines():
            if _has_cjk(ln):
                ln2 = _LX(ln)
                if _has_cjk(ln2):
                    # Preserve numerical/scientific content, remove only remaining CJK.
                    ln2 = _LX_strip(ln2)
                ln = ln2
            lines.append(_en_clean_spaces(ln))
        out = '\n'.join(lines)
        # Final hard guarantee: no CJK remains in user-facing English report.
        out = re.sub(r'[\u4e00-\u9fff]+', '', out)
        out = re.sub(r'[。，“”‘’；、]+', ' ', out)
        out = re.sub(r' {2,}', ' ', out)
        out = re.sub(r'\n{3,}', '\n\n', out)
        return out.strip()
    except Exception:
        try:
            return _LX_strip(text)
        except Exception:
            return text



def _LX(s):
    if not isinstance(s, str) or not s:
        return s
    if _LANG != 'en':
        return s

    # 1) exact / normalized exact lookup
    hit = _en_lookup_exact(s)
    if isinstance(hit, str):
        return hit

    # 2) line-by-line conversion for Text-like content
    if '\n' in s:
        return '\n'.join(_LX(part) for part in s.split('\n'))

    # 3) already English
    try:
        if not _has_cjk(s):
            return s
    except Exception:
        return s

    out = s
    merged = {}
    try:
        merged.update(_ZH2EN_UI)
    except Exception:
        pass
    try:
        merged.update(_EN_EXTRA_MAP)
    except Exception:
        pass

    # 4) longest substring replacement: fixes strings such as "🔄  自适应"
    for k in sorted(merged, key=lambda x: len(str(x)), reverse=True):
        if not isinstance(k, str) or not k:
            continue
        if len(k) < 2:
            continue
        try:
            if k in out:
                out = out.replace(k, str(merged[k]))
        except Exception:
            pass

    # 5) common button pattern: preserve icon and translate the text part
    if _has_cjk(out):
        try:
            m = re.match(r'^([^\wA-Za-z0-9]*?)([\u4e00-\u9fff].*)$', out.strip())
            if m:
                icon = m.group(1).strip()
                rest = m.group(2).strip()
                rest_hit = _en_lookup_exact(rest)
                if isinstance(rest_hit, str) and rest_hit.strip():
                    return (icon + '  ' + rest_hit).strip()
        except Exception:
            pass

    # 6) if still has CJK, remove the remaining CJK while preserving numbers, σ, CR, units.
    if _has_cjk(out):
        out = _LX_strip(out)
    out = _en_clean_spaces(out)
    # Avoid falling back to Chinese for unknown pure-Chinese widget labels.
    if not out or _has_cjk(out):
        return 'Text'
    return out

def _LX_strip(s):
    out_chars = []
    for ch in s:
        cp = ord(ch)
        if 0x4e00 <= cp <= 0x9fff:
            continue
        if 0x3000 <= cp <= 0x303f:
            continue
        if 0xff00 <= cp <= 0xffef:
            if 0xff01 <= cp <= 0xff5e:
                out_chars.append(chr(cp - 0xfee0))
                continue
            continue
        out_chars.append(ch)
    out = ''.join(out_chars)
    out = re.sub(r'\s+', ' ', out).strip()
    return out


def _has_cjk(s):
    if not isinstance(s, str):
        return False
    for ch in s:
        if '\u4e00' <= ch <= '\u9fff':
            return True
    return False


_WIDGET_ORIG_TEXT = {}


def _wid_key(w):
    try:
        return str(w)
    except Exception:
        return None


def _restore_or_translate(widget, attr, current_value):
    """Bidirectional translation: store original ZH on first EN switch,
    write original back on ZH switch, write EN on EN switch."""
    key = _wid_key(widget)
    if key is None:
        return
    store = _WIDGET_ORIG_TEXT.setdefault(key, {})

    if _LANG == 'en':
        if _has_cjk(current_value):
            store[attr] = current_value
            tr = _LX(current_value)
            if (not isinstance(tr, str)) or (tr.strip() == ''):
                tr = 'Text'
            if isinstance(tr, str) and _has_cjk(tr):
                tr = _par_force_english_report(tr) or 'Text'
            if tr != current_value:
                try: widget.config(**{attr: tr})
                except Exception: pass
        else:
            if attr in store:
                tr = _LX(store[attr])
                if tr != current_value:
                    try: widget.config(**{attr: tr})
                    except Exception: pass
    else:
        if attr in store:
            orig = store[attr]
            if orig != current_value:
                try: widget.config(**{attr: orig})
                except Exception: pass


def _walk_translate_widgets(widget):
    try:
        children = widget.winfo_children()
    except Exception:
        return
    for child in children:
        # [V13] 复合按钮(m_make_btn)交其自带钩子整串翻译, 不让通用器拆碎
        if getattr(child, '_mbtn_is_button', False):
            try: child._mbtn_apply_lang()
            except Exception: pass
            continue
        # [V13] 标了 _no_lx 的控件跳过通用翻译, 但仍递归其子控件
        if getattr(child, '_no_lx', False):
            _walk_translate_widgets(child)
            continue
        try:
            keys = child.keys()
        except Exception:
            keys = []
        for attr in ('text', 'title', 'label'):
            if attr not in keys:
                continue
            try:
                cur = child.cget(attr)
            except Exception:
                continue
            if not isinstance(cur, str):
                continue
            _restore_or_translate(child, attr, cur)
        try:
            cls = child.winfo_class()
        except Exception:
            cls = ''

        if cls == 'Canvas':
            _translate_pill_button(child)

        if cls == 'Listbox':
            try:
                key = _wid_key(child)
                store = _WIDGET_ORIG_TEXT.setdefault(key, {})
                n = child.size()
                if _LANG == 'en':
                    if 'listbox_items' not in store:
                        store['listbox_items'] = [child.get(i) for i in range(n)]
                    items = store['listbox_items']
                    new_items = [_LX(it) if isinstance(it, str) else it
                                 for it in items]
                    if new_items != [child.get(i) for i in range(n)]:
                        try:
                            child.delete(0, 'end')
                            for it in new_items:
                                child.insert('end', it)
                        except Exception: pass
                else:
                    if 'listbox_items' in store:
                        items = store['listbox_items']
                        if items != [child.get(i) for i in range(n)]:
                            try:
                                child.delete(0, 'end')
                                for it in items:
                                    child.insert('end', it)
                            except Exception: pass
            except Exception: pass

        if cls in ('TCombobox', 'Combobox'):
            try:
                key = _wid_key(child)
                store = _WIDGET_ORIG_TEXT.setdefault(key, {})
                vals = child.cget('values')
                if isinstance(vals, (tuple, list)):
                    if _LANG == 'en':
                        if 'combo_values' not in store:
                            store['combo_values'] = tuple(vals)
                        new_vals = tuple(_LX(v) if isinstance(v, str) else v
                                         for v in store['combo_values'])
                        if tuple(vals) != new_vals:
                            child.config(values=new_vals)
                    else:
                        if 'combo_values' in store:
                            child.config(values=store['combo_values'])
            except Exception: pass

        if cls == 'Text':
            _translate_text_widget(child)

        _walk_translate_widgets(child)


def _translate_pill_button(cv):
    """Custom-canvas mode pill buttons. Their text lives on cv._label / cv._name."""
    try:
        key = _wid_key(cv)
        if key is None:
            return
        store = _WIDGET_ORIG_TEXT.setdefault(key, {})
        changed = False
        for attr in ('_label', '_name'):
            if not hasattr(cv, attr):
                continue
            cur = getattr(cv, attr)
            if not isinstance(cur, str):
                continue
            if _LANG == 'en':
                if _has_cjk(cur):
                    store[attr] = cur
                    new_v = _LX(cur)
                    if new_v != cur:
                        setattr(cv, attr, new_v)
                        changed = True
                elif attr in store:
                    new_v = _LX(store[attr])
                    if new_v != cur:
                        setattr(cv, attr, new_v)
                        changed = True
            else:
                if attr in store and store[attr] != cur:
                    setattr(cv, attr, store[attr])
                    changed = True
        if changed:
            try:
                redraw = getattr(cv, '_lx_redraw', None)
                if callable(redraw):
                    redraw()
            except Exception: pass
    except Exception: pass


def _translate_text_widget(tw):
    """tk.Text and ttk.Text content. Store original on first EN switch."""
    try:
        key = _wid_key(tw)
        store = _WIDGET_ORIG_TEXT.setdefault(key, {})
        try: state_orig = str(tw.cget('state'))
        except Exception: state_orig = 'normal'
        try: tw.config(state='normal')
        except Exception: pass

        if _LANG == 'en':
            if 'text_content' not in store:
                try:
                    store['text_content'] = tw.get('1.0', 'end-1c')
                except Exception:
                    store['text_content'] = ''
            orig = store['text_content']
            tr = _LX(orig) if orig else ''
            try:
                tw.delete('1.0', 'end')
                if tr:
                    tw.insert('1.0', tr)
            except Exception: pass
        else:
            if 'text_content' in store:
                try:
                    tw.delete('1.0', 'end')
                    tw.insert('1.0', store['text_content'])
                except Exception: pass

        try: tw.config(state=state_orig)
        except Exception: pass
    except Exception: pass


_MPL_ORIG = {}


def _mpl_obj_key(obj):
    try:
        return id(obj)
    except Exception:
        return None


def _mpl_translate_text(getter_setter_pair, key_suffix, obj):
    """getter_setter_pair: (lambda obj: obj.get_xxx(), lambda obj, v: obj.set_xxx(v))"""
    getter, setter = getter_setter_pair
    try:
        cur = getter(obj)
    except Exception:
        return
    if not isinstance(cur, str):
        return
    obj_id = _mpl_obj_key(obj)
    if obj_id is None:
        return
    store = _MPL_ORIG.setdefault(obj_id, {})

    if _LANG == 'en':
        if _has_cjk(cur):
            store[key_suffix] = cur
            try: setter(obj, _LX(cur))
            except Exception: pass
        elif key_suffix in store:
            try: setter(obj, _LX(store[key_suffix]))
            except Exception: pass
    else:
        if key_suffix in store and store[key_suffix] != cur:
            try: setter(obj, store[key_suffix])
            except Exception: pass


def _walk_translate_mpl_figures(root):
    try:
        children = root.winfo_children()
    except Exception:
        return
    for child in children:
        try:
            cls = child.winfo_class()
        except Exception:
            cls = ''
        if cls == 'Canvas':
            fig = None
            try:
                fig = getattr(child, 'figure', None)
                if fig is None:
                    mpl_canvas = getattr(child, '_mpl_canvas', None)
                    if mpl_canvas is not None:
                        fig = getattr(mpl_canvas, 'figure', None)
            except Exception: pass
            if fig is not None and hasattr(fig, 'axes'):
                try:
                    for ax in fig.axes:
                        try:
                            _mpl_translate_text(
                                (lambda a: a.get_title(),
                                 lambda a, v: a.set_title(v)),
                                'title', ax)
                            _mpl_translate_text(
                                (lambda a: a.get_xlabel(),
                                 lambda a, v: a.set_xlabel(v)),
                                'xlabel', ax)
                            _mpl_translate_text(
                                (lambda a: a.get_ylabel(),
                                 lambda a, v: a.set_ylabel(v)),
                                'ylabel', ax)
                            leg = ax.get_legend()
                            if leg is not None:
                                for txt in leg.get_texts():
                                    _mpl_translate_text(
                                        (lambda t: t.get_text(),
                                         lambda t, v: t.set_text(v)),
                                        'text', txt)
                            for txt in list(ax.texts):
                                _mpl_translate_text(
                                    (lambda t: t.get_text(),
                                     lambda t, v: t.set_text(v)),
                                    'text', txt)
                            try:
                                for tk_ in ax.get_xticklabels():
                                    _mpl_translate_text(
                                        (lambda t: t.get_text(),
                                         lambda t, v: t.set_text(v)),
                                        'text', tk_)
                                for tk_ in ax.get_yticklabels():
                                    _mpl_translate_text(
                                        (lambda t: t.get_text(),
                                         lambda t, v: t.set_text(v)),
                                        'text', tk_)
                            except Exception: pass
                        except Exception: pass
                    try:
                        sup = fig._suptitle
                        if sup is not None:
                            _mpl_translate_text(
                                (lambda t: t.get_text(),
                                 lambda t, v: t.set_text(v)),
                                'text', sup)
                    except Exception: pass
                    try: fig.canvas.draw_idle()
                    except Exception: pass
                except Exception: pass
        _walk_translate_mpl_figures(child)


_orig_showinfo    = messagebox.showinfo
_orig_showwarning = messagebox.showwarning
_orig_showerror   = messagebox.showerror
_orig_askyesno    = messagebox.askyesno
_orig_askokcancel = messagebox.askokcancel
_orig_askquestion = messagebox.askquestion

def _mb_translate(args, kwargs):
    new_args = []
    for a in args:
        if isinstance(a, str):
            new_args.append(_LX(a))
        else:
            new_args.append(a)
    if 'title' in kwargs and isinstance(kwargs['title'], str):
        kwargs['title'] = _LX(kwargs['title'])
    if 'message' in kwargs and isinstance(kwargs['message'], str):
        kwargs['message'] = _LX(kwargs['message'])
    if 'detail' in kwargs and isinstance(kwargs['detail'], str):
        kwargs['detail'] = _LX(kwargs['detail'])
    return tuple(new_args), kwargs

def _mb_showinfo(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_showinfo(*args, **kwargs)

def _mb_showwarning(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_showwarning(*args, **kwargs)

def _mb_showerror(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_showerror(*args, **kwargs)

def _mb_askyesno(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_askyesno(*args, **kwargs)

def _mb_askokcancel(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_askokcancel(*args, **kwargs)

def _mb_askquestion(*args, **kwargs):
    args, kwargs = _mb_translate(args, kwargs)
    return _orig_askquestion(*args, **kwargs)

messagebox.showinfo    = _mb_showinfo
messagebox.showwarning = _mb_showwarning
messagebox.showerror   = _mb_showerror
messagebox.askyesno    = _mb_askyesno
messagebox.askokcancel = _mb_askokcancel
messagebox.askquestion = _mb_askquestion


def _patch_tk_widget_init():
    classes = [tk.Label, tk.Button, tk.Checkbutton, tk.Radiobutton,
               tk.Menubutton, tk.LabelFrame, tk.Toplevel,
               ttk.Label, ttk.Button, ttk.Checkbutton, ttk.Radiobutton,
               ttk.Menubutton, ttk.LabelFrame, ttk.Notebook]
    for cls in classes:
        if getattr(cls, '_lx_patched', False):
            continue
        orig_init = cls.__init__
        def _make_new_init(orig_init):
            def _new_init(self, *args, **kwargs):
                orig_text = kwargs.get('text')
                orig_title = kwargs.get('title')
                if _LANG == 'en':
                    if isinstance(orig_text, str):
                        kwargs['text'] = _LX(orig_text)
                    if isinstance(orig_title, str):
                        kwargs['title'] = _LX(orig_title)
                ret = orig_init(self, *args, **kwargs)
                try:
                    key = _wid_key(self)
                    if key:
                        store = _WIDGET_ORIG_TEXT.setdefault(key, {})
                        if isinstance(orig_text, str) and _has_cjk(orig_text):
                            store['text'] = orig_text
                        if isinstance(orig_title, str) and _has_cjk(orig_title):
                            store['title'] = orig_title
                except Exception: pass
                return ret
            return _new_init
        cls.__init__ = _make_new_init(orig_init)
        cls._lx_patched = True

    for cls in [tk.Tk, tk.Toplevel]:
        if getattr(cls, '_lx_title_patched', False):
            continue
        orig_title = cls.title
        def _make_title(orig_title):
            def _new_title(self, string=None, *a, **kw):
                if string is not None and isinstance(string, str):
                    if _LANG == 'en':
                        try:
                            key = _wid_key(self)
                            if key and _has_cjk(string):
                                _WIDGET_ORIG_TEXT.setdefault(key, {})['_window_title'] = string
                        except Exception: pass
                        string = _LX(string)
                if string is None:
                    return orig_title(self)
                return orig_title(self, string, *a, **kw)
            return _new_title
        cls.title = _make_title(orig_title)
        cls._lx_title_patched = True

_patch_tk_widget_init()


# [EN_UI_V2] Translate labels created by widget.configure(text=...) after startup.
def _patch_tk_runtime_config_translation():
    classes = [tk.Label, tk.Button, tk.Checkbutton, tk.Radiobutton,
               tk.Menubutton, tk.LabelFrame, tk.Toplevel,
               ttk.Label, ttk.Button, ttk.Checkbutton, ttk.Radiobutton,
               ttk.Menubutton, ttk.LabelFrame]
    try:
        classes.append(ttk.Combobox)
    except Exception:
        pass
    for cls in classes:
        if getattr(cls, '_en_runtime_config_patched', False):
            continue
        orig_conf = cls.configure
        def _make_conf(orig_conf):
            def _new_conf(self, cnf=None, **kw):
                try:
                    if _LANG == 'en':
                        if isinstance(cnf, dict):
                            cnf = dict(cnf)
                            for attr in ('text', 'title', 'label'):
                                if attr in cnf and isinstance(cnf[attr], str):
                                    cnf[attr] = _LX(cnf[attr])
                            if 'values' in cnf and isinstance(cnf['values'], (list, tuple)):
                                cnf['values'] = tuple(_LX(v) if isinstance(v, str) else v
                                                      for v in cnf['values'])
                        for attr in ('text', 'title', 'label'):
                            if attr in kw and isinstance(kw[attr], str):
                                kw[attr] = _LX(kw[attr])
                        if 'values' in kw and isinstance(kw['values'], (list, tuple)):
                            kw['values'] = tuple(_LX(v) if isinstance(v, str) else v
                                                 for v in kw['values'])
                except Exception:
                    pass
                if cnf is None:
                    return orig_conf(self, **kw)
                return orig_conf(self, cnf, **kw)
            return _new_conf
        cls.configure = _make_conf(orig_conf)
        cls.config = cls.configure
        cls._en_runtime_config_patched = True

# [EN_UI_V2] tk.Menu labels are not normal widgets, so patch add_* calls too.
def _patch_tk_menu_label_translation():
    for name in ('add_command', 'add_cascade', 'add_checkbutton', 'add_radiobutton'):
        try:
            orig = getattr(tk.Menu, name)
        except Exception:
            continue
        flag = f'_en_{name}_patched'
        if getattr(tk.Menu, flag, False):
            continue
        def _make(orig):
            def _new(self, *args, **kwargs):
                try:
                    if _LANG == 'en' and isinstance(kwargs.get('label'), str):
                        kwargs['label'] = _LX(kwargs['label'])
                except Exception:
                    pass
                return orig(self, *args, **kwargs)
            return _new
        setattr(tk.Menu, name, _make(orig))
        setattr(tk.Menu, flag, True)

    for name in ('entryconfig', 'entryconfigure'):
        try:
            orig = getattr(tk.Menu, name)
        except Exception:
            continue
        flag = f'_en_{name}_patched'
        if getattr(tk.Menu, flag, False):
            continue
        def _make(orig):
            def _new(self, index, cnf=None, **kwargs):
                try:
                    if _LANG == 'en':
                        if isinstance(cnf, dict) and isinstance(cnf.get('label'), str):
                            cnf = dict(cnf)
                            cnf['label'] = _LX(cnf['label'])
                        if isinstance(kwargs.get('label'), str):
                            kwargs['label'] = _LX(kwargs['label'])
                except Exception:
                    pass
                if cnf is None:
                    return orig(self, index, **kwargs)
                return orig(self, index, cnf, **kwargs)
            return _new
        setattr(tk.Menu, name, _make(orig))
        setattr(tk.Menu, flag, True)

_patch_tk_runtime_config_translation()
_patch_tk_menu_label_translation()


def _patch_mpl_text_methods():
    try:
        from matplotlib.axes import Axes as _MplAxes
        from matplotlib.text import Text as _MplText
    except Exception:
        return
    if getattr(_MplAxes, '_lx_patched', False):
        return

    _orig_set_title  = _MplAxes.set_title
    _orig_set_xlabel = _MplAxes.set_xlabel
    _orig_set_ylabel = _MplAxes.set_ylabel
    _orig_text       = _MplAxes.text
    _orig_annotate   = _MplAxes.annotate
    _orig_legend     = _MplAxes.legend

    def _record_orig(obj, key, val):
        try:
            if isinstance(val, str) and _has_cjk(val):
                _MPL_ORIG.setdefault(_mpl_obj_key(obj), {})[key] = val
        except Exception: pass

    def _new_set_title(self, label='', *a, **kw):
        _record_orig(self, 'title', label)
        if _LANG == 'en' and isinstance(label, str):
            label = _LX(label)
        return _orig_set_title(self, label, *a, **kw)

    def _new_set_xlabel(self, xlabel='', *a, **kw):
        _record_orig(self, 'xlabel', xlabel)
        if _LANG == 'en' and isinstance(xlabel, str):
            xlabel = _LX(xlabel)
        return _orig_set_xlabel(self, xlabel, *a, **kw)

    def _new_set_ylabel(self, ylabel='', *a, **kw):
        _record_orig(self, 'ylabel', ylabel)
        if _LANG == 'en' and isinstance(ylabel, str):
            ylabel = _LX(ylabel)
        return _orig_set_ylabel(self, ylabel, *a, **kw)

    def _new_text(self, x, y, s='', *a, **kw):
        if _LANG == 'en' and isinstance(s, str):
            tobj = _orig_text(self, x, y, _LX(s), *a, **kw)
            try:
                if _has_cjk(s):
                    _MPL_ORIG.setdefault(_mpl_obj_key(tobj), {})['text'] = s
            except Exception: pass
            return tobj
        return _orig_text(self, x, y, s, *a, **kw)

    def _new_annotate(self, text='', *a, **kw):
        if _LANG == 'en' and isinstance(text, str):
            tobj = _orig_annotate(self, _LX(text), *a, **kw)
            try:
                if _has_cjk(text):
                    _MPL_ORIG.setdefault(_mpl_obj_key(tobj), {})['text'] = text
            except Exception: pass
            return tobj
        return _orig_annotate(self, text, *a, **kw)

    def _new_legend(self, *a, **kw):
        if _LANG == 'en':
            if 'labels' in kw and isinstance(kw['labels'], (list, tuple)):
                kw['labels'] = [_LX(x) if isinstance(x, str) else x
                                for x in kw['labels']]
            elif a and isinstance(a[0], (list, tuple)):
                a = list(a)
                a[0] = [_LX(x) if isinstance(x, str) else x for x in a[0]]
                a = tuple(a)
        leg = _orig_legend(self, *a, **kw)
        if _LANG == 'en' and leg is not None:
            try:
                for txt in leg.get_texts():
                    s = txt.get_text()
                    if isinstance(s, str) and _has_cjk(s):
                        _MPL_ORIG.setdefault(_mpl_obj_key(txt), {})['text'] = s
                        txt.set_text(_LX(s))
            except Exception: pass
        return leg

    _MplAxes.set_title  = _new_set_title
    _MplAxes.set_xlabel = _new_set_xlabel
    _MplAxes.set_ylabel = _new_set_ylabel
    _MplAxes.text       = _new_text
    _MplAxes.annotate   = _new_annotate
    _MplAxes.legend     = _new_legend
    _MplAxes._lx_patched = True

    if not getattr(_MplText, '_lx_patched', False):
        _orig_text_set_text = _MplText.set_text
        def _new_set_text(self, s):
            try:
                if isinstance(s, str) and _has_cjk(s):
                    _MPL_ORIG.setdefault(_mpl_obj_key(self), {})['text'] = s
            except Exception: pass
            if _LANG == 'en' and isinstance(s, str):
                s = _LX(s)
            return _orig_text_set_text(self, s)
        _MplText.set_text = _new_set_text
        _MplText._lx_patched = True


_patch_mpl_text_methods()

# ============================================================================
# [v15 路径打开修复] 精确打开/定位导出文件
# 目标: 无论路径是否包含中文、空格、括号、长路径, 都尽量精确定位到文件。
# Windows 优先调用 Shell32.SHOpenFolderAndSelectItems; 失败才退化 explorer。
# ============================================================================
def _norm_existing_path(path):
    try:
        p = os.path.abspath(os.path.normpath(str(path).strip().strip('"')))
    except Exception:
        p = str(path or '').strip().strip('"')
    return p


def _win_select_file(path):
    """Windows: 用 Shell API 精确选中文件。成功 True, 失败 False。"""
    if not sys.platform.startswith('win'):
        return False
    try:
        import ctypes
        p = _norm_existing_path(path)
        if not os.path.exists(p):
            return False
        shell32 = ctypes.windll.shell32
        ole32 = ctypes.windll.ole32
        pidl = ctypes.c_void_p()
        hr = shell32.SHParseDisplayName(
            ctypes.c_wchar_p(p), None, ctypes.byref(pidl), 0, None)
        if hr != 0 or not pidl:
            return False
        try:
            hr = shell32.SHOpenFolderAndSelectItems(pidl, 0, None, 0)
            return hr == 0
        finally:
            try:
                ole32.CoTaskMemFree(pidl)
            except Exception:
                pass
    except Exception:
        return False


def _open_path_in_file_manager(path, select=True):
    """打开文件所在位置; select=True 时尽量高亮文件本身。"""
    p = _norm_existing_path(path)
    folder = p if os.path.isdir(p) else os.path.dirname(p)
    if not folder:
        folder = os.path.expanduser('~')
    if sys.platform.startswith('win'):
        if select and os.path.isfile(p) and _win_select_file(p):
            return True
        try:
            if select and os.path.isfile(p):
                subprocess.Popen(['explorer.exe', f'/select,"{p}"'])
            else:
                os.startfile(folder)
            return True
        except Exception:
            try:
                os.startfile(folder)
                return True
            except Exception:
                raise
    elif sys.platform == 'darwin':
        if select and os.path.isfile(p):
            subprocess.Popen(['open', '-R', p])
        else:
            subprocess.Popen(['open', folder])
        return True
    else:
        subprocess.Popen(['xdg-open', folder])
        return True


def _open_file_with_default_app(path):
    """用系统默认应用直接打开文件。"""
    p = _norm_existing_path(path)
    if sys.platform.startswith('win'):
        os.startfile(p)
    elif sys.platform == 'darwin':
        subprocess.Popen(['open', p])
    else:
        subprocess.Popen(['xdg-open', p])
    return True


def imread_safe(p):
    try: return cv2.imdecode(np.fromfile(str(p), np.uint8), cv2.IMREAD_COLOR)
    except: return None

def auto_crop(img, gray):
    h, w = gray.shape; cm = gray.mean(axis=0)
    left = 0
    for c in range(min(w//3, 60)):
        if cm[c] > 80: left = c; break
    right = w
    for c in range(w-1, max(2*w//3, w-60), -1):
        if cm[c] > 80: right = c+1; break
    if left > 2 or right < w-2: img, gray, cx = img[:, left:right], gray[:, left:right], left
    else: cx = 0
    h, w = gray.shape
    if w < 80: return img, gray, cx
    q = w//4; el = np.mean(cv2.Canny(gray[:, :q], 50, 150))
    ec = np.mean(cv2.Canny(gray[:, q:3*q], 50, 150))
    if el < ec*1.5 or el < 10: return img, gray, cx
    cp = np.sum(gray < 200, axis=0); th = np.max(cp)*0.3; act = cp > th
    runs, s = [], None
    for i in range(w):
        if act[i] and s is None: s = i
        elif not act[i] and s is not None: runs.append((s, i, i-s)); s = None
    if s: runs.append((s, w, w-s))
    if len(runs) > 1:
        lo = max(runs, key=lambda r: r[2]); cx2 = max(0, lo[0]-5)
        return img[:, cx2:], gray[:, cx2:], cx+cx2
    return img, gray, cx

def segment_spine(gray):
    bl = cv2.GaussianBlur(gray, (5,5), 0)
    _, b1 = cv2.threshold(bl, 0, 255, cv2.THRESH_BINARY_INV+cv2.THRESH_OTSU)
    _, b2 = cv2.threshold(bl, 220, 255, cv2.THRESH_BINARY_INV)
    bn = cv2.bitwise_or(b1, b2)
    k = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5,5))
    bn = cv2.morphologyEx(bn, cv2.MORPH_CLOSE, k, iterations=3)
    bn = cv2.morphologyEx(bn, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3,3)))
    cs, _ = cv2.findContours(bn, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not cs: return bn
    m = np.zeros_like(bn); cv2.drawContours(m, [max(cs, key=cv2.contourArea)], -1, 255, -1)
    return m

def isolate_bodies(mask):
    h, w = mask.shape; dist = cv2.distanceTransform(mask, cv2.DIST_L2, 5); md = dist.max()
    if md < 2: return mask
    cdt = (dist >= md*0.40).astype(np.uint8)*255; bw = []
    for y in range(h):
        c = np.where(cdt[y]>0)[0]
        if len(c)>0: bw.append(c[-1]-c[0]+1)
    hw = max(3, int(np.median(bw)*0.55)) if bw else max(3, w//10)
    hk = cv2.getStructuringElement(cv2.MORPH_RECT, (hw, 1))
    ch = cv2.bitwise_and(cv2.dilate(cv2.erode(mask, hk), hk), mask)
    core = cv2.bitwise_and(cdt, ch)
    if core.sum() < mask.sum()*0.03: core = ch if ch.sum() > cdt.sum() else cdt
    for ks in [9,13,11,13,9]:
        ks2 = min(ks, max(3, min(h,w)//2*2+1))
        if ks2%2==0: ks2 += 1
        core = cv2.GaussianBlur(core, (ks2,ks2), 0)
        _, core = cv2.threshold(core, 127, 255, cv2.THRESH_BINARY)
    ro = np.where(np.sum(core>0, axis=1)>0)[0]
    if len(ro) < 10: return core
    rw, rc = [], []
    for y in ro:
        c = np.where(core[y]>0)[0]
        if len(c): rw.append(c[-1]-c[0]+1); rc.append((c[0]+c[-1])/2.0)
        else: rw.append(0); rc.append(w/2)
    rw, rc = np.array(rw, float), np.array(rc, float)
    km = min(51, len(rw)//2*2+1)
    if km >= 3: rw_s = medfilt(rw, km); rc_s = medfilt(rc, km)
    else: rw_s, rc_s = rw.copy(), rc.copy()
    win = min(51, len(rc_s)//2*2+1)
    if win >= 5: rc_s = savgol_filter(rc_s, win, 2); rw_s = savgol_filter(rw_s, win, 2)
    ref = np.zeros_like(core)
    for i, y in enumerate(ro):
        c_ = rc_s[i]; half = max(1, rw_s[i]/2)
        ref[y, max(0,int(c_-half)):min(w-1,int(c_+half))+1] = 255
    return cv2.bitwise_and(ref, mask)

def extract_midline(mask):
    h, _ = mask.shape; ys, xs = [], []
    for y in range(h):
        c = np.where(mask[y]>0)[0]
        if len(c)>1: ys.append(float(y)); xs.append(float(np.median(c)))
    return np.array(ys), np.array(xs)

def _adaptive_trim(ys, xs):
    n = len(ys)
    if n < 30: return ys, xs
    dx_ = np.gradient(xs); dy_ = np.gradient(ys)+1e-10; sl = dx_/dy_
    q1, q3 = n//4, 3*n//4; ma = np.median(np.abs(sl[q1:q3])); th = max(ma*5, 0.15)
    start = 0
    for i in range(n//4):
        if abs(sl[i]) < th: start = i; break
    else: start = n//10
    end = n-1
    for i in range(n-1, 3*n//4, -1):
        if abs(sl[i]) < th: end = i; break
    else: end = n-n//10
    mn = max(3, int(n*0.05)); mx = int(n*0.20)
    start = max(mn, min(start, mx)); end = min(n-mn, max(end, n-mx))
    if end-start < n//3: start = max(3, n//10); end = n-max(3, n//10)
    return ys[start:end+1], xs[start:end+1]

def smooth_midline(ys, xs):
    yt, xt = _adaptive_trim(ys, xs); n = len(yt)
    if n < 15: return yt, xt
    k = min(21, n//2*2+1)
    if k >= 3: xt = medfilt(xt, k)
    w = min(21, n//2*2+1)
    if w >= 5: xt = savgol_filter(xt, w, 3)
    try: sp = UnivariateSpline(yt, xt, k=3, s=n*0.5); return yt, sp(yt)
    except: return yt, gaussian_filter1d(xt, sigma=max(1, n*0.05))

def discretize(ys, xs, n=N_PTS):
    idx = np.linspace(0, len(ys)-1, n).astype(int); return ys[idx].copy(), xs[idx].copy()

def spline_fit(cy, cx, nd=700):

    cy = np.array(cy, dtype=float, copy=True)
    cx = np.array(cx, dtype=float, copy=True)
    for i in range(1, len(cy)):
        if cy[i] <= cy[i-1]: cy[i] = cy[i-1]+0.1
    try: cs = CubicSpline(cy, cx); yd = np.linspace(cy[0], cy[-1], nd); return yd, cs(yd), cs
    except: return cy, cx, None

def compute_slope(ys, xs):
    n = len(ys)
    if n < 10: return np.zeros(n)
    pad = max(int(n*0.08), 8)
    xp = np.concatenate([xs[pad:0:-1], xs, xs[-2:-pad-2:-1]])
    yp = np.concatenate([2*ys[0]-ys[pad:0:-1], ys, 2*ys[-1]-ys[-2:-pad-2:-1]])
    sr = np.gradient(xp)/(np.gradient(yp)+1e-10)
    return gaussian_filter1d(sr[pad:pad+n], sigma=max(n*0.08, 7))

def measure_cobb(ys, xs, slope):
    n = len(ys)
    if n < 20: return 0.0, {}
    t = max(n//3, 3)
    ct = np.polyfit(ys[:t], xs[:t], 1); cb = np.polyfit(ys[-t:], xs[-t:], 1)
    at = np.degrees(np.arctan(ct[0])); ab = np.degrees(np.arctan(cb[0]))
    cobb_tan = abs(at-ab)
    if cobb_tan > 90: cobb_tan = 180-cobb_tan
    bl = np.linspace(xs[0], xs[-1], n); dev = xs-bl
    apex = np.argmax(np.abs(dev)); mg = max(3, n//10)
    above = np.where((ys < ys[apex])&(ys > ys[mg]))[0]
    below = np.where((ys > ys[apex])&(ys < ys[-mg]))[0]
    upper, lower = mg, n-mg; cu, cl = ct, cb; cs_v = cobb_tan; cf = cobb_tan
    if len(above)>2 and len(below)>2:
        ui = np.argmax(np.abs(slope[above])); li = np.argmax(np.abs(slope[below]))
        upper = above[ui]; lower = below[li]
        au = np.degrees(np.arctan(slope[upper])); al = np.degrees(np.arctan(slope[lower]))
        cs_v = abs(au-al)
        if cs_v > 90: cs_v = 180-cs_v
        fl = max(int(n*0.14), 10)
        def _lf(idx):
            s, e = max(0, idx-fl//2), min(n, idx+fl//2)
            return np.polyfit(ys[s:e], xs[s:e], 1) if e-s >= 3 else [0,0]
        cu = _lf(upper); cl = _lf(lower)
        cf = abs(np.degrees(np.arctan(cu[0]))-np.degrees(np.arctan(cl[0])))
        if cf > 90: cf = 180-cf
    else:
        mid = n//2; cu = np.polyfit(ys[:mid], xs[:mid], 1); cl = np.polyfit(ys[mid:], xs[mid:], 1)
        cf = abs(np.degrees(np.arctan(cu[0]))-np.degrees(np.arctan(cl[0]))); cs_v = cf
        if cf > 90: cf = 180-cf
    final = sorted([cs_v, cf, cobb_tan])[1]
    if final > 90: final = 180-final
    return final, dict(upper=upper, lower=lower, apex=apex, slope=slope,
                       cu=cu, cl=cl, cobb_slope=cs_v, cobb_fit=cf, cobb_tan=cobb_tan)

class AutoResult:
    def __init__(self):
        self.img=self.gray=self.mask_raw=self.mask_core=None; self.crop_x=0
        self.ml_ys=self.ml_xs=None; self.cy=self.cx=self.dy=self.dx=None
        self.slope=None; self.cobb=0.0; self.info={}; self.ok=False

def analyze(path):
    r = AutoResult(); r.img = imread_safe(path)
    if r.img is None: return r
    r.gray = cv2.cvtColor(r.img, cv2.COLOR_BGR2GRAY)
    ic, gc, r.crop_x = auto_crop(r.img, r.gray)
    r.mask_raw = segment_spine(gc); r.mask_core = isolate_bodies(r.mask_raw)
    yf, xf = extract_midline(r.mask_core)
    if len(yf) < 30: return r
    ys, xs = smooth_midline(yf, xf); r.ml_ys, r.ml_xs = ys, xs
    r.cy, r.cx = discretize(ys, xs, N_PTS)
    r.dy, r.dx, _ = spline_fit(r.cy, r.cx)
    r.slope = compute_slope(r.dy, r.dx); r.cobb, r.info = measure_cobb(r.dy, r.dx, r.slope)
    r.ok = True; return r

def recompute(r):
    r.dy, r.dx, _ = spline_fit(r.cy, r.cx)
    r.slope = compute_slope(r.dy, r.dx); r.cobb, r.info = measure_cobb(r.dy, r.dx, r.slope)

class DraggableAnnotation:
    # ============================================================
    # [BUG 修复 v4] 全方位 None 检查 — 防止 ann 被销毁后访问其属性崩溃。
    # 此前 .ann.figure.canvas 在 ann 被 fig.clear() 后变 None,
    # 导致 render 中断, 用户感觉滚轮无响应。
    # ============================================================
    # [v9.9 增强] 加可选 on_release_callback(ann, dx_px, dy_px) — 用户
    #   拖动结束时调用, 用于持久化 "用户调整后的标签位置".
    # ============================================================
    def __init__(self, ann, on_release_callback=None):
        self.ann = ann
        self.press = None
        self._cp = self._cm = self._cr = None
        self._on_release = on_release_callback
        try:
            fig = getattr(ann, 'figure', None)
            if fig is None: return
            c = getattr(fig, 'canvas', None)
            if c is None: return
            self._cp = c.mpl_connect('button_press_event', self._p)
            self._cm = c.mpl_connect('motion_notify_event', self._m)
            self._cr = c.mpl_connect('button_release_event', self._r)
        except Exception: pass

    def _p(self, e):
        try:
            if e.button != 1 or e.inaxes is not self.ann.axes: return
            try: ok, _ = self.ann.contains(e)
            except Exception: ok = False
            if not ok: return
            try: x0, y0 = self.ann.get_position()
            except Exception: return
            self.press = (x0, y0, e.x, e.y)
        except Exception: pass

    def _m(self, e):
        if self.press is None or e.x is None: return
        try:
            x0, y0, xp, yp = self.press
            ax = getattr(self.ann, 'axes', None)
            if ax is None: return
            fig = getattr(self.ann, 'figure', None)
            if fig is None: return
            # ════════════════════════════════════════════════════════
            # [v9.10 BUG 修复] 拖动单位错误
            # --------------------------------------------------------
            # 旧代码: `(e.x - xp) / bb.width` 是 axes-fraction (0-1)
            #         但 ann.xytext 写入的是 'offset points' (因为
            #         textcoords='offset points'). 把 axes-fraction 加到
            #         points 上, 拖 100 px 只产生 0.07 points 的位移,
            #         视觉上几乎不变 — 用户感觉"拖不动".
            # 新代码: 直接像素增量转 offset points:
            #         dx_points = dx_pixels * 72 / dpi
            #         dpi=100 时 1 px ≈ 0.72 points, 拖动幅度与鼠标完全一致.
            # ════════════════════════════════════════════════════════
            try:
                _dpi = float(fig.dpi)
                if _dpi <= 0: _dpi = 100.0
            except Exception:
                _dpi = 100.0
            _pt_per_px = 72.0 / _dpi
            self.ann.set_position(
                (x0 + (e.x - xp) * _pt_per_px,
                 y0 + (e.y - yp) * _pt_per_px))
            canv = getattr(fig, 'canvas', None)
            if canv is None: return
            try: canv.draw_idle()
            except Exception: pass
        except Exception: pass

    def _r(self, e):
        # [v9.9] 拖动结束 -> 调 on_release_callback (持久化新位置)
        try:
            if self.press is not None and self._on_release is not None:
                try: self._on_release(self.ann)
                except Exception: pass
        except Exception: pass
        self.press = None

    def disconnect(self):
        # ============================================================
        # [BUG 修复 v4 - 关键! 用户反馈"VBL分布曲线滚轮调整无效, 必须点重置布局才变"]
        # 根因: render() 第一行就调 for d in self.draggers: d.disconnect()
        #       ann 被销毁后 self.ann.figure 变 None → 'NoneType' has no
        #       attribute 'canvas' → render() 中断 → 画面看不到变化。
        #       点击 "重置布局" 后, draggers 列表被重建为空, render 不再崩,
        #       才出现 "重置后能看到变化" 的现象。
        # 修复: 全方位 None 检查 + try/except 兜底, 保证 disconnect 永不抛异常。
        # ============================================================
        try:
            ann = self.ann
            if ann is None: return
            fig = getattr(ann, 'figure', None)
            if fig is None: return
            c = getattr(fig, 'canvas', None)
            if c is None: return
            for cid in (self._cp, self._cm, self._cr):
                if cid is None: continue
                try: c.mpl_disconnect(cid)
                except Exception: pass
        except Exception: pass

class ToolTip:
    """全自动板块的悬浮提示工具。
    [问题3 修复]: 同 M_ToolTip, 防止提示卡屏不消失。
    修复要点: 显示后启动 watchdog 周期检查鼠标真实位置,
    一旦离开 widget 范围立刻关闭提示。
    """
    def __init__(self, w, text, delay=600):
        self.w=w; self.text=text; self.delay=delay
        self._tip=None; self._aid=None; self._watchdog_aid=None
        w.bind('<Enter>', self._s); w.bind('<Leave>', self._h); w.bind('<ButtonPress>', self._h)
        w.bind('<FocusOut>', self._h); w.bind('<Unmap>', self._h); w.bind('<Destroy>', self._h)
    def _s(self, e=None): self._aid=self.w.after(self.delay, self._show)
    def _show(self):
        if self._tip: return
        try:
            if not self.w.winfo_exists(): return
        except Exception: return
        x=self.w.winfo_rootx()+self.w.winfo_width()//2
        y=self.w.winfo_rooty()+self.w.winfo_height()+4
        self._tip=tw=tk.Toplevel(self.w); tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}"); tw.configure(bg='#333')
        tk.Label(tw, text=self.text, bg='#333', fg='white',
                 font=('sans-serif',9), padx=8, pady=4, wraplength=_px(260)).pack()
        # 启动 watchdog 防止 tooltip 卡屏
        self._watchdog_aid = self.w.after(120, self._watchdog)
    def _watchdog(self):
        self._watchdog_aid = None
        if not self._tip: return
        try:
            if not self.w.winfo_exists():
                self._h(); return
            px = self.w.winfo_pointerx(); py = self.w.winfo_pointery()
            wx = self.w.winfo_rootx(); wy = self.w.winfo_rooty()
            ww = self.w.winfo_width(); wh = self.w.winfo_height()
            inside = (wx <= px <= wx + ww) and (wy <= py <= wy + wh)
            if not inside:
                self._h(); return
        except Exception:
            self._h(); return
        try: self._watchdog_aid = self.w.after(120, self._watchdog)
        except Exception: pass
    def _h(self, e=None):
        if self._aid:
            try: self.w.after_cancel(self._aid)
            except Exception: pass
            self._aid=None
        if self._watchdog_aid:
            try: self.w.after_cancel(self._watchdog_aid)
            except Exception: pass
            self._watchdog_aid=None
        if self._tip:
            try: self._tip.destroy()
            except Exception: pass
            self._tip=None

class PanelRenderer:
    PANEL_NAMES = ['解析Cobb角标注', '原始分割', '椎体核心', 'VBL斜率分布曲线']

    def __init__(self, parent, pid, font_scale=1.0, on_dblclick=None):
        self.parent=parent; self.pid=pid; self.font_scale=font_scale
        self.on_dblclick=on_dblclick
        self.fig = Figure(figsize=(4.5, 4.5), dpi=100, facecolor='white')
        self.ax = self.fig.add_subplot(111)
        self.canvas = FigureCanvasTkAgg(self.fig, master=parent)
        self.widget = self.canvas.get_tk_widget()
        self.widget.configure(bg='white', highlightthickness=0)
        self.legends=[]; self.draggers=[]; self.draggable_texts=[]; self.artist_sizes={}
        self.font_overrides = {}
        self._clickable_elements = []
        self._popup_win = None
        self._detail_debounce_id = None

        self._init_xlim = None
        self._init_ylim = None
        self._pan_start = None       # (x_pixel, y_pixel, xlim, ylim)
        # ============================================================
        # [BUG 加固] 预初始化 _last_res / _last_img 为 None。
        # 避免 reset_view / _on_scroll / _do_auto_font 等在第一次 render 之前
        # 被触发时, AttributeError 导致功能失效或卡顿。
        # ============================================================
        self._last_res = None
        self._last_img = None
        self.canvas.mpl_connect('button_press_event', self._on_click)
        self.canvas.mpl_connect('scroll_event', self._on_scroll)
        self.canvas.mpl_connect('motion_notify_event', self._on_motion_pan)
        self.canvas.mpl_connect('button_release_event', self._on_release_pan)
        self.widget.bind('<Double-Button-1>', self._on_dbl)

    def _on_dbl(self, e):
        if self.on_dblclick: self.on_dblclick(self.pid)

    def _on_click(self, event):


        if event.button == 3:

            self._pan_start = {
                'x': event.x, 'y': event.y,
                'xlim': self.ax.get_xlim() if self.ax else None,
                'ylim': self.ax.get_ylim() if self.ax else None,
                'moved': False,
                'inaxes': event.inaxes is not None,
            }

    def _on_motion_pan(self, event):


        if self._pan_start is None:
            return
        if event.x is None or event.y is None:
            return
        dx = event.x - self._pan_start['x']
        dy = event.y - self._pan_start['y']
        if abs(dx) + abs(dy) < 5 and not self._pan_start['moved']:
            return
        self._pan_start['moved'] = True

        try:
            inv = self.ax.transData.inverted()
            (x0, y0) = inv.transform((0, 0))
            (x1, y1) = inv.transform((dx, dy))
            ddx = x1 - x0
            ddy = y1 - y0
            xlim = self._pan_start['xlim']
            ylim = self._pan_start['ylim']
            if xlim and ylim:
                self.ax.set_xlim(xlim[0] - ddx, xlim[1] - ddx)

                self.ax.set_ylim(ylim[0] - ddy, ylim[1] - ddy)
                self.canvas.draw_idle()
        except Exception:
            pass

    def _on_release_pan(self, event):

        if self._pan_start is None:
            return
        was_moved = self._pan_start.get('moved', False)
        self._pan_start = None
        if event.button == 3 and not was_moved:

            try:
                self.open_detail_font_dialog()
            except Exception:
                pass

    def _on_scroll(self, event):
        # ============================================================
        # [BUG 修复 v3 - 2024Q3] 用户反馈"小窗大窗滚轮调整大小都不立即更新"
        #
        # 真正根因 (matplotlib + Tk backend 的固有特性):
        #   FigureCanvasTkAgg 的 draw() / draw_idle() 仅渲染到 Agg buffer,
        #   要让 Tk widget 显示出来, 必须调用 canvas.flush_events() 把
        #   buffer 推送到 Tk PhotoImage。原代码只调 draw_idle, 不调
        #   flush_events, 因此画面要等到下一次 mainloop idle 才更新 —
        #   用户感觉 "滚轮没反应、要等好久才动"。
        #
        # 另一根因 (pid=3 = VBL斜率分布曲线):
        #   _render_slope 是数据折线图, 大量 plot/scatter/fill_betweenx/
        #   axhline/grid/ticks/legend, 每次重建 figure 耗 50~200ms,
        #   并且 ax.set_position() 控制绘图区, 字号变化时绘图区被压缩,
        #   鼠标常落在 ax 区域外 -> event.inaxes is None -> 滚轮被吞。
        #
        # 修复 v3:
        #   1) pid=3 走独立路径, 不要求 event.inaxes (字号缩放和鼠标位置无关)
        #   2) 滚轮事件防重入 (_scroll_busy 标志), 避免 render 还没完又收新事件
        #   3) 关键: render 后调用 canvas.flush_events() 立即推送到 Tk
        #   4) 也调用 widget.update_idletasks() 让 Tk 立即处理重绘
        #   5) pid=0/1/2 同样补 flush_events, 视图缩放也立即可见
        # ============================================================

        # ─── pid=3 专用路径: 字号缩放, 不依赖 event.inaxes ───
        if self.pid == 3:
            # 防重入 (用户快速连续滚轮时, 前一次 render 还没完不要再触发)
            if getattr(self, '_scroll_busy', False):
                return
            try:
                # 滚轮方向 → 缩放系数
                if event.button == 'up':
                    scale = 1.2
                elif event.button == 'down':
                    scale = 1.0 / 1.2
                else:
                    return

                if (self._last_res is None
                        or not getattr(self._last_res, 'ok', False)):
                    return

                # 计算新字号 (硬限 0.35x ~ 4.0x)
                new_fs = self.font_scale * scale
                new_fs = max(0.35, min(4.0, new_fs))
                if abs(new_fs - self.font_scale) < 0.005:
                    return

                self._scroll_busy = True
                self.font_scale = new_fs
                try:
                    # 重渲染图 (重建整个 figure)
                    self.render(self._last_res, self._last_img)
                    # ===== 强制立即可见: draw + flush_events =====
                    # matplotlib Tk backend 的 draw_idle 是异步的,
                    # 必须 flush_events 才会把 Agg 渲染结果推送到 Tk。
                    try:
                        self.canvas.draw()
                    except Exception:
                        try: self.canvas.draw_idle()
                        except Exception: pass
                    try:
                        self.canvas.flush_events()
                    except Exception: pass
                    try:
                        self.widget.update_idletasks()
                    except Exception: pass
                finally:
                    self._scroll_busy = False
            except Exception:
                self._scroll_busy = False
            return

        # ─── pid=0/1/2 视图缩放路径 ───
        if self.ax is None or event.inaxes is None:
            return
        if event.xdata is None or event.ydata is None:
            return
        scale = 1.2 if event.button == 'up' else (1.0 / 1.2)
        try:
            xlim = self.ax.get_xlim()
            ylim = self.ax.get_ylim()
            xd, yd = event.xdata, event.ydata

            w = xlim[1] - xlim[0]
            if w == 0:
                return
            nw = w / scale
            rx = (xd - xlim[0]) / w
            new_xlim = (xd - nw * rx, xd + nw * (1 - rx))

            h = ylim[1] - ylim[0]
            if h == 0:
                return
            nh = h / scale
            ry = (yd - ylim[0]) / h
            new_ylim = (yd - nh * ry, yd + nh * (1 - ry))

            # ===== NaN/Inf 检测 =====
            import math as _m
            for v in (new_xlim[0], new_xlim[1], new_ylim[0], new_ylim[1]):
                if not _m.isfinite(v):
                    return

            # ===== 范围限制 (1/100x ~ 20x) =====
            ref_xlim = self._init_xlim if self._init_xlim else xlim
            ref_ylim = self._init_ylim if self._init_ylim else ylim
            ref_w = abs(ref_xlim[1] - ref_xlim[0])
            ref_h = abs(ref_ylim[1] - ref_ylim[0])
            new_w_r = abs(new_xlim[1] - new_xlim[0])
            new_h_r = abs(new_ylim[1] - new_ylim[0])
            MIN_RATIO = 1.0 / 100.0
            MAX_RATIO = 20.0
            if ref_w > 0 and ref_h > 0:
                if (new_w_r < ref_w * MIN_RATIO
                        or new_h_r < ref_h * MIN_RATIO):
                    return
                if (new_w_r > ref_w * MAX_RATIO
                        or new_h_r > ref_h * MAX_RATIO):
                    return

            self.ax.set_xlim(new_xlim)
            self.ax.set_ylim(new_ylim)
            # ===== 同步刷新 + flush_events 让 Tk 立即可见 =====
            try:
                self.canvas.draw()
            except Exception:
                try: self.canvas.draw_idle()
                except Exception: pass
            try:
                self.canvas.flush_events()
            except Exception: pass
        except Exception:
            pass

    def reset_view(self):
        # ============================================================
        # [BUG 加固] 用户在视图越界丢失后, 必须能用 🔍↺ 按钮恢复。
        #   原行为: 仅在 _init_xlim 已设置时恢复。若 _snapshot_initial_view
        #           尚未触发 (例如刚切换面板布局时), 按重置无效。
        #   修复  : fallback 到全量 render, 保证按下按钮一定有效果。
        # ============================================================
        try:
            if self._init_xlim and self._init_ylim:
                self.ax.set_xlim(self._init_xlim)
                self.ax.set_ylim(self._init_ylim)
                self.canvas.draw_idle()
                return
        except Exception:
            pass
        # Fallback: 用最后一次的 res / img 重新 render
        try:
            if (self._last_res is not None
                    and getattr(self._last_res, 'ok', False)):
                self.render(self._last_res, self._last_img)
                # 重新 snapshot, 下次重置就走快路径
                try:
                    self.widget.after(120, self._snapshot_initial_view)
                except Exception: pass
        except Exception:
            pass

    def _snapshot_initial_view(self):

        try:
            self._init_xlim = self.ax.get_xlim()
            self._init_ylim = self.ax.get_ylim()
        except Exception:
            self._init_xlim = self._init_ylim = None

    def bind_auto_font(self):

        self._last_auto_w = 0
        self._last_auto_h = 0
        self._auto_font_id = None
        self.widget.bind('<Configure>', self._on_widget_configure, add='+')

    def _on_widget_configure(self, _e=None):
        try:
            w = self.widget.winfo_width()
            h = self.widget.winfo_height()
        except Exception:
            return

        if (abs(w - self._last_auto_w) < 10
                and abs(h - self._last_auto_h) < 10):
            return
        self._last_auto_w = w
        self._last_auto_h = h
        # debounce 200 ms
        if self._auto_font_id:
            try: self.widget.after_cancel(self._auto_font_id)
            except Exception: pass
        self._auto_font_id = self.widget.after(200, self._do_auto_font)

    def _do_auto_font(self):

        self._auto_font_id = None
        if not hasattr(self, '_last_res') or self._last_res is None:
            return
        if not self._last_res.ok:
            return
        try:
            w = self.widget.winfo_width()
            h = self.widget.winfo_height()
        except Exception:
            return
        if w < 40 or h < 40:
            return


        ws = w / 380.0
        hs = h / 320.0
        scale = min(ws, hs)

        scale = max(0.55, min(2.2, scale))
        if abs(scale - self.font_scale) < 0.05:
            return
        self.font_scale = scale


        try:
            self.render(self._last_res, self._last_img)
        except Exception:
            pass

    def _update_clickable_regions(self):
        self._clickable_elements = []
        try:
            renderer = self.fig.canvas.get_renderer()
        except Exception:
            return
        for i, leg in enumerate(self.legends):
            key = f"leg_{self.pid}_{i}"
            name = "图例框" if self.pid != 3 else "顶部图例框"
            try:
                ext = leg.get_window_extent(renderer)
                self._clickable_elements.append((key, name,
                    (ext.x0, ext.y0, ext.x1, ext.y1)))
            except Exception:
                self._clickable_elements.append((key, name, None))
        for i, ann in enumerate(self.draggable_texts):
            key = f"ann_{self.pid}_{i}"
            name = "角度统计框"
            try:
                ext = ann.get_window_extent(renderer)
                self._clickable_elements.append((key, name,
                    (ext.x0, ext.y0, ext.x1, ext.y1)))
            except Exception:
                self._clickable_elements.append((key, name, None))
        if self.pid == 3:
            for attr, key, name in [
                ('xaxis', f"xlabel_{self.pid}", "X轴标签"),
                ('yaxis', f"ylabel_{self.pid}", "Y轴标签")]:
                try:
                    label_artist = getattr(self.ax, attr).label
                    ext = label_artist.get_window_extent(renderer)
                    self._clickable_elements.append((key, name,
                        (ext.x0, ext.y0, ext.x1, ext.y1)))
                except Exception:
                    self._clickable_elements.append((key, name, None))

    def _show_element_editor(self, key, name, event):
        if self._popup_win:
            try: self._popup_win.destroy()
            except: pass

        self._cleanup_popup_bind()
        fs = self.font_scale
        defaults = {
            f"leg_{self.pid}_0": 8.5*fs,
            f"ann_{self.pid}_0": 9*fs,
            f"xlabel_{self.pid}": 10*fs,
            f"ylabel_{self.pid}": 10*fs,
            f"tick_{self.pid}": 9*fs,
        }
        cur = self.font_overrides.get(key, int(defaults.get(key, 9*fs)))
        root_x = self.widget.winfo_rootx() + event.x + 20
        root_y = self.widget.winfo_rooty() + (self.widget.winfo_height() - event.y) - 30
        pop = tk.Toplevel(self.widget)
        pop.wm_overrideredirect(True)
        pop.geometry(f"+{root_x}+{root_y}")
        pop.configure(bg='white', highlightbackground=ACC, highlightthickness=2)
        self._popup_win = pop
        hdr = tk.Frame(pop, bg=ACC); hdr.pack(fill=tk.X)
        tk.Label(hdr, text=f" \u270f\ufe0f {name}", bg=ACC, fg='white',
                 font=(TK_ZH, _sz(9), 'bold'), anchor=tk.W).pack(side=tk.LEFT, padx=6, pady=3)
        tk.Button(hdr, text="\u2715", command=pop.destroy, bg=ACC, fg='white',
                  relief='flat', bd=0, font=(TK_ZH, _sz(9)), padx=6,
                  cursor='hand2').pack(side=tk.RIGHT)
        body = tk.Frame(pop, bg='white'); body.pack(padx=10, pady=8)
        lbl = tk.Label(body, text=f"{cur} pt", bg='white', fg=ACC,
                       font=(TK_EN, _sz(12), 'bold'))
        lbl.pack()
        sc = tk.Scale(body, from_=4, to=48, orient=tk.HORIZONTAL,
                      bg='white', troughcolor=BG_I, highlightthickness=0,
                      showvalue=False, length=_px(220),
                      command=lambda v, k=key, l=lbl: self._element_live(v, k, l))
        sc.set(cur); sc.pack(pady=4)

        top = self.widget.winfo_toplevel()
        def _check_focus(e):
            try:
                w = str(e.widget)
                if not w.startswith(str(pop)):
                    self._cleanup_popup_bind()
                    try: pop.destroy()
                    except: pass
                    self._popup_win = None
            except: pass
        try:
            self._popup_bind_id = top.bind('<Button-1>', _check_focus, add='+')
            self._popup_bind_top = top
        except: pass
        def _on_pop_destroy(_e=None):
            self._cleanup_popup_bind()
        pop.bind('<Destroy>', _on_pop_destroy)

    def _cleanup_popup_bind(self):

        bid = getattr(self, '_popup_bind_id', None)
        top = getattr(self, '_popup_bind_top', None)
        if bid and top:
            try: top.unbind('<Button-1>', bid)
            except: pass
        self._popup_bind_id = None
        self._popup_bind_top = None

    def _element_live(self, val, key, lbl):
        sz = int(float(val))
        self.font_overrides[key] = sz
        lbl.config(text=f"{sz} pt")
        if self._detail_debounce_id:
            try: self.widget.after_cancel(self._detail_debounce_id)
            except: pass
        self._detail_debounce_id = self.widget.after(150, self._do_live_redraw)

    def _do_live_redraw(self):
        self._detail_debounce_id = None
        if hasattr(self, '_last_res') and self._last_res is not None:
            self.render(self._last_res, self._last_img)

    def open_detail_font_dialog(self):
        win = tk.Toplevel(self.widget)
        win.title(f"\U0001f4dd 逐项编辑字号 — {self.PANEL_NAMES[self.pid]}")
        win.geometry(f"{_px(440)}x{_px(480)}"); win.configure(bg='white')
        win.transient(self.widget.winfo_toplevel())
        win.attributes('-topmost', True)

        def _close_detail():
            if self._detail_debounce_id:
                try: self.widget.after_cancel(self._detail_debounce_id)
                except: pass
                self._detail_debounce_id = None
            try: win.destroy()
            except: pass
        win.protocol("WM_DELETE_WINDOW", _close_detail)
        win.bind("<Escape>", lambda e: _close_detail())                    
        tk.Label(win, text="拖动任意滑块 → 图表即时更新",
                 bg='white', fg=ACC, font=(TK_ZH, _sz(11), 'bold')).pack(pady=(14, 4))
        tk.Label(win, text="每个元素独立控制，互不影响",
                 bg='white', fg=TG, font=(TK_ZH, _sz(9))).pack(pady=(0, 10))
        fs = self.font_scale
        if self.pid == 3:
            items = [
                ("\U0001f4ca 顶部图例框", f"leg_{self.pid}_0", 8.5*fs),
                ("\U0001f4d0 角度统计框", f"ann_{self.pid}_0", 9*fs),
                ("➡ X轴标签", f"xlabel_{self.pid}", 10*fs),
                ("⬆ Y轴标签", f"ylabel_{self.pid}", 10*fs),
                ("\U0001f522 刻度数字", f"tick_{self.pid}", 9*fs),
            ]
            has_tick_toggle = True
        else:
            items = [("\U0001f4ca 图例框", f"leg_{self.pid}_0", 8.5*fs)]
            if self.pid == 0:
                items.append(("\U0001f4cc 标题", f"title_{self.pid}", 14*fs))
            has_tick_toggle = False
        tk.Frame(win, bg=LC, height=1).pack(fill=tk.X, padx=20)
        sf = tk.Frame(win, bg='white')
        sf.pack(fill=tk.BOTH, expand=True, padx=20, pady=6)
        self._detail_debounce_id = None
        for name, key, default in items:
            cur = self.font_overrides.get(key, int(default))
            row = tk.Frame(sf, bg='white'); row.pack(fill=tk.X, pady=5)
            tk.Label(row, text=name, bg='white', fg=TW, font=(TK_ZH, _sz(10)),
                     width=12, anchor=tk.W).pack(side=tk.LEFT)
            lbl = tk.Label(row, text=f"{cur} pt", bg='white', fg=ACC,
                           font=(TK_EN, _sz(11), 'bold'), width=6)
            lbl.pack(side=tk.RIGHT)
            sc = tk.Scale(row, from_=4, to=48, orient=tk.HORIZONTAL,
                          bg='white', troughcolor=BG_I, highlightthickness=0,
                          showvalue=False, length=_px(200),
                          command=lambda v, k=key, l=lbl: self._detail_live(v, k, l))
            sc.set(cur); sc.pack(side=tk.RIGHT, padx=6)
        tk.Frame(win, bg=LC, height=1).pack(fill=tk.X, padx=20, pady=(6, 0))
        if has_tick_toggle:
            tf = tk.Frame(win, bg='white'); tf.pack(fill=tk.X, padx=24, pady=(8, 0))
            tick_adapt_key = f"tick_adapt_{self.pid}"
            cur_adapt = self.font_overrides.get(tick_adapt_key, 1)
            self._tick_adapt_var = tk.IntVar(value=cur_adapt)
            cb = tk.Checkbutton(tf, text="刻度个数随字体自适应（字体大→刻度少）",
                                variable=self._tick_adapt_var, bg='white', fg=TW,
                                font=(TK_ZH, _sz(9)), activebackground='white',
                                command=lambda: self._toggle_tick_adapt(tick_adapt_key))
            cb.pack(anchor=tk.W)
        tk.Label(win, text="提示：拖动滑块时图表自动刷新",
                 bg='white', fg=TD, font=(TK_ZH, _sz(9))).pack(pady=(6, 2))
        tk.Button(win, text="关闭", command=_close_detail, bg='#6B7280', fg='white',
                  relief='flat', font=(TK_ZH, _sz(10)), padx=16, pady=6,
                  cursor='hand2').pack(pady=8)

    def _detail_live(self, val, key, lbl):
        sz = int(float(val))
        self.font_overrides[key] = sz
        lbl.config(text=f"{sz} pt")
        if self._detail_debounce_id:
            try: self.widget.after_cancel(self._detail_debounce_id)
            except: pass
        self._detail_debounce_id = self.widget.after(
            150, self._detail_do_redraw)

    def _toggle_tick_adapt(self, key):
        self.font_overrides[key] = self._tick_adapt_var.get()
        self._detail_do_redraw()

    def _detail_do_redraw(self):
        # [BUG 加固 v4] 加 try 防止 render 内部任何异常被 Tk after 回调暴露出来
        self._detail_debounce_id = None
        try:
            if hasattr(self, '_last_res') and self._last_res is not None:
                self.render(self._last_res, self._last_img)
        except Exception: pass

    def render(self, res, img_display=None):
        # ============================================================
        # [BUG 修复 v4] render 第一行的 for d in self.draggers: d.disconnect()
        # 是用户报告"VBL滚轮无效"的真因。即使单个 dragger 抛 None 异常,
        # 整个 render 也会中断, 用户看到画面无变化。
        # 修复: 单个 disconnect 抛错也继续, 不影响整体 render 流程。
        # ============================================================
        self._last_res = res; self._last_img = img_display
        try: self.fig.clear()
        except Exception: pass
        try: self.ax = self.fig.add_subplot(111)
        except Exception: pass
        self.legends=[]
        # 安全释放所有旧 draggers, 单个失败不阻塞后续
        for d in self.draggers:
            try: d.disconnect()
            except Exception: pass
        self.draggers=[]; self.draggable_texts=[]
        if res is None or not res.ok:
            try:
                self.ax.text(0.5, 0.5, '等待数据……', ha='center', va='center',
                             transform=self.ax.transAxes, fontsize=12*self.font_scale,
                             color=TG, fontproperties=_zhfp(12*self.font_scale))
                self.ax.axis('off')
            except Exception: pass
            try: self.fig.tight_layout(pad=1.0)
            except: pass
            try: self.canvas.draw_idle()
            except Exception: pass
            return
        img_bgr = img_display if img_display is not None else res.img
        try:
            if self.pid==0: self._render_cobb(res, img_bgr)
            elif self.pid==1: self._render_raw(res, img_bgr)
            elif self.pid==2: self._render_core(res, img_bgr)
            elif self.pid==3: self._render_slope(res)
        except Exception as ex:
            # 子渲染函数崩了不应让整个 panel 卡死, 至少 fig 是空的
            try:
                import traceback as _tb
                _tb.print_exc()
            except Exception: pass
        try: self.canvas.draw_idle()
        except Exception: pass
        try: self.widget.after(100, self._update_clickable_regions)
        except Exception: pass

        try: self.widget.after(120, self._snapshot_initial_view)
        except Exception: pass

    def _legend_right(self, ax, handles, labels, default_fs, ncol=1,
                      leg_idx=0, top_margin=0.0):


        key = f"leg_{self.pid}_{leg_idx}"
        fs = self.font_overrides.get(key, default_fs)
        ratio = fs / max(default_fs, 1)
        leg = ax.legend(handles, labels,
                        loc='upper right',
                        fontsize=fs, framealpha=0.92, facecolor='white',
                        edgecolor='#CCC', borderpad=0.6, labelspacing=0.5,
                        handlelength=2.2*ratio, handletextpad=0.5,
                        markerscale=ratio, ncol=ncol,
                        prop=_zhfp(fs))
        leg.set_draggable(True)

        self.fig.subplots_adjust(
            left=0.0, right=1.0,
            top=1.0-top_margin, bottom=0.0)
        self.legends.append(leg)
        self.artist_sizes[id(leg)] = int(fs)
        return leg

    def _render_cobb(self, res, img_bgr):
        fs=self.font_scale; ax=self.ax; ih,iw=img_bgr.shape[:2]; cx=res.crop_x
        ax.imshow(cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB))
        ax.set_xlim(0, iw); ax.set_ylim(ih, 0)
        h_vbl, = ax.plot(res.dx+cx, res.dy, color=C_VBL, lw=2.0, alpha=0.94,
                          zorder=4, solid_capstyle='round')
        ax.scatter(res.cx+cx, res.cy, c=C_VBL, s=1.2, zorder=5, alpha=0.40)
        info=res.info; upper=info.get('upper',0); lower=info.get('lower',len(res.dy)-1)
        apex=info.get('apex',len(res.dy)//2)
        handles=[h_vbl]; labels=['椎体中心线 (VBL)']
        base_m=90*fs
        for idx,c,mk,sz,lb in [
            (upper,C_UIP,'s',base_m,'上拐点 (UIP)'),
            (lower,C_LIP,'s',base_m,'下拐点 (LIP)'),
            (apex,C_APEX,'D',base_m*1.18,'顶椎 (Apex)')]:
            if 0<=idx<len(res.dy):
                sc=ax.scatter(res.dx[idx]+cx, res.dy[idx], c=c, s=sz, marker=mk,
                              zorder=10, edgecolors='white', linewidths=1.2)
                handles.append(sc); labels.append(lb)
        cu_coef=info.get('cu',[0,0]); cl_coef=info.get('cl',[0,0]); L=ih*0.15
        for coef,idx,c in [(cu_coef,upper,C_UIP),(cl_coef,lower,C_LIP)]:
            if 0<=idx<len(res.dy):
                s=max(-10,min(10,coef[0])); px,py=res.dx[idx]+cx,res.dy[idx]
                nm=math.sqrt(1+s*s)
                x1=max(0,min(iw,px-L/nm)); y1=max(0,min(ih,py+s*L/nm))
                x2=max(0,min(iw,px+L/nm)); y2=max(0,min(ih,py-s*L/nm))
                if math.hypot(x2-x1,y2-y1)>3:
                    ax.plot([x1,x2],[y1,y2], c=c, lw=2.5, zorder=6, solid_capstyle='round')
        if (cu_coef is not None and cl_coef is not None and res.cobb>=1.0
                and 0<=upper<len(res.dy) and 0<=lower<len(res.dy)):
            from matplotlib.patches import Arc
            mid_x=(res.dx[upper]+res.dx[lower])/2+cx; mid_y=(res.dy[upper]+res.dy[lower])/2
            ar_r=ih*0.08; a1=math.degrees(math.atan(cu_coef[0])); a2=math.degrees(math.atan(cl_coef[0]))
            t1=-(max(a1,a2)+90); t2=-(min(a1,a2)+90)
            if 0.5<abs(t2-t1)<170:
                ax.add_patch(Arc((mid_x,mid_y), ar_r*2, ar_r*2, angle=0,
                                 theta1=t1, theta2=t2, color=C_APEX, lw=1.8, zorder=7))

        title_key = f"title_{self.pid}"
        title_fs = self.font_overrides.get(title_key, 14*fs)


        title_ann = ax.annotate(
            f'解析Cobb角 = {res.cobb:.1f}°',
            xy=(0.5, 0.97), xycoords='axes fraction',
            ha='center', va='top',
            fontsize=title_fs, fontweight='bold', color='#111',
            fontproperties=_zhfp(title_fs, 'bold'),
            bbox=dict(boxstyle='round,pad=0.5', fc='#FFFFFFE8',
                      edgecolor=ACC, lw=1.4), zorder=20)
        self.draggers.append(DraggableAnnotation(title_ann))
        self.draggable_texts.append(title_ann)
        self.artist_sizes[id(title_ann)] = int(title_fs)
        ax.axis('off')
        self._legend_right(ax, handles, labels, 8.5*fs)

    def _render_raw(self, res, img_bgr):
        fs=self.font_scale; ax=self.ax
        rgb=cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB); mh,mw=res.mask_raw.shape
        disp=rgb[:mh,:mw].copy(); ov=np.zeros_like(disp); ov[res.mask_raw>0]=[0,153,187]
        ax.imshow(cv2.addWeighted(disp, 0.55, ov, 0.45, 0))
        ih,iw=img_bgr.shape[:2]; ax.set_xlim(0,iw); ax.set_ylim(ih,0); ax.axis('off')
        proxy=[Line2D([0],[0], color='#0099BB', lw=6, solid_capstyle='butt')]
        self._legend_right(ax, proxy, ['脊柱原始分割掩膜'], 8.5*fs)

    def _render_core(self, res, img_bgr):
        fs=self.font_scale; ax=self.ax
        rgb=cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB); mh,mw=res.mask_core.shape
        disp=rgb[:mh,:mw].copy(); ov=np.zeros_like(disp); ov[res.mask_core>0]=[34,170,68]
        ax.imshow(cv2.addWeighted(disp, 0.50, ov, 0.50, 0))
        ih,iw=img_bgr.shape[:2]; ax.set_xlim(0,iw); ax.set_ylim(ih,0)
        ax.plot(res.dx, res.dy, color=C_VBL, lw=2.0, alpha=0.94, solid_capstyle='round')
        ax.scatter(res.cx, res.cy, c=C_UIP, s=1.2, zorder=5, alpha=0.7); ax.axis('off')
        proxy_vbl=Line2D([0],[0], color=C_VBL, lw=2.0, solid_capstyle='round')
        proxy_pts=Line2D([0],[0], color=C_UIP, lw=1.8, linestyle=':', dash_capstyle='round')
        self._legend_right(ax, [proxy_vbl, proxy_pts],
                           ['椎体中心线 (VBL)', '有限离散控制点集'], 8.5*fs)

    def _render_slope(self, res):
        fs=self.font_scale; ax=self.ax
        try: ax.set_box_aspect(1)
        except AttributeError: pass
        ax.set_facecolor('#FAFBFD')
        ax.plot(res.slope, res.dy, color='#BFCFDF', lw=3.5, alpha=0.25, zorder=2,
                solid_capstyle='round')
        ax.plot(res.slope, res.dy, color=C_SLOPE, lw=2.0, alpha=0.96, zorder=3,
                label='VBL斜率 dx/dy', solid_capstyle='round', solid_joinstyle='round')
        ax.fill_betweenx(res.dy, 0, res.slope, where=(res.slope>0),
                         alpha=0.12, color='#2E8B57', interpolate=True, zorder=1)
        ax.fill_betweenx(res.dy, 0, res.slope, where=(res.slope<0),
                         alpha=0.12, color='#CD5C5C', interpolate=True, zorder=1)
        info=res.info; upper=info.get('upper',0); lower=info.get('lower',len(res.dy)-1)
        apex=info.get('apex',len(res.dy)//2)
        base_m=90*fs
        for idx,c,mk,lb,m in [
            (upper,C_UIP,'s','UIP',base_m),
            (lower,C_LIP,'s','LIP',base_m),
            (apex,C_APEX,'D','Apex',base_m*1.2)]:
            if 0<=idx<len(res.dy):
                ax.scatter(res.slope[idx], res.dy[idx], c=c, s=m, marker=mk, zorder=8,
                           edgecolors='white', linewidths=1.2, label=lb)
                ax.axhline(y=res.dy[idx], color=c, ls='--', alpha=0.18, lw=0.6, zorder=1)
        ax.axvline(x=0, color='#999', ls='-', alpha=0.45, lw=0.8, zorder=2)
        ax.invert_yaxis()
        xlabel_fs = self.font_overrides.get(f"xlabel_{self.pid}", 10*fs)
        ylabel_fs = self.font_overrides.get(f"ylabel_{self.pid}", 10*fs)
        tick_fs = self.font_overrides.get(f"tick_{self.pid}", 9*fs)
        ax.set_xlabel('VBL斜率 dx/dy', fontsize=xlabel_fs, color='#333', labelpad=7,
                      fontproperties=_zhfp(xlabel_fs))
        ax.set_ylabel('VBL纵向采样位置 (px)', fontsize=ylabel_fs, color='#333', labelpad=7,
                      fontproperties=_zhfp(ylabel_fs))
        ax.grid(True, which='major', alpha=0.18, ls='-', color='#CCC', lw=0.6)
        ax.tick_params(axis='both', direction='in', colors='#444', labelsize=tick_fs,
                       length=4, width=0.7, which='major')
        tick_adapt = self.font_overrides.get(f"tick_adapt_{self.pid}", 1)
        if tick_adapt:
            from matplotlib.ticker import MaxNLocator
            base_tick_fs = 9 * fs
            nbins = max(3, int(8 - (tick_fs - base_tick_fs) * 0.4))
            ax.xaxis.set_major_locator(MaxNLocator(nbins=nbins))
            ax.yaxis.set_major_locator(MaxNLocator(nbins=nbins))
        for sp_ in ax.spines.values(): sp_.set_color('#BBB'); sp_.set_linewidth(0.8)
        default_leg_fs = 8.5*fs
        leg_key = f"leg_{self.pid}_0"
        leg_fs = self.font_overrides.get(leg_key, default_leg_fs)
        leg_ratio = leg_fs / max(default_leg_fs, 1)
        leg_h = 0.08 * max(1.0, leg_ratio)
        leg_ncol = 4 if leg_fs <= 12 else (3 if leg_fs <= 16 else 2)
        leg = ax.legend(loc='lower left', bbox_to_anchor=(0, 1.02, 1.0, leg_h),
                        mode='expand', ncol=leg_ncol,
                        fontsize=leg_fs, framealpha=0.94, facecolor='white',
                        edgecolor='#CCC', handlelength=1.5*leg_ratio,
                        handletextpad=0.3, markerscale=leg_ratio,
                        columnspacing=max(0.4, 0.8/leg_ratio), borderpad=0.4,
                        prop=_zhfp(leg_fs))
        leg.set_draggable(True); self.legends.append(leg)
        self.artist_sizes[id(leg)] = int(leg_fs)
        default_ann_fs = 9*fs
        ann_key = f"ann_{self.pid}_0"
        ann_fs = self.font_overrides.get(ann_key, default_ann_fs)
        ann_ratio = ann_fs / max(default_ann_fs, 1)
        ann_pad = 0.3 * max(1.0, ann_ratio)
        sv = info.get('cobb_slope',0); fv = info.get('cobb_fit',0)
        tv = info.get('cobb_tan',0); cv = res.cobb
        txt = (f"VBL-T：{sv:.1f}°\n"
               f"LLR：{fv:.1f}°\n"
               f"ER：{tv:.1f}°\n"
               f"──────\n"
               f"A-Cobb：{cv:.1f}°")
        ann_x, ann_y, ann_ha, ann_va = self._find_empty_corner(res.slope, res.dy)
        ann = ax.annotate(txt, xy=(ann_x, ann_y), xycoords='axes fraction',
                          ha=ann_ha, va=ann_va,
                          multialignment='center',
                          fontsize=ann_fs, color='#222',
                          fontproperties=_zhfp(ann_fs),
                          bbox=dict(boxstyle=f'round,pad={ann_pad:.2f}',
                                    fc='#FFFFFFEE', edgecolor='#AAA', lw=0.8))
        self.draggers.append(DraggableAnnotation(ann))
        self.draggable_texts.append(ann)
        self.artist_sizes[id(ann)] = int(ann_fs)
        top_margin = 0.84 - max(0, (leg_ratio - 1.0) * 0.06)
        self.fig.tight_layout(rect=[0, 0, 1, max(0.70, top_margin)], pad=1.2)


        if fs != 1.0:
            try:
                pos = self.ax.get_position()

                cx = pos.x0 + pos.width / 2
                cy = pos.y0 + pos.height / 2
                sc = max(0.4, min(2.0, fs))
                new_w = pos.width * sc
                new_h = pos.height * sc
                new_x = cx - new_w / 2
                new_y = cy - new_h / 2
                self.ax.set_position([new_x, new_y, new_w, new_h])
            except Exception:
                pass

    @staticmethod
    def _find_empty_corner(slope, dy):
        n = len(dy)
        if n < 5:
            return (0.97, 0.04, 'right', 'bottom')
        y_mid = (dy[0] + dy[-1]) / 2.0
        cnt = [0, 0, 0, 0]
        for i in range(n):
            is_left = (slope[i] < 0)
            is_top_data = (dy[i] < y_mid)
            if is_top_data and is_left:     cnt[0] += 1
            elif is_top_data and not is_left: cnt[1] += 1
            elif not is_top_data and is_left: cnt[2] += 1
            else:                            cnt[3] += 1
        best = cnt.index(min(cnt))
        margin = 0.06
        positions = [
            (margin, 1.0-margin, 'left',  'top'),
            (1.0-margin, 1.0-margin, 'right', 'top'),
            (margin, margin, 'left',  'bottom'),
            (1.0-margin, margin, 'right', 'bottom'),
        ]
        return positions[best]

class PanelWin(tk.Toplevel):
    def __init__(self, master, pid, res, img_display, outdir, fn,
                 src_panel=None, on_close_cb=None, win_key=None,
                 format_store=None):
        super().__init__(master); self.pid=pid; self.res=res; self.img_display=img_display
        self.outdir=outdir; self.fn=fn
        self._on_close_cb = on_close_cb
        self._win_key = win_key
        self._format_store = format_store
        self._default_fs = src_panel.font_scale if src_panel else 0.78
        stored = format_store.get(pid) if format_store else None
        if stored:
            init_fs = stored['font_scale']
            init_fo = dict(stored['font_overrides'])
        else:
            init_fs = self._default_fs
            init_fo = dict(src_panel.font_overrides) if src_panel and src_panel.font_overrides else {}
        self.title(f"面板 {pid+1} · {PanelRenderer.PANEL_NAMES[pid]} · {fn}")
        self.geometry(f"{_px(1180)}x{_px(920)}"); self.configure(bg='white'); self.minsize(_px(600), _px(500))
        tb=tk.Frame(self, bg='#F8F9FA', height=_px(48)); tb.pack(side=tk.TOP, fill=tk.X)
        tb.pack_propagate(False)
        tk.Label(tb, text=f"  {PanelRenderer.PANEL_NAMES[pid]} · {fn}", bg='#F8F9FA',
                 fg=TW, font=(TK_ZH, _sz(11),"bold")).pack(side=tk.LEFT, padx=12)
        tk.Button(tb, text="\U0001f4be 导出600dpi", command=self.export, bg=SUC, fg="white",
                  activebackground=SUC_H, relief="flat", bd=0, font=(TK_ZH, _sz(10),"bold"),
                  padx=14, pady=4, cursor="hand2").pack(side=tk.RIGHT, padx=8, pady=8)
        for t,c in [("A+",lambda:self._font(1.12)),("A-",lambda:self._font(0.9)),
                     ("↺ 重置",self._do_reset)]:
            tk.Button(tb, text=t, command=c, bg='white', relief='flat', padx=10,
                      font=(TK_ZH, _sz(10))).pack(side=tk.RIGHT, padx=2, pady=8)
        self.renderer=PanelRenderer(self, pid, font_scale=init_fs)
        self.renderer.font_overrides = init_fo
        self.renderer.widget.pack(fill=tk.BOTH, expand=True)
        nf=tk.Frame(self, bg='white'); nf.pack(side=tk.BOTTOM, fill=tk.X)
        try:
            self.nav=NavigationToolbar2Tk(self.renderer.canvas, nf, pack_toolbar=False)
            self.nav.update(); self.nav.pack(side=tk.LEFT, fill=tk.X, expand=True)
        except: pass
        self.after(120, lambda: self.renderer.render(self.res, self.img_display))
        self.protocol("WM_DELETE_WINDOW", self._on_close)
        self.bind("<Escape>", lambda e: self._on_close())                    

    def _save_to_store(self):
        if self._format_store is not None:
            self._format_store[self.pid] = {
                'font_scale': self.renderer.font_scale,
                'font_overrides': dict(self.renderer.font_overrides),
            }

    def _font(self, f):
        self.renderer.font_scale*=f
        self.renderer.render(self.res, self.img_display)
        self._save_to_store()

    def _do_reset(self):
        self.renderer.font_scale = self._default_fs
        self.renderer.artist_sizes = {}
        self.renderer.font_overrides = {}
        self.renderer.render(self.res, self.img_display)
        self._save_to_store()

    def _on_close(self):
        self._save_to_store()
        if self._on_close_cb and self._win_key:
            self._on_close_cb(self._win_key)

        try:
            plt.close(self.renderer.fig)
        except: pass
        try: self.destroy()
        except: pass

    def export(self):
        folder=filedialog.askdirectory(title="选择导出文件夹", initialdir=self.outdir or os.getcwd())
        if not folder: return
        nm=['AnalyticCobb','raw_seg','core','VBL_slope']
        out=os.path.join(folder, f"{os.path.splitext(self.fn)[0]}_{nm[self.pid]}_600dpi.png")
        try:
            self.renderer.fig.savefig(out, dpi=600, bbox_inches='tight', facecolor='white', edgecolor='none')
            messagebox.showinfo("导出成功", f"已保存：\n{out}")
        except Exception as ex: messagebox.showerror("导出失败", str(ex))

class AutoApp:
    def __init__(self, root):
        self.root=root
        self.root.title("🦴 脊柱曲率智能分析系统（解析Cobb法）· Analytic Cobb Method · V1")
        self.root.geometry(f"{_px(1860)}x{_px(1080)}"); self.root.minsize(_px(1280), _px(860)); self.root.configure(bg=BG)
        self.folder=self.outdir=self.cur=""; self.files=[]; self.res=AutoResult(); self.records=[]
        self.zoom=1.0; self.off=[0.0,0.0]; self._pan=None; self.drag=-1
        self.hist=[]; self.redo_stack=[]; self._tkimg=None
        self.brightness=0; self.contrast=1.0; self.panels=[]
        self.label_offsets={'cobb':[0,0],'upper':[0,0],'lower':[0,0],'apex':[0,0]}
        self._dragging_label_item=None; self._drag_lbl_key=None; self._drag_lbl_start=None
        self._pw_body=None; self._pw_center=None; self._pw_panels=None
        self._panel_wins = {}
        self._format_store = {}
        self.format_presets = {}
        self._pareto_ws = None
        self._pareto_state = None
        style=ttk.Style()
        try: style.theme_use('clam')
        except: pass
        style.configure('TPanedwindow', background=BG)
        style.configure('Sash', sashthickness=6, gripcount=12)
        self._build_ui(); self._bind()

    def _btn(self, p, t, cmd, bg_=ACC, hv=ACC_H, fsz=10, py=5, tip=None, fg="white"):
        b=tk.Button(p, text=t, command=cmd, bg=bg_, fg=fg, activebackground=hv,
                    activeforeground=fg, relief="flat", bd=0, cursor="hand2",
                    font=(TK_ZH,fsz), pady=py, padx=10)
        b.bind("<Enter>", lambda e,b=b,h=hv: b.config(bg=h))
        b.bind("<Leave>", lambda e,b=b,o=bg_: b.config(bg=o))
        if tip: ToolTip(b, tip)
        return b

    def _build_ui(self):


        body=ttk.PanedWindow(self.root, orient=tk.HORIZONTAL)
        body.pack(fill=tk.BOTH, expand=True, padx=5, pady=(3,3)); self._pw_body=body
        left=tk.Frame(body, bg='white'); body.add(left, weight=0); self._build_left(left)
        # 修复(问题3): 绑定 AutoApp 左栏自适应字体
        self._auto_left_col = left
        self.root.after(200, lambda: self._setup_auto_sidebar_autofont(left, ref_width=270))


        central_area = tk.Frame(body, bg=BG)
        body.add(central_area, weight=5)
        self._pw_center = None
        self._central_area = central_area

        central_head = tk.Frame(central_area, bg='white', height=_px(32))
        central_head.pack(side=tk.TOP, fill=tk.X)
        central_head.pack_propagate(False)
        self._central_head = central_head
        self._panel_layout_mode = '1u4d'
        self._build_panel_layout_menu(central_head)

        self._panel_area = tk.Frame(central_area, bg=BG)
        self._panel_area.pack(fill=tk.BOTH, expand=True)
        self._panel_area.bind('<Configure>', self._on_panel_area_configure,
                              add='+')
        self._pw_panels = None


        self._canvas_frame = None
        self.cv = None
        self._panel_frames = []
        self._panel_headers = []
        self._panel_title_labels = []
        self._panel_toolbar_buttons = []
        self._layout_frames = []

        self._apply_panel_layout(self._panel_layout_mode)
        right=tk.Frame(body, bg='white'); body.add(right, weight=0); self._build_right(right)
        # 修复(问题3): 绑定 AutoApp 右栏自适应字体
        self._auto_right_col = right
        self.root.after(200, lambda: self._setup_auto_sidebar_autofont(right, ref_width=300))
        self.root.after(50, self._init_pane_sizes)
        self.root.after(700, lambda: _global_autofit(self.root))
        self.root.after(1500, lambda: _global_autofit(self.root))

        sbar=tk.Frame(self.root, bg='white', height=_px(30))
        sbar.pack(side=tk.BOTTOM, fill=tk.X); sbar.pack_propagate(False)
        tk.Frame(self.root, bg=LC, height=1).pack(side=tk.BOTTOM, fill=tk.X)
        self.status=tk.Label(sbar, text="就绪", anchor=tk.W, bg='white', fg=TG,
                             font=(TK_ZH, _sz(9)), padx=14)
        self.status.pack(side=tk.LEFT, fill=tk.X, expand=True)
        zf=tk.Frame(sbar, bg='white')
        zf.pack(side=tk.RIGHT, padx=6)

        tk.Label(zf, text="缩放:", bg='white', fg=TD,
                 font=(TK_ZH, _sz(8))).pack(side=tk.LEFT, padx=(0, 2))
        self.lbl_zoom = tk.Label(zf, text="100%", bg='white', fg=ACC,
                                 font=(TK_EN, _sz(9), 'bold'))
        self.lbl_zoom.pack(side=tk.LEFT, padx=(0, 6))
        for zt, zv, ztip in [("50%",0.5,"缩放到50%"),("100%",1.0,"原始大小"),
                               ("200%",2.0,"放大200%"),("适配",None,"适配窗口(F)")]:
            zb=tk.Button(zf, text=zt, command=lambda v=zv: self._quick_zoom(v),
                         bg='white', fg=TG, relief='flat', bd=0, padx=4,
                         font=(TK_ZH, _sz(8)), cursor='hand2')
            zb.pack(side=tk.LEFT, padx=1); ToolTip(zb, ztip)
            zb.bind("<Enter>", lambda e,b=zb: b.config(fg=ACC))
            zb.bind("<Leave>", lambda e,b=zb: b.config(fg=TG))
        self.btn_copy=tk.Button(sbar, text="📋 复制Cobb", command=self._copy_cobb,
                                bg='white', fg=TG, relief='flat', bd=0, padx=6,
                                font=(TK_ZH, _sz(8)), cursor='hand2')
        self.btn_copy.pack(side=tk.RIGHT, padx=4); ToolTip(self.btn_copy,"复制当前A-Cobb角到剪贴板")
        self.progress=ttk.Progressbar(sbar, length=_px(160), mode='determinate')
        self.progress.pack(side=tk.RIGHT, padx=6, pady=5); self.progress.pack_forget()
        self.root.protocol("WM_DELETE_WINDOW", self._on_close)

    def _init_pane_sizes(self):

        try: self._pw_body.sashpos(0, _px(270))
        except: pass
        try: self._pw_body.sashpos(1, self._pw_body.winfo_width()-_px(270))
        except: pass


        try:
            h = self._left_pw.winfo_height()
            if h > 200:
                # [问题4 修复] 调整初始切分位置, 让批量操作栏更高,
                # 使 "Pareto 耦合分析" (第 5 个按钮) 在初始布局可见。
                # 原: 0.19 / 0.38 / 0.62 / 0.86
                # 新: 0.10 / 0.24 / 0.42 / 0.86
                # 区段占比变化:
                #   list_frame  19% → 10% (图片列表缩小)
                #   nav_box     19% → 14% (文件导航略缩小并上移)
                #   view_box    24% → 18% (画布视图略缩小并上移)
                #   batch_box   24% → 44% (批量操作显著增大, 5 个按钮全部可见)
                #   hlp_box     14% → 14% (布局帮助保持不变)
                self._left_pw.sashpos(0, int(h * 0.10))
                self._left_pw.sashpos(1, int(h * 0.24))
                self._left_pw.sashpos(2, int(h * 0.42))
                self._left_pw.sashpos(3, int(h * 0.86))
        except Exception:
            pass

        try:
            h = self._right_pw.winfo_height()
            if h > 200:

                self._right_pw.sashpos(0, int(h * 0.14))
                self._right_pw.sashpos(1, int(h * 0.36))
                self._right_pw.sashpos(2, int(h * 0.72))
        except Exception:
            pass

    def reset_layout(self):
        if getattr(self, '_pareto_ws', None) is not None:
            try:
                self._pareto_ws.reset_layout()
                self._st("✅ 耦合工作区布局已重置")
            except Exception:
                pass
            return
        self._init_pane_sizes()

        self._apply_panel_layout('1u4d')
        self._st("✅ 布局已重置")


    PANEL_LAYOUT_MODES = [
        ('1u4d',        '上 1  下 4',      None),
        ('2u3d',        '上 2  下 3',      None),
        ('3u2d',        '上 3  下 2',      None),
        ('4u1d',        '上 4  下 1',      None),
        ('left_right',  '左 画布  右 4',   None),
        ('canvas_only', '仅显示画布',      None),
        ('panels_only', '仅显示 4 面板',   None),
        ('auto',        '自适应',          None),
        ('pareto',      '🎯 Pareto 耦合分析模式', None),
    ]

    def _build_panel_layout_menu(self, parent):

        mbtn = tk.Menubutton(
            parent, text="🗂 工作区布局 ▾", bg='#7C3AED', fg='white',
            activebackground='#6D28D9', activeforeground='white',
            relief='flat', bd=0, font=(TK_ZH, _sz(9), 'bold'),
            padx=12, pady=2, cursor='hand2')
        m = tk.Menu(mbtn, tearoff=0, bg='white', fg=TW,
                    font=(TK_ZH, _sz(10)))
        for key, label, _ in self.PANEL_LAYOUT_MODES:
            m.add_command(
                label=f"  {label}",
                command=lambda k=key: self._apply_panel_layout(k))
        mbtn.configure(menu=m)
        mbtn.pack(side=tk.RIGHT, padx=6)
        ToolTip(mbtn, "切换 画布 + 4 分析面板 的排列方式")


    def _create_canvas_cell(self, parent):

        cf = tk.Frame(parent, bg='white', bd=1, relief='solid',
                      highlightbackground=LC)
        cv = tk.Canvas(cf, bg='white', highlightthickness=0,
                       cursor="crosshair")
        cv.configure(width=1, height=1)
        cv.pack(fill=tk.BOTH, expand=True)
        for ev, fn in [("<ButtonPress-1>", self._ld),
                       ("<B1-Motion>", self._lm),
                       ("<ButtonRelease-1>", self._lu),
                       ("<ButtonPress-3>", self._ps),
                       ("<B3-Motion>", self._pm),
                       ("<ButtonRelease-3>", self._pe),
                       ("<ButtonPress-2>", self._ps),
                       ("<B2-Motion>", self._pm),
                       ("<ButtonRelease-2>", self._pe),
                       ("<MouseWheel>", self._wh),
                       ("<Configure>", self._on_canvas_configure)]:
            cv.bind(ev, fn)
        cv.bind("<Button-4>", lambda e: self._wh(e, 120))
        cv.bind("<Button-5>", lambda e: self._wh(e, -120))
        self.cv = cv
        self._canvas_frame = cf
        return cf

    def _create_panel_cell(self, parent, i, restore_state=None):

        circled = ['①', '②', '③', '④']
        pf = tk.Frame(parent, bg='white', bd=1, relief='solid',
                      highlightbackground=LC)
        pth = tk.Frame(pf, bg=BG_H, height=_px(26))
        pth.pack(side=tk.TOP, fill=tk.X)
        pth.pack_propagate(False)

        tk.Frame(pf, bg=LC, height=1).pack(side=tk.TOP, fill=tk.X)
        ttl = tk.Label(pth, text=f"  {circled[i]}  {PanelRenderer.PANEL_NAMES[i]}",
                       bg=BG_H, fg=TW, font=(TK_ZH, _sz(9), 'bold'))
        ttl.pack(side=tk.LEFT)
        btns_here = []
        for t_, cb_, tip_ in [
                ("\U0001f4be", lambda ii=i: self._panel_export(ii), "导出600dpi"),
                ("\U0001f50d", lambda ii=i: self._open_panel(ii), "放大"),
                ("📝", lambda ii=i: self._panel_detail_font(ii), "逐项编辑字号"),
                ("\U0001f504全部", lambda ii=i: self._apply_to_all(ii), "将当前格式应用到所有图片"),
                ("\U0001f4be存", lambda ii=i: self._save_preset(ii), "保存格式预设"),
                ("\U0001f4c2用", lambda ii=i: self._apply_preset(ii), "加载格式预设"),
                ("🔍↺", lambda ii=i: self._panel_reset_view(ii), "重置缩放/平移视图"),
                ("↺", lambda ii=i: self._panel_reset(ii), "重置字号等格式"),
                ("A+", lambda ii=i: self._panel_font(ii, 1.15), "全局字号+"),
                ("A-", lambda ii=i: self._panel_font(ii, 0.87), "全局字号-"),
        ]:
            b = tk.Button(pth, text=t_, command=cb_, bg=BG_H, relief='flat',
                          bd=0, padx=5, pady=0, cursor='hand2',
                          font=(TK_ZH, _sz(8)))
            b.pack(side=tk.RIGHT, padx=1)
            b.bind("<Enter>", lambda e, b=b: b.config(bg='white'))
            b.bind("<Leave>", lambda e, b=b: b.config(bg=BG_H))
            ToolTip(b, tip_)
            btns_here.append(b)

        init_fs = 1.0
        init_fo = {}
        if restore_state:
            init_fs = restore_state.get('font_scale', 1.0)
            init_fo = dict(restore_state.get('font_overrides', {}))
        r = PanelRenderer(pf, i, font_scale=init_fs,
                          on_dblclick=self._open_panel)
        r.font_overrides = init_fo
        r.widget.pack(fill=tk.BOTH, expand=True)
        r.widget.configure(width=1, height=1)
        r.bind_auto_font()
        self.panels.append(r)
        self._panel_frames.append(pf)
        self._panel_headers.append(pth)
        self._panel_title_labels.append(ttl)
        self._panel_toolbar_buttons.append(btns_here)
        return pf

    def _destroy_cells(self):


        cv_state = None
        if getattr(self, 'cv', None):
            try:
                cv_state = {
                    'zoom': self.zoom,
                    'off': list(self.off),
                }
            except Exception:
                pass
        panel_states = [None, None, None, None]
        for p in getattr(self, 'panels', []):
            try:
                panel_states[p.pid] = {
                    'font_scale': p.font_scale,
                    'font_overrides': dict(p.font_overrides),
                }
            except Exception:
                pass

        for p in self.panels:
            try: plt.close(p.fig)
            except Exception: pass

        if getattr(self, '_canvas_frame', None):
            try: self._canvas_frame.destroy()
            except Exception: pass
        self._canvas_frame = None
        self.cv = None
        for pf in self._panel_frames:
            try: pf.destroy()
            except Exception: pass
        self._panel_frames = []
        self._panel_headers = []
        self._panel_title_labels = []
        self._panel_toolbar_buttons = []
        self.panels = []

        for f in getattr(self, '_layout_frames', []):
            try: f.destroy()
            except Exception: pass
        self._layout_frames = []
        return cv_state, panel_states

    def _restore_state_and_render(self, cv_state, panel_states):

        if cv_state and self.cv:
            try:
                self.zoom = cv_state['zoom']
                self.off = list(cv_state['off'])
            except Exception:
                pass
        # refresh main canvas
        try:
            self.refresh()
        except Exception:
            pass

        if self.res.ok:
            img = self._get_display_img()
            for p in self.panels:
                try:
                    p.render(self.res, img)
                except Exception as _e_render:
                    # 不再静默吞掉错误,打印详细信息便于排查
                    import traceback
                    print(f'[Panel {p.pid}] render error: {_e_render}')
                    traceback.print_exc()
            # 修复: 延迟重试一次,确保 widget 已完成布局后所有 panel 都能画出来
            # (解决"窗口1和4空白"问题: 某些情况下 matplotlib 在 widget 尺寸为
            #  极小时第一次 draw 会被丢弃,需要在尺寸稳定后再 draw 一次)
            def _has_axis_content(ax):
                try:
                    return bool(ax.lines or ax.collections or
                                ax.images or ax.patches or ax.texts)
                except Exception:
                    return True

            def _force_redraw_all():
                try:
                    img2 = self._get_display_img()
                    for p in self.panels:
                        try:
                            # 检测 figure 是否真的画上了内容
                            empty = (not p.fig.axes or
                                     not any(_has_axis_content(ax)
                                             for ax in p.fig.axes))
                            if empty:
                                # 空的 -> 重新 render
                                p.render(self.res, img2)
                            else:
                                p.canvas.draw_idle()
                        except Exception: pass
                except Exception: pass
            try: self.root.after(180, _force_redraw_all)
            except Exception: pass
            try: self.root.after(450, _force_redraw_all)
            except Exception: pass

    def _apply_panel_layout(self, mode):


        if mode == 'auto':
            if getattr(self, '_pareto_ws', None) is not None:
                try:
                    self._pareto_ws.redistribute_all()
                    self._st('✅ 耦合分析两栏卡片已均匀平铺')
                except Exception:
                    pass
                return
            try:
                w = max(self._panel_area.winfo_width(), 1)
                h = max(self._panel_area.winfo_height(), 1)
                ratio = w / max(h, 1)
                if ratio > 2.0:
                    mode = 'left_right'
                elif ratio > 1.3:
                    mode = '1u4d'
                else:
                    mode = '3u2d'
            except Exception:
                mode = '1u4d'
        self._panel_layout_mode = mode

        if getattr(self, '_pareto_ws', None) is not None:
            try:
                self._pareto_state = self._pareto_ws.to_state()
            except Exception:
                pass
            try:
                self._pareto_ws.unmount_ext_toolbar()
            except Exception: pass
            try:
                self._pareto_ws.destroy()
            except Exception: pass
            self._pareto_ws = None

        cv_state, panel_states = self._destroy_cells()

        pa = self._panel_area


        if mode == '1u4d':

            outer = ttk.PanedWindow(pa, orient=tk.VERTICAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)

            top = tk.Frame(outer, bg='white')
            outer.add(top, weight=500)
            cf = self._create_canvas_cell(top)
            cf.pack(fill=tk.BOTH, expand=True)

            bot = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(bot, weight=200)
            for i in range(4):
                ph = tk.Frame(bot, bg='white')
                bot.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [bot]
        elif mode == '2u3d':

            outer = ttk.PanedWindow(pa, orient=tk.VERTICAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)

            top = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(top, weight=500)
            c_host = tk.Frame(top, bg='white')
            top.add(c_host, weight=2)
            cf = self._create_canvas_cell(c_host)
            cf.pack(fill=tk.BOTH, expand=True)
            p0_host = tk.Frame(top, bg='white')
            top.add(p0_host, weight=1)
            pf0 = self._create_panel_cell(p0_host, 0,
                                          restore_state=panel_states[0])
            pf0.pack(fill=tk.BOTH, expand=True)

            bot = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(bot, weight=200)
            for i in [1, 2, 3]:
                ph = tk.Frame(bot, bg='white')
                bot.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [top, bot]
        elif mode == '3u2d':

            outer = ttk.PanedWindow(pa, orient=tk.VERTICAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)
            top = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(top, weight=500)
            c_host = tk.Frame(top, bg='white')
            top.add(c_host, weight=2)
            cf = self._create_canvas_cell(c_host)
            cf.pack(fill=tk.BOTH, expand=True)
            for i in [0, 1]:
                ph = tk.Frame(top, bg='white')
                top.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            bot = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(bot, weight=200)
            for i in [2, 3]:
                ph = tk.Frame(bot, bg='white')
                bot.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [top, bot]
        elif mode == '4u1d':

            outer = ttk.PanedWindow(pa, orient=tk.VERTICAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)
            top = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(top, weight=500)
            c_host = tk.Frame(top, bg='white')
            top.add(c_host, weight=2)
            cf = self._create_canvas_cell(c_host)
            cf.pack(fill=tk.BOTH, expand=True)
            for i in [0, 1, 2]:
                ph = tk.Frame(top, bg='white')
                top.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            bot_host = tk.Frame(outer, bg='white')
            outer.add(bot_host, weight=200)
            pf3 = self._create_panel_cell(bot_host, 3,
                                          restore_state=panel_states[3])
            pf3.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [top]
        elif mode == 'left_right':

            outer = ttk.PanedWindow(pa, orient=tk.HORIZONTAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)
            c_host = tk.Frame(outer, bg='white')
            outer.add(c_host, weight=600)
            cf = self._create_canvas_cell(c_host)
            cf.pack(fill=tk.BOTH, expand=True)
            right = ttk.PanedWindow(outer, orient=tk.VERTICAL)
            outer.add(right, weight=300)
            for i in range(4):
                ph = tk.Frame(right, bg='white')
                right.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [right]
        elif mode == 'canvas_only':

            host = tk.Frame(pa, bg='white')
            host.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(host)
            cf = self._create_canvas_cell(host)
            cf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = []
        elif mode == 'panels_only':

            outer = ttk.PanedWindow(pa, orient=tk.VERTICAL)
            outer.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(outer)
            top = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(top, weight=1)
            for i in [0, 1]:
                ph = tk.Frame(top, bg='white')
                top.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            bot = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
            outer.add(bot, weight=1)
            for i in [2, 3]:
                ph = tk.Frame(bot, bg='white')
                bot.add(ph, weight=1)
                pf = self._create_panel_cell(ph, i,
                                             restore_state=panel_states[i])
                pf.pack(fill=tk.BOTH, expand=True)
            self._layout_inner_pws = [top, bot]
        elif mode == 'pareto':
            host = tk.Frame(pa, bg=BG)
            host.pack(fill=tk.BOTH, expand=True)
            self._layout_frames.append(host)
            self._pareto_ws = _ParetoWorkspace(
                host, self,
                ext_toolbar=getattr(self, '_central_head', None))
            # [V12_AUTOFIT] Pareto 工具栏/小对话框文字适配
            try:
                self.root.after(500, lambda: _global_autofit(self.root))
                self.root.after(1100, lambda: _global_autofit(self.root))
            except Exception: pass
            if getattr(self, '_pareto_state', None):
                _saved = self._pareto_state
                self.root.after(
                    150,
                    lambda s=_saved: (self._pareto_ws.restore_state(s)
                                      if self._pareto_ws is not None else None))
            self._layout_inner_pws = []
        else:
            return self._apply_panel_layout('1u4d')


        label = next((lbl for k, lbl, _ in self.PANEL_LAYOUT_MODES
                      if k == mode), mode)
        try:
            self._st(f"工作区布局 → {label} (拖动 sash 可调整比例)")
        except Exception:
            pass

        self.root.after(120, lambda: self._restore_state_and_render(
            cv_state, panel_states))

        self.root.after(180, lambda m=mode: self._init_layout_sashpos(m))

    def _init_layout_sashpos(self, mode):

        try:
            outer = self._layout_frames[0] if self._layout_frames else None
            if not outer or not isinstance(outer, ttk.PanedWindow):
                return
            if mode in ('1u4d', '2u3d', '3u2d', '4u1d', 'panels_only'):

                h = outer.winfo_height()
                if h > 100:
                    if mode == 'panels_only':
                        outer.sashpos(0, h // 2)
                    else:
                        outer.sashpos(0, int(h * 5.0 / 7.0))
            elif mode == 'left_right':
                w = outer.winfo_width()
                if w > 100:
                    outer.sashpos(0, int(w * 6.0 / 9.0))
        except Exception:
            pass

    def _try_refit_after_layout(self):

        if self.res.img is None:
            return
        try:
            self.refresh()
        except Exception:
            pass

    def _on_panel_area_configure(self, _e=None):

        if getattr(self, '_panel_layout_mode', None) == 'auto':
            # debounce
            if getattr(self, '_panel_cfg_id', None):
                try: self.root.after_cancel(self._panel_cfg_id)
                except Exception: pass
            self._panel_cfg_id = self.root.after(
                100, lambda: self._apply_panel_layout('auto'))


    def _adapt_group_fonts(self, grp):


        if not grp or not grp.get('items'):
            return
        container = grp['container']
        try:
            w = max(container.winfo_width(), 1)
            h = max(container.winfo_height(), 1)
        except Exception:
            return

        ws = max(0.7, min(2.4, w / _px(260)))
        hs = max(0.7, min(2.8, h / _px(120)))
        scale = min(ws, hs)

        n_btns = sum(1 for it in grp['items']
                     if len(it) >= 2 and it[1] == 'btn')


        reserved = 40
        for it in grp['items']:
            try:
                _, kind, _ = it
                if kind == 'label' or kind == 'label_en':
                    reserved += 22
                elif kind == 'entry':
                    reserved += 36
                elif kind == 'value':
                    reserved += 42
                elif kind == 'list':
                    reserved += 60
            except Exception:
                pass
        avail_per_btn = max(28, (h - reserved) / max(n_btns, 1))
        btn_pady_new = max(2, min(16, int((avail_per_btn - 22) / 2)))

        for item in grp['items']:
            try:
                widget, kind, base = item
            except Exception:
                continue
            try:
                if kind == 'title':
                    widget.configure(
                        font=(TK_ZH, max(10, int(base * scale)), 'bold'))
                elif kind == 'label':
                    widget.configure(
                        font=(TK_ZH, max(8, int(base * scale))))
                elif kind == 'label_en':
                    widget.configure(
                        font=(TK_EN, max(9, int(base * scale))))
                elif kind == 'value':
                    widget.configure(
                        font=(TK_EN, max(14, int(base * scale)), 'bold'))
                elif kind == 'entry':
                    widget.configure(
                        font=(TK_EN, max(12, int(base * scale))))
                elif kind == 'btn':
                    widget.configure(
                        font=(TK_ZH, max(9, int(base * scale)), 'bold'),
                        pady=btn_pady_new)
                elif kind == 'list':
                    widget.configure(
                        font=(TK_ZH, max(9, int(base * scale))))
            except Exception:
                pass

    def _adapt_left_fonts(self, _e=None):

        for grp in getattr(self, '_left_font_groups', []):
            try:
                self._adapt_group_fonts(grp)
            except Exception:
                pass

    def _adapt_right_fonts(self, _e=None):

        for grp in getattr(self, '_right_font_groups', []):
            try:
                self._adapt_group_fonts(grp)
            except Exception:
                pass

    # ----------------------------------------------------------------
    #  Sidebar 自适应字体 (AutoApp 版, 问题3 修复)
    # ----------------------------------------------------------------
    def _setup_auto_sidebar_autofont(self, sidebar, ref_width):
        """绑定 sidebar 的 Configure 事件,让里面所有控件字号
        随宽度变化等比例缩放。
        防 oscillation 措施同 ManualApp 版。"""
        try:
            sidebar.update_idletasks()
        except Exception: pass

        targets = []
        def _collect(w):
            for ch in w.winfo_children():
                try:
                    if isinstance(ch, (tk.Button, tk.Label, tk.Listbox,
                                        tk.Entry, tk.Checkbutton)):
                        f = ch.cget('font')
                        if f:
                            try:
                                if isinstance(f, (tuple, list)):
                                    fam = f[0] if len(f) > 0 else 'SimSun'
                                    fsz = int(f[1]) if len(f) > 1 else 10
                                    fst = ' '.join(str(x) for x in f[2:]) if len(f) > 2 else ''
                                else:
                                    parts = str(f).split()
                                    fam = parts[0] if parts else 'SimSun'
                                    fsz = 10
                                    fst_parts = []
                                    seen_size = False
                                    for p in parts[1:]:
                                        if not seen_size:
                                            try:
                                                fsz = int(p); seen_size = True
                                            except ValueError: pass
                                        else:
                                            fst_parts.append(p)
                                    fst = ' '.join(fst_parts)
                                ch._orig_font = (fam, fsz, fst.strip())
                                if isinstance(ch, tk.Label):
                                    try:
                                        wrap = int(ch.cget('wraplength') or 0)
                                        ch._orig_wraplength = wrap
                                    except Exception:
                                        ch._orig_wraplength = 0
                                ch._no_global_fit = True
                                targets.append(ch)
                            except Exception: pass
                except Exception: pass
                _collect(ch)
        _collect(sidebar)

        sidebar._autofont_after = None
        sidebar._autofont_last_scale = 1.0
        sidebar._autofont_last_width = 0
        sidebar._autofont_init_settled = False
        sidebar._autofont_suspend = False

        def _do_apply(width, force=False):
            if (not force) and (not sidebar._autofont_init_settled):
                return
            if sidebar._autofont_suspend:
                return
            try:
                if width <= 1: return
                if not force and abs(width - sidebar._autofont_last_width) < 6:
                    return
                scale = width / max(ref_width, 1)
                scale = max(0.55, min(1.4, scale))
                if not force and abs(scale - sidebar._autofont_last_scale) < 0.04:
                    sidebar._autofont_last_width = width
                    return

                sidebar._autofont_suspend = True
                try:
                    for ch in targets:
                        try:
                            if not ch.winfo_exists(): continue
                            fam, fsz, fst = ch._orig_font
                            new_size = max(7, int(round(fsz * scale)))
                            new_font = (fam, new_size, fst) if fst else (fam, new_size)
                            try:
                                cur = ch.cget('font')
                                if isinstance(cur, (tuple, list)) and len(cur) >= 2:
                                    if int(cur[1]) == new_size:
                                        continue
                            except Exception: pass
                            ch.configure(font=new_font)
                            if isinstance(ch, tk.Label):
                                ow = getattr(ch, '_orig_wraplength', 0)
                                if ow > 0:
                                    try:
                                        ch.configure(wraplength=max(40, int(ow * scale)))
                                    except Exception: pass
                        except Exception: pass
                    # [V12_AUTOFIT] 二次测量: 缩放后若文字仍超宽再逐级缩小
                    for _ch in targets:
                        try:
                            if _ch.winfo_exists():
                                _v12_fit_one(_ch, base_current=True)
                        except Exception: pass
                finally:
                    sidebar.after(30, lambda: setattr(sidebar, '_autofont_suspend', False))

                sidebar._autofont_last_scale = scale
                sidebar._autofont_last_width = width
            except Exception: pass

        def _on_configure(_e=None):
            if sidebar._autofont_suspend:
                return
            try:
                if sidebar._autofont_after is not None:
                    sidebar.after_cancel(sidebar._autofont_after)
            except Exception: pass
            try:
                cur_w = sidebar.winfo_width()
                sidebar._autofont_after = sidebar.after(
                    220, lambda w=cur_w: _do_apply(w))
            except Exception: pass

        def _settle_done():
            sidebar._autofont_init_settled = True
            try:
                _do_apply(sidebar.winfo_width(), force=True)
            except Exception: pass

        sidebar.bind('<Configure>', _on_configure)
        try: sidebar.after(1000, _settle_done)
        except Exception: pass
        # [V12_AUTOFIT] 启动后对整个窗口做全局文字适配 (覆盖卡片/对话框)
        try: sidebar.after(1300, lambda: _global_autofit(sidebar.winfo_toplevel()))
        except Exception: pass

