def _par_mech_style(mech_id):
    """返回 (line_color, marker, fill, title_bg, title_fg)。"""
    idx = max(0, int(mech_id) - 1) % len(_PAR_MECH_PALETTE)
    return _PAR_MECH_PALETTE[idx]


def _par_mech_default_name(mech_id):
    """没有用户自定义名称时,fallback 用此默认名。
    保持前两栏与历史版本一致 (横向力/截骨角度),其余栏用通用名。"""
    if mech_id == 1: return _PAR_MECH1_NAME
    if mech_id == 2: return _PAR_MECH2_NAME
    return f'机制{mech_id}'


def _par_compute_cr(pre, post):
    """矫正率 CR (%) = (术前 - 术后) / 术前 * 100"""
    try:
        pre_v = float(pre); post_v = float(post)
        if pre_v <= 1e-6:
            return 0.0
        return (pre_v - post_v) / pre_v * 100.0
    except Exception:
        return None


def _par_nondominated(points):
    """双目标（最小化 σ、最大化 CR）非支配集"""
    n = len(points); out = []
    for i in range(n):
        si, ci = points[i][0], points[i][1]
        dominated = False
        for j in range(n):
            if i == j: continue
            sj, cj = points[j][0], points[j][1]
            if (sj <= si and cj >= ci) and (sj < si or cj > ci):
                dominated = True; break
        if not dominated: out.append(i)
    return out


def _par_find_dominator(points, i):
    si, ci = points[i][0], points[i][1]
    for j, p in enumerate(points):
        if j == i: continue
        sj, cj = p[0], p[1]
        if (sj <= si and cj >= ci) and (sj < si or cj > ci):
            return j
    return None


def _par_parse_bc(s):
    """'20N'→20.0 / '40°'→40.0 / ''→None / ..."""
    if s is None: return None
    s = str(s).strip()
    if not s: return None
    import re as _re
    m = _re.search(r'([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)', s)
    if m:
        try: return float(m.group(1))
        except Exception: return None
    return None


# ╔════════════════════════════════════════════════════════════════════════╗
# ║ [v9.12 新增] 完整严谨的 Pareto 决策逻辑                                  ║
# ║ 基于 pareto_analysis_logic.json + recommendation_logic.json             ║
# ║ 完全对齐论文 §6.4 Pareto 分析方法 (用户已校核)                          ║
# ║ ----------------------------------------------------------------------- ║
# ║ 输入: 多机制 × 多工况 × 多组织 应力数据                                  ║
# ║ 输出: Pareto 前沿 + 被支配点 + 机制 CR 跨度 + 段分析 + 切换阈值 +        ║
# ║      每机制内推荐区间 / 稳妥值 / 安全上限                                 ║
# ╚════════════════════════════════════════════════════════════════════════╝

def _par_dominant_tissue_index(stresses):
    """单工况内最大应力组织的索引 (Pareto输入用,选峰值组织)"""
    if not stresses: return 0
    best_i = 0; best_v = float('-inf')
    for i, s in enumerate(stresses):
        try:
            v = float(s)
            if v > best_v:
                best_v = v; best_i = i
        except Exception: continue
    return best_i


def _par_mech_dominant_tissue_by_score(stresses_by_tissue_2d, tissue_names):
    """[来自 recommendation_logic step_1]
    用 '末值 + 全程均值' 综合评分识别机制内主导风险组织.

    Args:
        stresses_by_tissue_2d: list[list[float]]  外层 = 组织, 内层 = 工况
        tissue_names: list[str]
    Returns:
        (dom_idx, dom_name, scores_dict)
    """
    if not stresses_by_tissue_2d:
        return 0, (tissue_names[0] if tissue_names else 'Tissue1'), {}
    scores = {}
    for ti, seq in enumerate(stresses_by_tissue_2d):
        try:
            vals = [float(v) for v in seq if v is not None]
            if not vals: continue
            last_v = vals[-1]
            mean_v = sum(vals) / len(vals)
            score = last_v + mean_v
            name = tissue_names[ti] if ti < len(tissue_names) else f'Tissue{ti+1}'
            scores[name] = score
        except Exception: continue
    if not scores:
        return 0, (tissue_names[0] if tissue_names else 'Tissue1'), {}
    # argmax + tie-break: 末值高者优先, 再字典序
    best_name = max(scores.items(), key=lambda kv: kv[1])[0]
    try:
        dom_idx = tissue_names.index(best_name)
    except Exception:
        dom_idx = 0
    return dom_idx, best_name, scores


def _par_mech_dominant_tissue(rows_stresses, tissue_names):
    """逐工况主导组织 → 全机制主导组织 (大多数原则)"""
    counts = {}
    for stresses in rows_stresses:
        if not stresses: continue
        di = _par_dominant_tissue_index(stresses)
        counts[di] = counts.get(di, 0) + 1
    if not counts:
        return 0, (tissue_names[0] if tissue_names else 'Tissue1'), counts
    dom_idx = max(counts.items(), key=lambda kv: kv[1])[0]
    dom_name = tissue_names[dom_idx] if (tissue_names and dom_idx < len(tissue_names)) \
               else f'Tissue{dom_idx + 1}'
    return dom_idx, dom_name, counts


def _par_extract_pareto_full(points):
    """[来自 pareto_analysis_logic step_1]
    全局 Pareto 前沿提取 + 每个被支配点找出支配者.

    Args:
        points: list of {'mech_id', 'mech_name', 'bc', 'sigma', 'cr', 'label', 'tissue_name'}
    Returns:
        front_indices: 在前沿上的点的索引列表 (按 CR 升序)
        dominated_map: {dominated_idx: dominator_idx}
    """
    n = len(points)
    front_indices = []
    dominated_map = {}
    for i in range(n):
        pi = points[i]
        si, ci = pi.get('sigma'), pi.get('cr')
        if si is None or ci is None:
            continue
        dominator = None
        for j in range(n):
            if i == j: continue
            pj = points[j]
            sj, cj = pj.get('sigma'), pj.get('cr')
            if sj is None or cj is None:
                continue
            # j 支配 i 当且仅当 cj >= ci AND sj <= si AND (cj > ci OR sj < si)
            if (cj >= ci - 1e-12) and (sj <= si + 1e-12) and \
               ((cj > ci + 1e-12) or (sj < si - 1e-12)):
                dominator = j
                break
        if dominator is None:
            front_indices.append(i)
        else:
            dominated_map[i] = dominator
    # 按 CR 升序排前沿
    front_indices.sort(key=lambda k: points[k].get('cr', 0))
    return front_indices, dominated_map


def _par_mech_cr_coverage(points, front_indices):
    """[来自 pareto_analysis_logic step_2]
    对每个机制计算 CR 跨度. 返回 {mech_id: {...}}.
    """
    cov = {}
    for i, p in enumerate(points):
        mid = p.get('mech_id', 0)
        cr = p.get('cr')
        if cr is None: continue
        if mid not in cov:
            cov[mid] = {
                'mech_id': mid,
                'mech_name': p.get('mech_name', f'机制{mid}'),
                'all_crs': [],
                'front_crs': [],
                'all_points': [],
                'front_points': [],
            }
        cov[mid]['all_crs'].append(cr)
        cov[mid]['all_points'].append(i)
        if i in front_indices:
            cov[mid]['front_crs'].append(cr)
            cov[mid]['front_points'].append(i)
    for mid, info in cov.items():
        info['CR_min'] = min(info['all_crs']) if info['all_crs'] else None
        info['CR_max_all'] = max(info['all_crs']) if info['all_crs'] else None
        info['CR_max_front'] = max(info['front_crs']) if info['front_crs'] else None
        info['CR_min_front'] = min(info['front_crs']) if info['front_crs'] else None
        info['front_point_count'] = len(info['front_crs'])
        info['globally_dominated'] = (info['front_point_count'] == 0)
    return cov


def _par_interp_sigma_at_cr(front_pts_sorted_by_cr, target_cr):
    """对单机制的前沿点 (按CR升序), 在 target_cr 处线性插值 σ.
    超出该机制 CR 跨度 → None (不可达)"""
    if not front_pts_sorted_by_cr: return None
    if len(front_pts_sorted_by_cr) == 1:
        cr0 = front_pts_sorted_by_cr[0]['cr']
        if abs(cr0 - target_cr) < 1e-9:
            return front_pts_sorted_by_cr[0]['sigma']
        return None
    cr_min = front_pts_sorted_by_cr[0]['cr']
    cr_max = front_pts_sorted_by_cr[-1]['cr']
    if target_cr < cr_min - 1e-9 or target_cr > cr_max + 1e-9:
        return None
    for k in range(len(front_pts_sorted_by_cr) - 1):
        a = front_pts_sorted_by_cr[k]
        b = front_pts_sorted_by_cr[k+1]
        if a['cr'] - 1e-9 <= target_cr <= b['cr'] + 1e-9:
            if abs(b['cr'] - a['cr']) < 1e-12:
                return a['sigma']
            t = (target_cr - a['cr']) / (b['cr'] - a['cr'])
            return a['sigma'] + t * (b['sigma'] - a['sigma'])
    return None


def _par_segment_analysis(points, front_indices, coverage,
                          n_samples=11, mostly_frac=0.8, tol_sigma=1e-6):
    """[来自 pareto_analysis_logic step_3+step_4]
    段切分 + 重叠段内插值比较 → 段优势机制.

    Returns:
        segments: list of dict {
            'lo', 'hi', 'reachable_mechs': [mech_id],
            'classification': 'exclusive' | 'overlap',
            'preferred_mech': mech_id or None,
            'preference_type': 'strict' | 'mostly' | 'mixed' | 'exclusive',
            'evidence': {...}
        }
    """
    # 1. 收集断点
    breakpoints = set()
    for mid, info in coverage.items():
        if info.get('CR_min_front') is not None:
            breakpoints.add(info['CR_min_front'])
        if info.get('CR_max_front') is not None:
            breakpoints.add(info['CR_max_front'])
    # 也加入 CR_min/CR_max_all 边界, 但段分析以 front 为准
    bps = sorted(breakpoints)
    if len(bps) < 2:
        # 单段
        if len(bps) == 1:
            return [{'lo': bps[0], 'hi': bps[0],
                    'reachable_mechs': list(coverage.keys()),
                    'classification': 'exclusive',
                    'preferred_mech': list(coverage.keys())[0]
                                       if coverage else None,
                    'preference_type': 'single',
                    'evidence': {'note': 'CR 区分度不足, 建议增加工况'}}]
        return []

    segments = []
    for i in range(len(bps) - 1):
        lo, hi = bps[i], bps[i+1]
        if hi <= lo + 1e-9: continue  # 零宽段
        reachable = []
        for mid, info in coverage.items():
            if info.get('CR_min_front') is None or info.get('CR_max_front') is None:
                continue
            # 严格判定: 机制完全覆盖 [lo, hi]
            if info['CR_min_front'] <= lo + 1e-9 and \
               info['CR_max_front'] >= hi - 1e-9:
                reachable.append(mid)
        if not reachable: continue
        seg = {'lo': lo, 'hi': hi, 'reachable_mechs': reachable}
        if len(reachable) == 1:
            seg['classification'] = 'exclusive'
            seg['preferred_mech'] = reachable[0]
            seg['preference_type'] = 'exclusive'
            seg['evidence'] = {}
        else:
            # 重叠段: 在 [lo, hi] 采样, 各机制插值比较
            samples = []
            if n_samples < 2: n_samples = 2
            for k in range(n_samples):
                t = k / max(1, n_samples - 1)
                samples.append(lo + t * (hi - lo))
            # 每机制前沿点(按CR升序)
            mech_fronts = {}
            for mid in reachable:
                front_idx_list = coverage[mid]['front_points']
                fpts = sorted(
                    [points[k] for k in front_idx_list],
                    key=lambda p: p.get('cr', 0)
                )
                mech_fronts[mid] = fpts

            winners = []
            ratios_log = []
            for cr_s in samples:
                sig_by_mech = {}
                for mid in reachable:
                    v = _par_interp_sigma_at_cr(mech_fronts[mid], cr_s)
                    if v is not None:
                        sig_by_mech[mid] = v
                if not sig_by_mech:
                    winners.append(None); continue
                best_m = min(sig_by_mech.items(), key=lambda kv: kv[1])[0]
                best_sig = sig_by_mech[best_m]
                # tie detection
                tied = [m for m, s in sig_by_mech.items()
                         if abs(s - best_sig) < tol_sigma]
                winners.append(best_m if len(tied) == 1 else 'tie')
                ratios_log.append({'cr': cr_s, 'sigmas': sig_by_mech,
                                    'winner': winners[-1]})

            # 决断
            valid_winners = [w for w in winners if w is not None]
            if not valid_winners:
                seg['classification'] = 'overlap'
                seg['preferred_mech'] = None
                seg['preference_type'] = 'unknown'
                seg['evidence'] = {'samples': ratios_log}
            else:
                from collections import Counter
                cnt = Counter(valid_winners)
                top_m, top_n = cnt.most_common(1)[0]
                frac = top_n / len(valid_winners)
                if top_m == 'tie':
                    seg['preferred_mech'] = None
                    seg['preference_type'] = 'tie'
                elif frac >= 1.0 - 1e-9:
                    seg['preferred_mech'] = top_m
                    seg['preference_type'] = 'strict'
                elif frac >= mostly_frac:
                    seg['preferred_mech'] = top_m
                    seg['preference_type'] = 'mostly'
                else:
                    seg['preferred_mech'] = None
                    seg['preference_type'] = 'mixed'
                seg['classification'] = 'overlap'
                seg['evidence'] = {
                    'samples': ratios_log,
                    'winner_counts': dict(cnt),
                    'dominant_fraction': frac,
                }
        segments.append(seg)
    return segments


def _par_switch_thresholds(segments, coverage):
    """[来自 pareto_analysis_logic step_5] 提取段间切换阈值."""
    out = []
    for i in range(len(segments) - 1):
        s1, s2 = segments[i], segments[i+1]
        m1 = s1.get('preferred_mech')
        m2 = s2.get('preferred_mech')
        if m1 is None or m2 is None or m1 == m2:
            continue
        # 阈值 = s1 的上端点 = s2 的下端点
        threshold = s1['hi']
        out.append({
            'threshold_cr': threshold,
            'from_mech': m1,
            'from_mech_name': coverage.get(m1, {}).get('mech_name', str(m1)),
            'to_mech': m2,
            'to_mech_name': coverage.get(m2, {}).get('mech_name', str(m2)),
            'reason': f'CR={threshold:.2f}% 处优势机制从 [{coverage.get(m1, {}).get("mech_name", m1)}] 切换至 [{coverage.get(m2, {}).get("mech_name", m2)}]',
        })
    return out


def _par_recommend_per_mech(conditions, stresses_by_tissue, mech_name='',
                            unit='', factor_rebound=0.8, factor_sharp_rise=1.3):
    """[来自 recommendation_logic 完整 6 步]
    单机制内推荐: 主导组织识别 → 增长率 → 谷底 → 模式分类 → 推荐区间.

    Args:
        conditions: list of float (严格升序工况边界)
        stresses_by_tissue: dict {tissue_name: list_of_sigma}
        mech_name: str
        unit: str
    Returns:
        result dict 同 recommendation_logic.output_schema
    """
    M = len(conditions)
    if M < 2:
        return {
            'mechanism_name': mech_name, 'error': 'M<2 数据不足',
            'optimal_range': None, 'safer_recommendation': None,
            'critical_threshold': None,
        }
    # 1. 主导组织 (score = last_v + mean_v)
    tissue_names = list(stresses_by_tissue.keys())
    seqs_2d = [list(stresses_by_tissue[n]) for n in tissue_names]
    dom_idx, dom_name, scores = _par_mech_dominant_tissue_by_score(
        seqs_2d, tissue_names)
    dom_seq = seqs_2d[dom_idx] if dom_idx < len(seqs_2d) else seqs_2d[0]
    if len(dom_seq) != M:
        dom_seq = dom_seq[:M] + [dom_seq[-1]] * max(0, M - len(dom_seq))

    # 2. 增长率
    rel = []
    abs_inc = []
    for i in range(M - 1):
        a, b = dom_seq[i], dom_seq[i+1]
        if a is None or b is None or a <= 0:
            rel.append(0.0); abs_inc.append(0.0); continue
        rel.append((b - a) / a * 100.0)
        abs_inc.append(b - a)

    if not rel:
        return {
            'mechanism_name': mech_name, 'error': '增长率序列为空',
            'optimal_range': None, 'safer_recommendation': None,
            'critical_threshold': None,
        }

    # 3. 谷底
    valley_idx = min(range(len(rel)), key=lambda k: rel[k])

    # 4. 模式分类
    pre_last = rel[valley_idx - 1] if valley_idx >= 1 else None
    post_max = max(rel[valley_idx+1:]) if (valley_idx+1) < len(rel) else None
    if post_max is None:
        pattern = 'B'; rule_label = 'TypeB_no_post'
    elif pre_last is None:
        pattern = 'A'; rule_label = 'TypeA_no_pre'
    elif post_max >= pre_last * factor_rebound:
        pattern = 'A'; rule_label = 'TypeA_valley_is_optimal_interval'
    else:
        pattern = 'B'; rule_label = 'TypeB_plateau'

    # 5. 临界索引
    sharp_rise_idx = None
    if pattern == 'A':
        critical_idx = valley_idx + 1
        rule_label = 'TypeA_valley_is_optimal_interval'
    else:
        # Type B: 在 pre_valley 中找 sharp rise
        pre_valley = rel[:valley_idx]
        critical_idx = None
        for k in range(1, len(pre_valley)):
            if pre_valley[k-1] <= 0: continue
            if pre_valley[k] > pre_valley[k-1] and \
               pre_valley[k] / pre_valley[k-1] >= factor_sharp_rise:
                sharp_rise_idx = k
                critical_idx = k
                rule_label = 'TypeB_sharp_rise_recommend_interval_immediately_before'
                break
        if critical_idx is None:
            critical_idx = valley_idx
            rule_label = 'TypeB_plateau_onset_recommend_last_descending_interval'

    if critical_idx == 0:
        critical_idx = 1  # edge case

    # 6. 输出
    if critical_idx - 1 < 0 or critical_idx >= M:
        return {
            'mechanism_name': mech_name, 'error': f'critical_idx={critical_idx} 越界',
            'optimal_range': None, 'safer_recommendation': None,
            'critical_threshold': None,
        }
    optimal_range = [conditions[critical_idx - 1], conditions[critical_idx]]
    safer = conditions[critical_idx - 1]
    critical_threshold = conditions[critical_idx]
    buffer_size = critical_threshold - safer

    return {
        'mechanism_name': mech_name,
        'unit': unit,
        'dominant_tissue': dom_name,
        'tissue_scores': scores,
        'rel_growth_percent': rel,
        'abs_increment_MPa': abs_inc,
        'valley_idx': valley_idx,
        'pattern': pattern,
        'decision_rule': rule_label,
        'critical_idx': critical_idx,
        'optimal_range': optimal_range,
        'safer_recommendation': safer,
        'critical_threshold': critical_threshold,
        'buffer_size': buffer_size,
        'sharp_rise_idx': sharp_rise_idx,
        'pre_last': pre_last,
        'post_max': post_max,
    }


def _par_mech_cr_range(points_of_mech):
    """旧 API 兼容: 返回机制 CR 范围 (min, max)"""
    crs = [p.get('cr') for p in points_of_mech if p.get('cr') is not None]
    if not crs: return (None, None)
    return (min(crs), max(crs))


def _par_recommend_cr_intervals(points_by_mech):
    """旧 API 兼容: 简化版 CR 区间推荐 (供 _rerender_recommendation 老路径使用).
    points_by_mech: {mech_id: [points...]}
    """
    out = []
    for mid, pts in points_by_mech.items():
        if not pts: continue
        cmin, cmax = _par_mech_cr_range(pts)
        if cmin is None: continue
        out.append({
            'mech_id': mid,
            'mech_name': pts[0].get('mech_name', f'机制{mid}'),
            'cr_min': cmin, 'cr_max': cmax,
        })
    out.sort(key=lambda d: d.get('cr_min', 0))
    return out


