def m_imread_safe(path):
    try:
        return cv2.imdecode(np.fromfile(str(path), np.uint8),
                            cv2.IMREAD_COLOR)
    except Exception:
        return None


def m_compute_tilt(p1, p2):

    v = (p2[0] - p1[0], p2[1] - p1[1])
    a = abs(math.degrees(math.atan2(v[1], v[0])))
    if a > 90:
        a = 180 - a
    return float(a)


def m_angle_between_lines(pa1, pa2, pb1, pb2):

    va = (pa2[0] - pa1[0], pa2[1] - pa1[1])
    vb = (pb2[0] - pb1[0], pb2[1] - pb1[1])
    if math.hypot(*va) < 1e-6 or math.hypot(*vb) < 1e-6:
        return 0.0
    aa = math.degrees(math.atan2(va[1], va[0]))
    ab = math.degrees(math.atan2(vb[1], vb[0]))
    d = abs(aa - ab)
    if d > 180:
        d = 360 - d
    if d > 90:
        d = 180 - d
    return float(d)


def m_compute_max_cobb_pair(measurements):

    active = [(i, m) for i, m in enumerate(measurements)
              if m.ok and not m.dimmed and m.visible]
    if len(active) < 2:
        return None
    best = None
    for i in range(len(active)):
        ia, ma = active[i]
        for j in range(i + 1, len(active)):
            ib, mb = active[j]
            ang = m_angle_between_lines(ma.points[0], ma.points[1],
                                      mb.points[0], mb.points[1])
            if best is None or ang > best[2]:
                best = (ia, ib, ang)
    return best


def m_line_extended(pa, pb, ext_px):

    dx, dy = pb[0] - pa[0], pb[1] - pa[1]
    L = math.hypot(dx, dy)
    if L < 1e-6:
        return pa, pb
    ux, uy = dx / L, dy / L
    return ((pa[0] - ux * ext_px, pa[1] - uy * ext_px),
            (pb[0] + ux * ext_px, pb[1] + uy * ext_px))


def m_line_intersection(p1, p2, p3, p4):
    x1, y1 = p1; x2, y2 = p2
    x3, y3 = p3; x4, y4 = p4
    den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if abs(den) < 1e-6:
        return ((x1 + x2 + x3 + x4) / 4, (y1 + y2 + y3 + y4) / 4)
    t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den
    return (x1 + t * (x2 - x1), y1 + t * (y2 - y1))


class M_Measurement:


    def __init__(self, label=""):
        self.label = label or ""
        self.points = []          # [(x, y), ...] image coords
        self.tilt = 0.0
        self.visible = True
        self.dimmed = False

        self.label_offset = (0.0, 0.0)

    @property
    def n(self):
        return len(self.points)

    @property
    def ok(self):
        return len(self.points) >= 2

    def recompute(self):
        self.tilt = m_compute_tilt(*self.points[:2]) if self.ok else 0.0

    def to_dict(self):
        return {
            'label': self.label,
            'points': [list(p) for p in self.points],
            'visible': self.visible,
            'dimmed': self.dimmed,
            'label_offset': list(self.label_offset),
        }

    @classmethod
    def from_dict(cls, d):
        m = cls(label=d.get('label', ''))
        m.points = [tuple(p) for p in d.get('points', [])]
        m.visible = bool(d.get('visible', True))
        m.dimmed = bool(d.get('dimmed', False))
        lo = d.get('label_offset', (0.0, 0.0))
        m.label_offset = (float(lo[0]), float(lo[1])) if lo else (0.0, 0.0)
        m.recompute()
        return m


class ManualResult:


    def __init__(self):
        self.img = None
        self.path = ""
        self.measurements = []
        self.active_idx = -1
        self._next_id = 1
        self.confirmed = False
        self.cobb_max_pair = None     # (ia, ib, angle)

        self.labels_visible = True
        self.label_font_size = 11


        self.baseline_visible = True
        self.baseline_y = None
        self.baseline_x1 = None
        self.baseline_x2 = None

        self.cobb_label_offset = (0.0, 0.0)

        self.solo_max_mode = False

    def setup_baseline_defaults(self):

        if self.img is None:
            return
        h, w = self.img.shape[:2]
        if self.baseline_y is None:
            self.baseline_y = h * 0.5
        if self.baseline_x1 is None:
            self.baseline_x1 = w * 0.1
        if self.baseline_x2 is None:
            self.baseline_x2 = w * 0.9

    @property
    def active(self):
        if 0 <= self.active_idx < len(self.measurements):
            return self.measurements[self.active_idx]
        return None

    @property
    def count(self):
        return len(self.measurements)

    @property
    def ok_list(self):
        return [m for m in self.measurements if m.ok]

    @property
    def max_pair_indices(self):
        if self.cobb_max_pair is None:
            return (-1, -1)
        ia, ib, _ = self.cobb_max_pair
        return (ia, ib)

    def new_measurement(self):
        label = f"L{self._next_id}"
        self._next_id += 1
        m = M_Measurement(label=label)
        self.measurements.append(m)
        self.active_idx = len(self.measurements) - 1
        return m

    def delete_measurement(self, idx):
        if 0 <= idx < len(self.measurements):
            del self.measurements[idx]
            if self.active_idx >= len(self.measurements):
                self.active_idx = len(self.measurements) - 1
            if self.confirmed:
                self.recompute_max_cobb()

    def recompute_max_cobb(self):
        self.cobb_max_pair = m_compute_max_cobb_pair(self.measurements)

    def render_color_for(self, mid):

        if not (0 <= mid < len(self.measurements)):
            return _M_LINE_COLOR
        m = self.measurements[mid]
        if m.dimmed:
            return _M_LINE_COLOR_DIM
        if self.confirmed and self.cobb_max_pair is not None:
            ia, ib, _ = self.cobb_max_pair
            if mid == ia:
                return _M_HL_A
            if mid == ib:
                return _M_HL_B
        return _M_LINE_COLOR

    def max_pair_role(self, mid):
        if not (self.confirmed and self.cobb_max_pair is not None):
            return None
        ia, ib, _ = self.cobb_max_pair
        if mid == ia:
            return 'A'
        if mid == ib:
            return 'B'
        return None

    def find_nearest_endpoint_image(self, ix, iy, hit_r_img):
        best = (-1, -1, float('inf'))
        for mid, m in enumerate(self.measurements):
            if not m.visible:
                continue
            for pid, (px, py) in enumerate(m.points):
                d = math.hypot(ix - px, iy - py)
                if d < best[2]:
                    best = (mid, pid, d)
        if best[2] < hit_r_img:
            return best[0], best[1]
        return -1, -1

    def find_nearest_line_image(self, ix, iy, hit_r_img):
        best_idx = -1
        best_d = float('inf')
        for mid, m in enumerate(self.measurements):
            if not m.ok or not m.visible:
                continue
            (x1, y1), (x2, y2) = m.points[0], m.points[1]
            dx, dy = x2 - x1, y2 - y1
            L2 = dx * dx + dy * dy
            if L2 < 1e-6:
                continue
            t = max(0.0, min(1.0,
                             ((ix - x1) * dx + (iy - y1) * dy) / L2))
            px, py = x1 + t * dx, y1 + t * dy
            d = math.hypot(ix - px, iy - py)
            if d < best_d:
                best_d, best_idx = d, mid
        return best_idx if best_d < hit_r_img else -1

    def to_state(self):
        return {
            'measurements': [m.to_dict() for m in self.measurements],
            'active_idx': self.active_idx,
            'next_id': self._next_id,
            'confirmed': self.confirmed,
            'cobb_max_pair': (list(self.cobb_max_pair)
                              if self.cobb_max_pair else None),
            'labels_visible': self.labels_visible,
            'label_font_size': self.label_font_size,
            'baseline_visible': self.baseline_visible,
            'baseline_y': self.baseline_y,
            'baseline_x1': self.baseline_x1,
            'baseline_x2': self.baseline_x2,
            'cobb_label_offset': list(self.cobb_label_offset),
            'solo_max_mode': self.solo_max_mode,
        }

    def from_state(self, d):
        self.measurements = [M_Measurement.from_dict(md)
                             for md in d.get('measurements', [])]
        self.active_idx = int(d.get('active_idx', -1))
        if self.active_idx >= len(self.measurements):
            self.active_idx = len(self.measurements) - 1
        self._next_id = int(d.get('next_id',
                                  max(1, len(self.measurements) + 1)))
        self.confirmed = bool(d.get('confirmed', False))
        cm = d.get('cobb_max_pair', None)
        if cm and len(cm) == 3:
            self.cobb_max_pair = (int(cm[0]), int(cm[1]), float(cm[2]))
        else:
            self.cobb_max_pair = None
        self.labels_visible = bool(d.get('labels_visible', True))
        self.label_font_size = int(d.get('label_font_size', 11))
        self.baseline_visible = bool(d.get('baseline_visible', True))
        self.baseline_y = d.get('baseline_y', None)
        self.baseline_x1 = d.get('baseline_x1', None)
        self.baseline_x2 = d.get('baseline_x2', None)
        if self.baseline_y is not None:
            self.baseline_y = float(self.baseline_y)
        if self.baseline_x1 is not None:
            self.baseline_x1 = float(self.baseline_x1)
        if self.baseline_x2 is not None:
            self.baseline_x2 = float(self.baseline_x2)
        cl = d.get('cobb_label_offset', (0.0, 0.0))
        self.cobb_label_offset = ((float(cl[0]), float(cl[1]))
                                  if cl else (0.0, 0.0))
        self.solo_max_mode = bool(d.get('solo_max_mode', False))
        if self.confirmed:
            self.recompute_max_cobb()


def m_load_image(path):
    r = ManualResult()
    r.path = path
    r.img = m_imread_safe(path)
    r.setup_baseline_defaults()
    return r


class M_ToolTip:
    """半自动板块的悬浮提示工具。
    [问题3 修复]: 解决"鼠标移开后提示信息卡在屏幕上不消失"的 bug。
    修复要点:
      1. 显示后启动一个轮询 watchdog (每 120ms 检查一次鼠标位置),
         一旦鼠标真实位置离开了所属 widget 的矩形区域,
         立即销毁提示, 即使没有 <Leave> 事件也能消失。
      2. 同时绑定 <Motion>/<FocusOut>/<Unmap>/<Destroy> 多个事件,
         任意一个触发都立刻关闭。
      3. 父 widget 销毁时同步清理 watchdog after-id, 避免野指针。
    """
    def __init__(self, w, text, delay=600):
        self.w = w
        self.text = text
        self.delay = delay
        self._tip = None
        self._aid = None
        self._watchdog_aid = None
        w.bind('<Enter>', self._s)
        w.bind('<Leave>', self._h)
        w.bind('<ButtonPress>', self._h)
        w.bind('<FocusOut>', self._h)
        w.bind('<Unmap>', self._h)
        w.bind('<Destroy>', self._h)

    def _s(self, _e=None):
        self._aid = self.w.after(self.delay, self._show)

    def _show(self):
        if self._tip:
            return
        try:
            if not self.w.winfo_exists():
                return
        except Exception:
            return
        x = self.w.winfo_rootx() + self.w.winfo_width() // 2
        y = self.w.winfo_rooty() + self.w.winfo_height() + 4
        tw = tk.Toplevel(self.w)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}")
        tw.configure(bg='#333')
        tk.Label(tw, text=self.text, bg='#333', fg='white',
                 font=(_M_TK_ZH, _M_FS_S), padx=8, pady=4,
                 wraplength=_px(300)).pack()
        self._tip = tw
        # 启动 watchdog: 周期检查鼠标真实位置, 离开 widget 矩形即关闭
        self._watchdog_aid = self.w.after(120, self._watchdog)

    def _watchdog(self):
        """周期性检查鼠标是否仍在 widget 范围内。
        若已不在(包括 widget 已被销毁), 立即关闭提示。"""
        self._watchdog_aid = None
        if not self._tip:
            return
        try:
            if not self.w.winfo_exists():
                self._h()
                return
            # 获取鼠标全局坐标
            px = self.w.winfo_pointerx()
            py = self.w.winfo_pointery()
            # widget 在屏幕上的矩形
            wx = self.w.winfo_rootx()
            wy = self.w.winfo_rooty()
            ww = self.w.winfo_width()
            wh = self.w.winfo_height()
            inside = (wx <= px <= wx + ww) and (wy <= py <= wy + wh)
            if not inside:
                self._h()
                return
        except Exception:
            self._h()
            return
        # 仍在 widget 内, 继续轮询
        try:
            self._watchdog_aid = self.w.after(120, self._watchdog)
        except Exception:
            pass

    def _h(self, _e=None):
        if self._aid:
            try: self.w.after_cancel(self._aid)
            except Exception: pass
            self._aid = None
        if self._watchdog_aid:
            try: self.w.after_cancel(self._watchdog_aid)
            except Exception: pass
            self._watchdog_aid = None
        if self._tip:
            try: self._tip.destroy()
            except Exception: pass
            self._tip = None


class M_Debouncer:
    def __init__(self, widget, delay_ms, fn):
        self.widget = widget
        self.delay = delay_ms
        self.fn = fn
        self._id = None

    def trigger(self):
        if self._id is not None:
            try:
                self.widget.after_cancel(self._id)
            except Exception:
                pass
        self._id = self.widget.after(self.delay, self._fire)

    def _fire(self):
        self._id = None
        try:
            self.fn()
        except Exception:
            traceback.print_exc()

    def cancel(self):
        if self._id is not None:
            try:
                self.widget.after_cancel(self._id)
            except Exception:
                pass
            self._id = None


def m_make_btn(parent, text, cmd, color=_M_ACC, color_h=_M_ACC_H, fg='white',
             tip=None, pady=8, fs=None, font_style='bold',
             relief='flat', bd=0, hl_color=None):
    """半自动板块按钮 (V2 居中版):
    - 中文文字部分严格居中于按钮 (使用 place(relx=0.5, anchor='center'))
    - emoji 图标位于文字首字符左边 1 个空格距离
    - 通过 tk.Frame + 两个 Label 组合实现, 不依赖 tk.Button 的内部布局
    - 完全兼容现有 .pack/.grid/.bind/.configure(text/bg/activebackground/fg/font/state)
    - 支持 relief/bd/hl_color 用于带边框的 outline 按钮
    """
    fs_val = fs if fs is not None else _M_FS_M

    _mbtn_orig_full = text  # [V13] 保存原始整串(含 emoji), 供语言切换时整串查表

    # =================================================================
    # [v9.12 修复] 英文模式下: 先用 _LX 翻译完整字符串, 再拆 emoji/文字.
    # 之前的实现是先拆再分别翻译, 文字部分若纯中文则被 _LX_strip 删空,
    # 导致英文模式下按钮只见 emoji, 文字空白. 现在改为整体查表翻译.
    # =================================================================
    try:
        if _LANG == 'en' and isinstance(text, str) and _has_cjk(text):
            try:
                _translated_full = _LX(text)
                if _translated_full and _translated_full != text:
                    text = _translated_full
            except Exception:
                pass
    except Exception:
        pass

    # 解析 text → (emoji_part, text_part)
    # 规则: 第一个空白字符之前的内容算 emoji,之后的算文字; 没空白则全是文字
    def _parse_text(t):
        s = (t or '').lstrip()
        if not s:
            return '', ''
        for i, ch in enumerate(s):
            if ch in (' ', '\t', '\u00A0'):
                emoji_pp = s[:i]
                text_pp = s[i:].lstrip()
                if not text_pp:
                    return '', emoji_pp
                return emoji_pp, text_pp
        return '', s

    emoji_part, text_part = _parse_text(text)

    # Frame 容器 (支持边框)
    frame_kw = dict(bg=color, cursor='hand2')
    if relief and relief != 'flat':
        frame_kw['relief'] = relief
        frame_kw['bd'] = bd if bd is not None else 1
        frame_kw['highlightthickness'] = 0
    elif hl_color is not None:
        frame_kw['bd'] = 0
        frame_kw['highlightthickness'] = max(1, bd)
        frame_kw['highlightbackground'] = hl_color
        frame_kw['highlightcolor'] = hl_color
    else:
        frame_kw['bd'] = 0
        frame_kw['highlightthickness'] = 0
    btn = tk.Frame(parent, **frame_kw)

    # 设定按钮固定高度: 字号 × 1.6 + pady * 2
    h_px = max(int(fs_val * 1.6), 16) + _px(pady) * 2
    try: btn.configure(height=h_px)
    except Exception: pass
    btn.pack_propagate(False)
    btn.grid_propagate(False)

    # 文字 Label - place 严格居中
    txt_lbl = tk.Label(btn, text=text_part, bg=color, fg=fg,
                       font=(_M_TK_ZH, fs_val, font_style),
                       anchor='center')
    txt_lbl.place(relx=0.5, rely=0.5, anchor='center')

    # Emoji Label - 后续 layout 到 txt_lbl 左边
    emoji_lbl = tk.Label(btn, text=emoji_part, bg=color, fg=fg,
                         font=(_M_TK_ZH, fs_val),
                         anchor='center')
    if emoji_part:
        emoji_lbl.place(x=4, rely=0.5, anchor='w')

    # 状态字典
    _s = {'color': color, 'color_h': color_h, 'fg': fg,
          'enabled': True, 'hover': False, 'fs': fs_val}
    btn._mbtn_state = _s
    btn._mbtn_txt = txt_lbl
    btn._mbtn_emoji = emoji_lbl

    # 重新布局 emoji 到 文字 Label 左侧 (距离 = 1 空格宽)
    def _layout_emoji(_e=None):
        try:
            cur_emoji_text = emoji_lbl.cget('text')
            if not cur_emoji_text:
                try: emoji_lbl.place_forget()
                except Exception: pass
                return
            txt_lbl.update_idletasks()
            emoji_lbl.update_idletasks()
            tx = txt_lbl.winfo_x()
            tw = txt_lbl.winfo_width()
            if tw <= 1 or tx <= 0:
                btn.after(60, _layout_emoji)
                return
            from tkinter import font as _tkfont
            try:
                cur_font = _tkfont.Font(font=txt_lbl.cget('font'))
                space_w = max(4, cur_font.measure(' '))
                emoji_w = emoji_lbl.winfo_reqwidth()
                if emoji_w <= 1:
                    emoji_w = int(_s.get('fs', fs_val) * 1.8)
            except Exception:
                space_w = 6
                emoji_w = int(fs_val * 1.8)
            ex = tx - space_w - emoji_w
            if ex < 2:
                ex = 2
            emoji_lbl.place_configure(x=ex, rely=0.5, anchor='w')
        except Exception: pass

    btn._mbtn_relayout = _layout_emoji
    btn.bind('<Configure>', _layout_emoji)
    btn.after(20, _layout_emoji)
    btn.after(150, _layout_emoji)
    btn.after(400, _layout_emoji)

    # =================================================================
    # [V13/V14] 复合按钮的语言切换钩子 + 按外框宽度缩字 + 永不空白安全网
    # =================================================================
    btn._mbtn_orig_text = _mbtn_orig_full
    btn._mbtn_is_button = True
    try:
        txt_lbl._no_lx = True;   txt_lbl._no_global_fit = True
        emoji_lbl._no_lx = True; emoji_lbl._no_global_fit = True
    except Exception:
        pass

    def _mbtn_fit():
        try:
            if not btn.winfo_exists():
                return
            fw = btn.winfo_width()
            if fw <= 1:
                btn.after(120, _mbtn_fit)
                return
            import tkinter.font as _tkf
            cf = txt_lbl.cget('font')
            fam2, sz2, wt2 = _v12_parse_font(cf)
            if not fam2 or not sz2:
                return
            orig = getattr(txt_lbl, '_gaf_orig', None)
            if orig is None:
                orig = (fam2, sz2, wt2)
                txt_lbl._gaf_orig = orig
            ofam, osize, owt = orig
            t = txt_lbl.cget('text')
            if not t or not str(t).strip():
                return
            emoji_w = 0
            try:
                if emoji_lbl.cget('text'):
                    emoji_w = emoji_lbl.winfo_reqwidth() + 8
            except Exception:
                pass
            budget = max(8, fw - 12 - emoji_w)
            probe = _tkf.Font(family=ofam, size=osize, weight=owt)
            sz = osize
            while sz > 6 and probe.measure(str(t)) > budget:
                sz -= 1
                probe.configure(size=sz)
            _, cur_sz, _ = _v12_parse_font(cf)
            if cur_sz == sz:
                return
            newf = (ofam, sz, owt) if owt == 'bold' else (ofam, sz)
            txt_lbl.configure(font=newf)
            btn.after(10, _layout_emoji)
        except Exception:
            pass
    btn._mbtn_fit = _mbtn_fit
    btn.bind('<Configure>', lambda e: _mbtn_fit(), add='+')
    btn.after(450, _mbtn_fit)

    def _mbtn_apply_lang():
        try:
            disp = _LX(_mbtn_orig_full)
            em, tp = _parse_text(disp)
            # [V14 安全网] 合法英文翻译必含拉丁字母。若原串本有中文文字部分,
            #   但整条翻译结果不含任何拉丁字母, 说明查表落空被 _LX_strip 删空,
            #   则回退到原始整串(保留完整中文), 杜绝按钮只剩图标/文字消失。
            _oe, _ot = _parse_text(_mbtn_orig_full)
            import re as _re_mb
            if str(_ot).strip() and not _re_mb.search('[A-Za-z]', disp or ''):
                _fallback_tp = _LX(_ot)
                if (not isinstance(_fallback_tp, str)) or (not _re_mb.search('[A-Za-z]', _fallback_tp or '')):
                    _fallback_tp = 'Action'
                em, tp = _oe, _fallback_tp
            emoji_lbl.configure(text=em)
            txt_lbl.configure(text=tp)
            if em:
                emoji_lbl.place(x=4, rely=0.5, anchor='w')
            else:
                try: emoji_lbl.place_forget()
                except Exception: pass
            try:
                o = getattr(txt_lbl, '_gaf_orig', None)
                if o:
                    f0, s0, w0 = o
                    txt_lbl.configure(font=((f0, s0, w0) if w0 == 'bold' else (f0, s0)))
            except Exception: pass
            btn.after(20, _layout_emoji)
            btn.after(160, _layout_emoji)
            btn.after(180, _mbtn_fit)
        except Exception:
            pass
    btn._mbtn_apply_lang = _mbtn_apply_lang

    # 点击/Hover
    def _do_click(_e=None):
        if not _s['enabled']: return
        if cmd:
            try: cmd()
            except Exception: traceback.print_exc()

    def _do_enter(_e=None):
        if not _s['enabled']: return
        _s['hover'] = True
        try:
            tk.Frame.configure(btn, bg=_s['color_h'])
            txt_lbl.configure(bg=_s['color_h'])
            emoji_lbl.configure(bg=_s['color_h'])
        except Exception: pass

    def _do_leave(_e=None):
        _s['hover'] = False
        try:
            tk.Frame.configure(btn, bg=_s['color'])
            txt_lbl.configure(bg=_s['color'])
            emoji_lbl.configure(bg=_s['color'])
        except Exception: pass

    # 注: tooltip 在下面会 bind Enter/Leave; 我们用 add='+' 避免覆盖
    for w in (btn, txt_lbl, emoji_lbl):
        w.bind('<Button-1>', _do_click)
        w.bind('<Enter>', _do_enter, add='+')
        w.bind('<Leave>', _do_leave, add='+')

    # 重写 .configure / .config 兼容 tk.Button 的常用调用
    def _new_configure(*args, **kwargs):
        if 'text' in kwargs:
            new_text = kwargs.pop('text')
            new_emoji, new_text_part = _parse_text(new_text)
            try:
                emoji_lbl.configure(text=new_emoji)
                txt_lbl.configure(text=new_text_part)
                if new_emoji:
                    emoji_lbl.place(x=4, rely=0.5, anchor='w')
                else:
                    try: emoji_lbl.place_forget()
                    except Exception: pass
                btn.after(20, _layout_emoji)
                btn.after(150, _layout_emoji)
            except Exception: pass
        if 'bg' in kwargs:
            new_bg = kwargs.pop('bg')
            _s['color'] = new_bg
            if not _s['hover']:
                try:
                    tk.Frame.configure(btn, bg=new_bg)
                    txt_lbl.configure(bg=new_bg)
                    emoji_lbl.configure(bg=new_bg)
                except Exception: pass
        if 'activebackground' in kwargs:
            new_h = kwargs.pop('activebackground')
            _s['color_h'] = new_h
            if _s['hover']:
                try:
                    tk.Frame.configure(btn, bg=new_h)
                    txt_lbl.configure(bg=new_h)
                    emoji_lbl.configure(bg=new_h)
                except Exception: pass
        if 'activeforeground' in kwargs:
            kwargs.pop('activeforeground')  # ignore - Frame doesn't support
        if 'fg' in kwargs:
            new_fg = kwargs.pop('fg')
            _s['fg'] = new_fg
            try:
                if _s['enabled']:
                    txt_lbl.configure(fg=new_fg)
                    emoji_lbl.configure(fg=new_fg)
            except Exception: pass
        if 'font' in kwargs:
            new_font = kwargs.pop('font')
            try:
                txt_lbl.configure(font=new_font)
                emoji_lbl.configure(font=new_font)
                if isinstance(new_font, (tuple, list)) and len(new_font) > 1:
                    try: _s['fs'] = int(new_font[1])
                    except Exception: pass
                btn.after(20, _layout_emoji)
            except Exception: pass
        if 'state' in kwargs:
            sv = kwargs.pop('state')
            en = (sv == tk.NORMAL or str(sv) == 'normal')
            _s['enabled'] = en
            try:
                tk.Frame.configure(btn, cursor='hand2' if en else '')
                if en:
                    txt_lbl.configure(fg=_s['fg'])
                    emoji_lbl.configure(fg=_s['fg'])
                else:
                    txt_lbl.configure(fg='#9CA3AF')
                    emoji_lbl.configure(fg='#9CA3AF')
            except Exception: pass
        # 'command' / 'padx' / 'pady' / 'relief' / 'bd' 等剩余属性传给 Frame
        for nope_key in ('command', 'padx', 'pady',
                         'justify', 'anchor', 'wraplength'):
            if nope_key in kwargs:
                kwargs.pop(nope_key)
        if kwargs:
            try:
                tk.Frame.configure(btn, *args, **kwargs)
            except Exception: pass

    btn.configure = _new_configure
    btn.config = _new_configure

    if tip:
        M_ToolTip(btn, tip)

    return btn


def m_make_section_header(parent, text):

    f = tk.Frame(parent, bg=_M_BG_H, height=_px(30))
    f.pack(side=tk.TOP, fill=tk.X)
    f.pack_propagate(False)
    lbl = tk.Label(f, text=text, bg=_M_BG_H, fg=_M_TW,
                   font=(_M_TK_ZH, _M_FS_M, 'bold'),
                   anchor=tk.CENTER)
    lbl.pack(expand=True, fill=tk.BOTH)
    f._header_label = lbl
    return f


def m_make_separator(parent, pady=4):
    tk.Frame(parent, bg=_M_LC, height=1).pack(
        fill=tk.X, padx=_px(10), pady=_px(pady))


_M_ST_IDLE = 'idle'
_M_ST_DRAWING = 'drawing'
_M_ST_DRAGGING = 'dragging'
ST_DRAGGING_LABEL = 'dragging_label'
ST_DRAGGING_COBB = 'dragging_cobb'
ST_DRAGGING_BL_MID = 'dragging_bl_mid'
ST_DRAGGING_BL_END = 'dragging_bl_end'


class M_DrawingController:


    def __init__(self, card):
        self.card = card
        self.state = _M_ST_IDLE
        self._drawing_idx = -1
        self._drag_mid = -1
        self._drag_pid = -1
        self._drag_start_sxy = None
        self._drag_moved = False
        self._drag_snapshot_taken = False
        self._hover_sxy = None

        self._label_drag_mid = -1
        self._label_orig_offset = (0.0, 0.0)
        self._label_drag_start_img = (0.0, 0.0)

        self._cobb_orig_offset = (0.0, 0.0)
        self._cobb_drag_start_img = (0.0, 0.0)

        self._bl_end = None         # 'left' / 'right' / 'mid'
        self._bl_orig = None
        self._bl_start_img = (0.0, 0.0)

    @property
    def is_drawing(self):
        return self.state == _M_ST_DRAWING

    @property
    def drawing_first_point(self):
        if not self.is_drawing or self._drawing_idx < 0:
            return None
        res = self.card.res
        if self._drawing_idx >= len(res.measurements):
            return None
        m = res.measurements[self._drawing_idx]
        return m.points[0] if m.n >= 1 else None

    @property
    def hover_point_screen(self):
        return self._hover_sxy

    def _hit_baseline_handle(self, sx, sy):

        card = self.card
        res = card.res
        if not res.baseline_visible:
            return None
        if res.baseline_y is None:
            return None
        hr_px = max(10, int(9 * card.zoom)) + 2

        for end, xi in (('mid', (res.baseline_x1 + res.baseline_x2) / 2),
                        ('left', res.baseline_x1),
                        ('right', res.baseline_x2)):
            ex, ey = card.image_to_screen(xi, res.baseline_y)
            if abs(sx - ex) <= hr_px and abs(sy - ey) <= hr_px:
                return end
        return None

    def _hit_label(self, sx, sy):

        card = self.card
        res = card.res
        if not res.labels_visible:
            return -1

        try:
            items = card.cv.find_overlapping(sx - 1, sy - 1, sx + 1, sy + 1)
            for it in items:
                for t in card.cv.gettags(it):
                    if t.startswith("label_"):
                        try:
                            return int(t.split("_", 1)[1])
                        except Exception:
                            pass
        except Exception:
            pass
        return -1

    def _hit_cobb_label(self, sx, sy):

        card = self.card
        try:
            items = card.cv.find_overlapping(sx - 1, sy - 1, sx + 1, sy + 1)
            for it in items:
                for t in card.cv.gettags(it):
                    if t == "cobb_label":
                        return True
        except Exception:
            pass
        return False

    def on_mouse_down(self, sx, sy):
        card = self.card
        if card.res.img is None:
            return
        if self.state == _M_ST_DRAWING:
            return


        bl_hit = self._hit_baseline_handle(sx, sy)
        if bl_hit is not None:
            res = card.res
            self._bl_end = bl_hit
            self._bl_orig = (res.baseline_x1, res.baseline_x2, res.baseline_y)
            ix, iy = card.screen_to_image(sx, sy)
            self._bl_start_img = (ix, iy)
            self.state = (ST_DRAGGING_BL_MID if bl_hit == 'mid'
                          else ST_DRAGGING_BL_END)
            self._drag_start_sxy = (sx, sy)
            self._drag_moved = False
            self._drag_snapshot_taken = False
            return


        if self._hit_cobb_label(sx, sy):
            self._cobb_orig_offset = tuple(card.res.cobb_label_offset)
            ix, iy = card.screen_to_image(sx, sy)
            self._cobb_drag_start_img = (ix, iy)
            self.state = ST_DRAGGING_COBB
            self._drag_start_sxy = (sx, sy)
            self._drag_moved = False
            self._drag_snapshot_taken = False
            return


        lbl_mid = self._hit_label(sx, sy)
        if lbl_mid >= 0 and lbl_mid < card.res.count:
            m = card.res.measurements[lbl_mid]
            self._label_drag_mid = lbl_mid
            self._label_orig_offset = tuple(m.label_offset)
            ix, iy = card.screen_to_image(sx, sy)
            self._label_drag_start_img = (ix, iy)
            self.state = ST_DRAGGING_LABEL
            self._drag_start_sxy = (sx, sy)
            self._drag_moved = False
            self._drag_snapshot_taken = False
            card.set_active_measurement(lbl_mid)
            return


        ix, iy = card.screen_to_image(sx, sy)
        hit_r_img = _M_HIT_R_ENDPOINT_PX / max(0.3, card.zoom)
        mid, pid = card.res.find_nearest_endpoint_image(ix, iy, hit_r_img)
        if mid >= 0:
            self.state = _M_ST_DRAGGING
            self._drag_mid = mid
            self._drag_pid = pid
            self._drag_start_sxy = (sx, sy)
            self._drag_moved = False
            self._drag_snapshot_taken = False
            card.set_active_measurement(mid)
            return


        self._drag_start_sxy = (sx, sy)


    def on_mouse_move(self, sx, sy):
        st = self.state
        if st == _M_ST_DRAGGING:
            sx0, sy0 = self._drag_start_sxy
            if (not self._drag_moved and
                    abs(sx - sx0) + abs(sy - sy0) > _M_DRAG_THRESHOLD_PX):
                self._drag_moved = True
                if not self._drag_snapshot_taken:
                    self.card.snapshot_push()
                    self._drag_snapshot_taken = True
            if self._drag_moved:
                ix, iy = self.card.screen_to_image(sx, sy)
                self._apply_drag(ix, iy)
            return

        if st == ST_DRAGGING_LABEL:
            sx0, sy0 = self._drag_start_sxy
            if (not self._drag_moved and
                    abs(sx - sx0) + abs(sy - sy0) > _M_DRAG_THRESHOLD_PX):
                self._drag_moved = True
                if not self._drag_snapshot_taken:
                    self.card.snapshot_push()
                    self._drag_snapshot_taken = True
            if self._drag_moved:
                ix, iy = self.card.screen_to_image(sx, sy)
                self._apply_label_drag(ix, iy)
            return

        if st == ST_DRAGGING_COBB:
            sx0, sy0 = self._drag_start_sxy
            if (not self._drag_moved and
                    abs(sx - sx0) + abs(sy - sy0) > _M_DRAG_THRESHOLD_PX):
                self._drag_moved = True
                if not self._drag_snapshot_taken:
                    self.card.snapshot_push()
                    self._drag_snapshot_taken = True
            if self._drag_moved:
                ix, iy = self.card.screen_to_image(sx, sy)
                self._apply_cobb_drag(ix, iy)
            return

        if st in (ST_DRAGGING_BL_MID, ST_DRAGGING_BL_END):
            sx0, sy0 = self._drag_start_sxy
            if (not self._drag_moved and
                    abs(sx - sx0) + abs(sy - sy0) > _M_DRAG_THRESHOLD_PX):
                self._drag_moved = True
                if not self._drag_snapshot_taken:
                    self.card.snapshot_push()
                    self._drag_snapshot_taken = True
            if self._drag_moved:
                ix, iy = self.card.screen_to_image(sx, sy)
                self._apply_baseline_drag(ix, iy)
            return

    def on_mouse_up(self, sx, sy):
        card = self.card
        st = self.state

        if st == _M_ST_DRAGGING:
            self._reset_drag()
            card.redraw_overlay()
            card.notify_updated()
            return

        if st == ST_DRAGGING_LABEL:
            self._reset_drag()
            card.redraw_overlay()
            card.notify_updated()
            return

        if st == ST_DRAGGING_COBB:
            self._reset_drag()
            card.redraw_overlay()
            card.notify_updated()
            return

        if st in (ST_DRAGGING_BL_MID, ST_DRAGGING_BL_END):
            self._reset_drag()
            card.redraw_overlay()
            card.notify_updated()
            return

        if self.state == _M_ST_DRAWING:
            if card.res.img is None:
                return
            ix, iy = card.screen_to_image(sx, sy)
            ih, iw = card.res.img.shape[:2]
            ix = max(0.0, min(float(iw), ix))
            iy = max(0.0, min(float(ih), iy))


            fp = self.drawing_first_point
            if fp is not None:
                px_dist = math.hypot((ix - fp[0]) * card.zoom,
                                     (iy - fp[1]) * card.zoom)
                if px_dist < _M_DRAG_THRESHOLD_PX * 2:
                    self._cancel_drawing()
                    card.redraw_overlay()
                    card.notify_updated()
                    return

            m = card.res.measurements[self._drawing_idx]
            m.points.append((float(ix), float(iy)))
            m.recompute()
            if card.res.confirmed:
                card.res.recompute_max_cobb()
            self.state = _M_ST_IDLE
            self._drawing_idx = -1
            card.redraw_overlay()
            card.notify_updated()
            return


        if card.res.img is None:
            return
        if self._drag_start_sxy is not None:
            sx0, sy0 = self._drag_start_sxy
            if abs(sx - sx0) + abs(sy - sy0) > _M_DRAG_THRESHOLD_PX:
                self._drag_start_sxy = None
                return
        self._drag_start_sxy = None

        ix, iy = card.screen_to_image(sx, sy)
        ih, iw = card.res.img.shape[:2]
        ix = max(0.0, min(float(iw), ix))
        iy = max(0.0, min(float(ih), iy))

        card.snapshot_push()
        m = card.res.new_measurement()
        m.points.append((float(ix), float(iy)))
        m.recompute()
        self.state = _M_ST_DRAWING
        self._drawing_idx = card.res.active_idx
        card.redraw_overlay()
        card.notify_updated()

    def on_mouse_hover(self, sx, sy):
        if self.state == _M_ST_DRAWING:
            self._hover_sxy = (sx, sy)
            self.card.redraw_overlay()
        else:
            if self._hover_sxy is not None:
                self._hover_sxy = None

    def on_escape(self):
        st = self.state
        if st == _M_ST_DRAWING:
            self._cancel_drawing()
            self.card.redraw_overlay()
            self.card.notify_updated()
        elif st in (_M_ST_DRAGGING, ST_DRAGGING_LABEL, ST_DRAGGING_COBB,
                    ST_DRAGGING_BL_MID, ST_DRAGGING_BL_END):
            if self._drag_snapshot_taken:
                self.card.undo()
            self._reset_drag()

    def _apply_drag(self, ix, iy):
        res = self.card.res
        if not (0 <= self._drag_mid < len(res.measurements)):
            return
        m = res.measurements[self._drag_mid]
        if not (0 <= self._drag_pid < len(m.points)):
            return
        ih, iw = res.img.shape[:2]
        ix = max(0.0, min(float(iw), ix))
        iy = max(0.0, min(float(ih), iy))
        m.points[self._drag_pid] = (ix, iy)
        m.recompute()
        if res.confirmed:
            res.recompute_max_cobb()
        self.card.redraw_overlay()

    def _apply_label_drag(self, ix, iy):
        res = self.card.res
        mid = self._label_drag_mid
        if not (0 <= mid < len(res.measurements)):
            return
        m = res.measurements[mid]
        dx = ix - self._label_drag_start_img[0]
        dy = iy - self._label_drag_start_img[1]
        ox, oy = self._label_orig_offset
        m.label_offset = (ox + dx, oy + dy)
        self.card.redraw_overlay()

    def _apply_cobb_drag(self, ix, iy):
        res = self.card.res
        dx = ix - self._cobb_drag_start_img[0]
        dy = iy - self._cobb_drag_start_img[1]
        ox, oy = self._cobb_orig_offset
        res.cobb_label_offset = (ox + dx, oy + dy)
        self.card.redraw_overlay()

    def _apply_baseline_drag(self, ix, iy):
        res = self.card.res
        if res.img is None or self._bl_orig is None:
            return
        ih, iw = res.img.shape[:2]
        ix = max(0.0, min(float(iw), ix))
        iy = max(0.0, min(float(ih), iy))
        ox1, ox2, oy = self._bl_orig
        sx, sy = self._bl_start_img
        dx = ix - sx
        dy = iy - sy
        if self._bl_end == 'mid':

            res.baseline_x1 = ox1 + dx
            res.baseline_x2 = ox2 + dx
            res.baseline_y = oy + dy
        elif self._bl_end == 'left':
            res.baseline_x1 = ox1 + dx
            res.baseline_y = oy + dy

            if res.baseline_x1 > res.baseline_x2 - 20:
                res.baseline_x1 = res.baseline_x2 - 20
        elif self._bl_end == 'right':
            res.baseline_x2 = ox2 + dx
            res.baseline_y = oy + dy
            if res.baseline_x2 < res.baseline_x1 + 20:
                res.baseline_x2 = res.baseline_x1 + 20
        # Clamp y
        res.baseline_y = max(0.0, min(float(ih), res.baseline_y))
        self.card.redraw_overlay()

    def _reset_drag(self):
        self.state = _M_ST_IDLE
        self._drag_mid = -1
        self._drag_pid = -1
        self._drag_start_sxy = None
        self._drag_moved = False
        self._drag_snapshot_taken = False
        self._label_drag_mid = -1
        self._label_orig_offset = (0.0, 0.0)
        self._cobb_orig_offset = (0.0, 0.0)
        self._bl_end = None
        self._bl_orig = None

    def _cancel_drawing(self):
        if self._drawing_idx < 0:
            return
        self._drawing_idx = -1
        self.state = _M_ST_IDLE
        self._hover_sxy = None
        self.card.undo()


class M_CanvasRenderer:


    def __init__(self, card):
        self.card = card

    def redraw_image(self):
        card = self.card
        cv = card.cv
        cv.delete("bg_image")
        card._tkimg = None
        if card.res.img is None:
            cv.create_text(
                cv.winfo_width() // 2 or 100,
                cv.winfo_height() // 2 or 100,
                text="请加载图像 (双击左侧文件列表)",
                fill=_M_TG, font=(_M_TK_ZH, _M_FS_L),
                justify=tk.CENTER, tags=("bg_image",))
            return
        disp = card.get_display_image()
        h, w = disp.shape[:2]
        dw = max(1, int(w * card.zoom))
        dh = max(1, int(h * card.zoom))
        interp = cv2.INTER_AREA if card.zoom < 1 else cv2.INTER_CUBIC
        resized = cv2.resize(disp, (dw, dh), interpolation=interp)
        card._tkimg = ImageTk.PhotoImage(
            Image.fromarray(cv2.cvtColor(resized, cv2.COLOR_BGR2RGB)))
        cv.create_image(card.off[0], card.off[1],
                        anchor=tk.NW, image=card._tkimg,
                        tags=("bg_image",))
        cv.tag_lower("bg_image")
        try:
            card.lbl_zoom.configure(text=f"{card.zoom * 100:.0f}%")
        except Exception:
            pass

    def redraw_overlay(self):
        card = self.card
        cv = card.cv
        cv.delete("meas")
        if card.res.img is None:
            return
        h, w = card.res.img.shape[:2]
        max_ia, max_ib = card.res.max_pair_indices

        solo = (card.res.solo_max_mode and card.res.confirmed
                and card.res.cobb_max_pair is not None)
        keep_set = {max_ia, max_ib} if solo else None

        self._draw_baseline(w, h)

        for mi, m in enumerate(card.res.measurements):
            if not m.visible:
                continue
            if solo and mi not in keep_set:
                continue
            is_high = ((mi in (max_ia, max_ib)) and card.res.confirmed)
            is_active = (mi == card.res.active_idx)
            self._draw_measurement(m, mi, w, h,
                                   is_high=is_high, is_active=is_active)

        if card.res.confirmed and card.res.cobb_max_pair is not None:
            ia, ib, ang = card.res.cobb_max_pair
            if 0 <= ia < card.res.count and 0 <= ib < card.res.count:
                ma = card.res.measurements[ia]
                mb = card.res.measurements[ib]
                if ma.ok and mb.ok and ma.visible and mb.visible:
                    self._draw_cobb_arc(ma, mb, ang, w, h)


        dc = card.drawer
        if dc.is_drawing:
            fp = dc.drawing_first_point
            hp = dc.hover_point_screen
            if fp is not None and hp is not None:
                sx1, sy1 = card.image_to_screen(*fp)
                sx2, sy2 = hp
                cv.create_line(sx1, sy1, sx2, sy2,
                               fill='#6B7280', dash=(5, 3),
                               width=max(1, int(2 * card.zoom)),
                               tags=("meas",))
                r = 4
                cv.create_oval(sx1 - r, sy1 - r, sx1 + r, sy1 + r,
                               fill=_M_LINE_COLOR, outline='white',
                               width=2, tags=("meas",))
                cv.create_oval(sx2 - r, sy2 - r, sx2 + r, sy2 + r,
                               outline='#6B7280', fill='white',
                               width=1, tags=("meas",))

        try:
            cv.tag_raise("meas")
        except Exception:
            pass

    def _draw_measurement(self, m, mi, w, h, is_high, is_active):
        card = self.card
        cv = card.cv
        pts = m.points
        res = card.res
        dim = m.dimmed
        c = res.render_color_for(mi)
        role = res.max_pair_role(mi)
        glow = _M_HL_A_GLOW if role == 'A' else (_M_HL_B_GLOW if role == 'B' else None)

        if m.ok:
            x1, y1 = card.image_to_screen(*pts[0])
            x2, y2 = card.image_to_screen(*pts[1])

            if is_high:
                lw = max(4.5, 5.2 * card.zoom)
            else:
                lw = max(2, 2.4 * card.zoom)
            stipple = 'gray50' if dim else ''


            if is_high and glow:
                cv.create_line(x1, y1, x2, y2, fill=glow,
                               width=lw + max(10, 12 * card.zoom),
                               stipple='gray50',
                               capstyle=tk.ROUND, tags=("meas",))
                cv.create_line(x1, y1, x2, y2, fill=glow,
                               width=lw + max(5, 6 * card.zoom),
                               capstyle=tk.ROUND, tags=("meas",))


            cv.create_line(x1, y1, x2, y2, fill=c, width=lw,
                           stipple=stipple,
                           capstyle=tk.ROUND, tags=("meas",))


            if is_high:
                cv.create_line(x1, y1, x2, y2, fill='#FFFFFF',
                               width=max(1.2, 1.4 * card.zoom),
                               dash=(3, 5), tags=("meas",))


            ext = max(w, h) * 0.18
            a, b = m_line_extended(pts[0], pts[1], ext)
            ax1, ay1 = card.image_to_screen(*a)
            ax2, ay2 = card.image_to_screen(*b)
            cv.create_line(ax1, ay1, ax2, ay2, fill=c,
                           width=max(1, 1.1 * card.zoom),
                           dash=(6, 4), stipple=stipple,
                           tags=("meas",))


        r = max(4.0, _M_PT_R * card.zoom * (1.3 if is_high else 1.0))
        for i, p in enumerate(pts):
            sx, sy = card.image_to_screen(*p)
            cr = r + (2.5 if is_high else 1.5)
            if is_active:
                cv.create_oval(sx - cr - 3, sy - cr - 3,
                               sx + cr + 3, sy + cr + 3,
                               outline=c, fill='',
                               width=max(1.5, 1.8 * card.zoom),
                               tags=("meas",))
            cv.create_oval(sx - cr, sy - cr, sx + cr, sy + cr,
                           fill='white', outline='white', tags=("meas",))
            cv.create_oval(sx - r, sy - r, sx + r, sy + r,
                           fill=c, outline='white',
                           width=max(1, 1.2 * card.zoom) if is_high else 1,
                           stipple='gray50' if dim else '',
                           tags=("meas",))

            fsz = max(8, int(10 * card.zoom))
            cv.create_text(sx + r + 4, sy - r - 4,
                           text=f"{m.label}-{i+1}", fill=c,
                           anchor=tk.W,
                           font=(_M_TK_EN, fsz, "bold"),
                           tags=("meas",))


        if m.ok and card.res.labels_visible:

            p0x, p0y = pts[0]


            default_lx = p0x - 90
            default_ly = p0y
            lx = default_lx + m.label_offset[0]
            ly = default_ly + m.label_offset[1]
            cx, cy = card.image_to_screen(lx, ly)


            base_fs = card.res.label_font_size
            fsz = max(8, int(base_fs * card.zoom
                             * (1.15 if is_high else 1.0)))
            mark = f"  ★{role}" if is_high else ("  ·" if dim else "")
            txt = f"{m.label}: {m.tilt:.1f}°{mark}"

            try:
                import tkinter.font as tkfont
                font_obj = tkfont.Font(family=_M_TK_EN, size=fsz, weight='bold')
                txt_w = font_obj.measure(txt)
                txt_h = font_obj.metrics('linespace')
            except Exception:
                txt_w = int(len(txt) * fsz * 0.72)
                txt_h = int(fsz * 1.4)
            pad_x = max(5, int(0.5 * fsz))
            pad_y = max(3, int(0.3 * fsz))

            fill_bg = '#FFFCEE' if is_high else '#FFFFFF'


            rx2 = cx
            rx1 = cx - txt_w - 2 * pad_x
            ry1 = cy - txt_h / 2 - pad_y
            ry2 = cy + txt_h / 2 + pad_y
            lbl_tag = f"label_{mi}"
            cv.create_rectangle(rx1, ry1, rx2, ry2,
                                fill=fill_bg, outline=c,
                                width=(max(1.6, 1.8 * card.zoom)
                                       if is_high else 1.2),
                                stipple='gray50' if dim else '',
                                tags=("meas", lbl_tag, "angle_label"))
            cv.create_text((rx1 + rx2) / 2, cy, text=txt, fill=c,
                           anchor=tk.CENTER,
                           font=(_M_TK_EN, fsz, "bold"),
                           tags=("meas", lbl_tag, "angle_label"))


    def _draw_baseline(self, w, h):


        card = self.card
        cv = card.cv
        res = card.res
        if not res.baseline_visible:
            return
        if res.baseline_y is None or res.baseline_x1 is None or res.baseline_x2 is None:
            return
        y_img = res.baseline_y
        x1_img = res.baseline_x1
        x2_img = res.baseline_x2

        sx1, sy1 = card.image_to_screen(x1_img, y_img)
        sx2, sy2 = card.image_to_screen(x2_img, y_img)
        smx, smy = card.image_to_screen((x1_img + x2_img) / 2, y_img)


        BL_COLOR = '#7DD3FC'
        BL_ACCENT = '#0EA5E9'
        lw = max(1.0, 1.2 * card.zoom)


        cv.create_line(sx1, sy1, sx2, sy2, fill=BL_COLOR,
                       width=lw, dash=(2, 4),
                       capstyle=tk.ROUND,
                       tags=("meas", "baseline_line"))


        hr = max(5.0, 6.0 * card.zoom)

        cv.create_rectangle(sx1 - hr, sy1 - hr, sx1 + hr, sy1 + hr,
                            fill='white', outline=BL_ACCENT,
                            width=max(1.4, 1.6 * card.zoom),
                            tags=("meas", "baseline_handle",
                                  "baseline_handle_left"))
        cv.create_rectangle(sx1 - hr * 0.5, sy1 - hr * 0.5,
                            sx1 + hr * 0.5, sy1 + hr * 0.5,
                            fill=BL_ACCENT, outline='',
                            tags=("meas", "baseline_handle",
                                  "baseline_handle_left"))

        cv.create_rectangle(sx2 - hr, sy2 - hr, sx2 + hr, sy2 + hr,
                            fill='white', outline=BL_ACCENT,
                            width=max(1.4, 1.6 * card.zoom),
                            tags=("meas", "baseline_handle",
                                  "baseline_handle_right"))
        cv.create_rectangle(sx2 - hr * 0.5, sy2 - hr * 0.5,
                            sx2 + hr * 0.5, sy2 + hr * 0.5,
                            fill=BL_ACCENT, outline='',
                            tags=("meas", "baseline_handle",
                                  "baseline_handle_right"))

        hr2 = hr * 1.1
        cv.create_oval(smx - hr2, smy - hr2, smx + hr2, smy + hr2,
                       fill='white', outline=BL_ACCENT,
                       width=max(1.4, 1.6 * card.zoom),
                       tags=("meas", "baseline_handle",
                             "baseline_handle_mid"))
        cv.create_oval(smx - hr2 * 0.45, smy - hr2 * 0.45,
                       smx + hr2 * 0.45, smy + hr2 * 0.45,
                       fill=BL_ACCENT, outline='',
                       tags=("meas", "baseline_handle",
                             "baseline_handle_mid"))


        fsz = max(9, int(10 * card.zoom))
        cv.create_text(sx1 - hr - 6, sy1, text="水平基准",
                       fill=BL_ACCENT, anchor=tk.E,
                       font=(_M_TK_ZH, fsz, "bold"),
                       tags=("meas",))

    def _draw_cobb_arc(self, ma, mb, ang, w, h):
        card = self.card
        cv = card.cv
        p1, p2 = ma.points[0], ma.points[1]
        p3, p4 = mb.points[0], mb.points[1]
        mx, my = m_line_intersection(p1, p2, p3, p4)
        mx = max(-w, min(2 * w, mx))
        my = max(-h, min(2 * h, my))
        cx, cy = card.image_to_screen(mx, my)
        r_img = min(w, h) * 0.12
        r = max(16, r_img * card.zoom)
        a1 = math.degrees(math.atan2(p2[1] - p1[1], p2[0] - p1[0]))
        a2 = math.degrees(math.atan2(p4[1] - p3[1], p4[0] - p3[0]))
        t1, t2 = min(a1, a2), max(a1, a2)
        if not (0.5 < abs(t2 - t1) < 170):
            return

        cv.create_arc(cx - r, cy - r, cx + r, cy + r,
                      start=-t2, extent=-(t1 - t2),
                      style=tk.ARC, outline='#FECACA',
                      width=max(4.5, 5.5 * card.zoom),
                      tags=("meas",))

        cv.create_arc(cx - r, cy - r, cx + r, cy + r,
                      start=-t2, extent=-(t1 - t2),
                      style=tk.ARC, outline=_M_HL_ARC,
                      width=max(2.8, 3.4 * card.zoom),
                      tags=("meas",))


        ma_rad = math.radians((t1 + t2) / 2)

        default_lx_img = mx + (r_img * 1.3) * math.cos(ma_rad)
        default_ly_img = my + (r_img * 1.3) * math.sin(ma_rad)
        ox, oy = card.res.cobb_label_offset
        lx_img = default_lx_img + ox
        ly_img = default_ly_img + oy
        tx, ty = card.image_to_screen(lx_img, ly_img)

        fsz = max(12, int(13 * card.zoom))
        txt = f"★ Cobb Max = {ang:.2f}°"

        try:
            import tkinter.font as tkfont
            fobj = tkfont.Font(family=_M_TK_EN, size=fsz, weight='bold')
            txt_w = fobj.measure(txt)
            txt_h = fobj.metrics('linespace')
        except Exception:
            txt_w = int(len(txt) * fsz * 0.64)
            txt_h = int(fsz * 1.4)
        pad_x = max(6, int(0.5 * fsz))
        pad_y = max(3, int(0.3 * fsz))
        cv.create_rectangle(tx - txt_w / 2 - pad_x,
                            ty - txt_h / 2 - pad_y,
                            tx + txt_w / 2 + pad_x,
                            ty + txt_h / 2 + pad_y,
                            fill='#FFFCEE', outline=_M_HL_ARC,
                            width=max(1.6, 1.8 * card.zoom),
                            tags=("meas", "cobb_label"))
        cv.create_text(tx, ty, text=txt, fill='#B91C1C',
                       anchor=tk.CENTER,
                       font=(_M_TK_EN, fsz, "bold"),
                       tags=("meas", "cobb_label"))


class M_AnalysisRenderer:
    def __init__(self, parent, font_scale=1.0):
        self.parent = parent
        self.font_scale = font_scale
        self.fig = Figure(figsize=(4.5, 4.5), dpi=100, facecolor=_M_SCI_BG)
        self.ax = self.fig.add_subplot(111)
        self.canvas = FigureCanvasTkAgg(self.fig, master=parent)
        self.widget = self.canvas.get_tk_widget()
        self.widget.configure(bg='white', highlightthickness=0)

        self._last_res = None

        self.widget.bind("<Button-3>", self._on_rclick)
        self.widget.bind("<Button-2>", self._on_rclick)

    def _on_rclick(self, e):
        menu = tk.Menu(self.widget, tearoff=0,
                       bg='white', fg=_M_TW,
                       activebackground=_M_ACC, activeforeground='white',
                       font=(_M_TK_ZH, _M_FS_N))
        menu.add_command(label=f"当前字号: {self.font_scale:.2f}×",
                         state='disabled')
        menu.add_separator()
        menu.add_command(label="🔍+  字号 + (+0.10)",
                         command=lambda: self.set_font_scale(self.font_scale + 0.10))
        menu.add_command(label="🔍++  字号 ++ (+0.25)",
                         command=lambda: self.set_font_scale(self.font_scale + 0.25))
        menu.add_separator()
        menu.add_command(label="🔎-  字号 - (-0.10)",
                         command=lambda: self.set_font_scale(self.font_scale - 0.10))
        menu.add_command(label="🔎--  字号 -- (-0.25)",
                         command=lambda: self.set_font_scale(self.font_scale - 0.25))
        menu.add_separator()
        menu.add_command(label="↺  重置为默认 (1.00×)",
                         command=lambda: self.set_font_scale(1.0))
        try:
            menu.tk_popup(e.x_root, e.y_root)
        finally:
            menu.grab_release()

    def set_font_scale(self, scale):
        scale = max(0.4, min(3.0, float(scale)))

        scale = round(scale, 2)
        if abs(scale - self.font_scale) < 0.005:
            return
        self.font_scale = scale
        if self._last_res is not None:
            self.render(self._last_res)

    def render(self, res):
        self._last_res = res
        self.fig.clear()
        ax = self.fig.add_subplot(111)
        self.ax = ax
        fs = self.font_scale
        ax.set_facecolor(_M_SCI_BG)

        if res is None or res.img is None:
            ax.text(0.5, 0.5, '尚未加载图像',
                    ha='center', va='center',
                    transform=ax.transAxes,
                    fontsize=12 * fs, color=_M_TG,
                    fontproperties=m_zhfp(12 * fs))
            ax.axis('off')
            self.canvas.draw_idle()
            return

        ok_list = [(i, m) for i, m in enumerate(res.measurements) if m.ok]
        if not ok_list:
            ax.text(0.5, 0.5,
                    "尚无完整线条\n在左图点击 2 次画一条线",
                    ha='center', va='center',
                    transform=ax.transAxes,
                    fontsize=11 * fs, color=_M_SCI_AX,
                    fontproperties=m_zhfp(11 * fs))
            ax.axis('off')
            self.canvas.draw_idle()
            return

        labels = [m.label for _, m in ok_list]
        values = [m.tilt for _, m in ok_list]
        colors = [res.render_color_for(i) for i, _ in ok_list]
        dim_flags = [m.dimmed for _, m in ok_list]
        max_ia, max_ib = res.max_pair_indices
        high_flags = [(i in (max_ia, max_ib)) and res.confirmed
                      for i, _ in ok_list]
        roles = [res.max_pair_role(i) for i, _ in ok_list]

        n = len(ok_list)
        y_pos = np.arange(n)[::-1]


        bar_h = max(0.55, min(0.86, 0.62 + 0.10 * (fs - 1.0)))

        for i, hi in enumerate(high_flags):
            if hi:
                ax.axhspan(y_pos[i] - bar_h * 0.72, y_pos[i] + bar_h * 0.72,
                           facecolor='#FEF3C7', alpha=0.35, zorder=0)

        bars = ax.barh(y_pos, values, color=colors, alpha=0.92,
                       edgecolor='white', linewidth=1.2, height=bar_h,
                       zorder=3)
        for bar, dim, high in zip(bars, dim_flags, high_flags):
            if dim:
                bar.set_alpha(0.28)
                bar.set_edgecolor('#BBBBBB')
            elif high:
                bar.set_edgecolor('#B91C1C')
                bar.set_linewidth(2.2)

        max_v = max(max(values), 1.0)
        for i, v in enumerate(values):
            if high_flags[i]:
                star = f"  ★{roles[i]}"
            elif dim_flags[i]:
                star = "  ·"
            else:
                star = ""
            txt_color = colors[i] if not dim_flags[i] else '#9CA3AF'


            fp_tick = m_zhfp(10 * fs, 'bold') if star.strip() else m_enfp(10 * fs, 'bold')
            ax.text(v + max_v * 0.015, y_pos[i],
                    f'{v:.1f}°{star}',
                    va='center', ha='left',
                    fontsize=10 * fs, color=txt_color, fontweight='bold',
                    fontproperties=fp_tick)

        ax.axvline(0, color='#9CA3AF', ls=(0, (6, 4)), lw=0.8, alpha=0.8)
        ax.set_yticks(y_pos)
        ax.set_yticklabels(labels, fontproperties=m_enfp(10 * fs, 'bold'))
        for tl, col, dim in zip(ax.get_yticklabels(), colors, dim_flags):
            tl.set_color(col if not dim else '#9CA3AF')
        ax.tick_params(axis='y', length=0, labelsize=10 * fs)
        ax.tick_params(axis='x', labelsize=9 * fs, colors=_M_SCI_AX_LIGHT)
        ax.set_xlim(0, max_v * 1.28)
        ax.set_xlabel('与水平线夹角 (°)',
                      fontsize=10.5 * fs,
                      fontproperties=m_zhfp(10.5 * fs),
                      color=_M_SCI_AX, labelpad=8)
        ax.grid(True, axis='x', alpha=0.35, ls='-',
                color=_M_SCI_GRID, lw=0.5, zorder=0)
        for sp in ['top', 'right']:
            ax.spines[sp].set_visible(False)
        for sp in ['left', 'bottom']:
            ax.spines[sp].set_color('#BBBBBB')
            ax.spines[sp].set_linewidth(0.8)


        active_vals = [v for v, d in zip(values, dim_flags) if not d]
        amean = float(np.mean(active_vals)) if active_vals else 0.0
        astd = (float(np.std(active_vals, ddof=1))
                if len(active_vals) > 1 else 0.0)

        if res.confirmed and res.cobb_max_pair is not None:
            ia, ib, ang_max = res.cobb_max_pair
            la = res.measurements[ia].label
            lb = res.measurements[ib].label
            summary = (f"n = {n}\n"
                       f"Max pair: {la} + {lb}\n"
                       f"★ Cobb = {ang_max:.2f}°\n"
                       f"Mean = {amean:.1f}° ± {astd:.1f}°")
            box_fc = '#FFFCEE'
            box_ec = '#B91C1C'
            tit = f'倾角分布  ·  n = {n}  ·  ★ Max Cobb = {ang_max:.2f}°'
            tcol = '#991B1B'
        else:
            summary = (f"n = {n}\n"
                       f"Max tilt = {max(values):.1f}°\n"
                       f"Min tilt = {min(values):.1f}°\n"
                       f"Mean = {amean:.1f}°\n"
                       f"(未确认 — 请按 Enter)")
            box_fc = '#F9FAFB'
            box_ec = '#BBBBBB'
            tit = f'倾角分布  ·  n = {n}  ·  (未确认)'
            tcol = _M_SCI_AX

        anno = ax.annotate(summary, xy=(0.97, 0.04),
                           xycoords='axes fraction',
                           ha='right', va='bottom',
                           multialignment='left',
                           fontsize=10 * fs, color=_M_SCI_AX,
                           fontproperties=m_zhfp(10 * fs),
                           bbox=dict(boxstyle='round,pad=0.55',
                                     fc=box_fc, edgecolor=box_ec, lw=1.0))

        try:
            anno.draggable()
        except Exception:
            pass

        ax.set_title(tit, fontsize=12.5 * fs, fontweight='bold',
                     color=tcol, pad=12,
                     fontproperties=m_zhfp(12.5 * fs, 'bold'))
        try:
            base_w, base_h = 4.5, 4.5
            target_h = max(base_h, base_h + (fs - 1.0) * 1.3)
            cur_w, cur_h = self.fig.get_size_inches()
            if abs(cur_h - target_h) > 0.05:
                self.fig.set_size_inches(cur_w if cur_w >= base_w else base_w,
                                         target_h, forward=True)
        except Exception:
            pass
        try:
            left   = max(0.18, min(0.32, 0.18 + 0.05 * (fs - 1.0)))
            bottom = max(0.12, min(0.24, 0.13 + 0.04 * (fs - 1.0)))
            top    = max(0.84, min(0.92, 0.92 - 0.02 * (fs - 1.0)))
            right  = 0.96
            self.fig.subplots_adjust(left=left, right=right,
                                     top=top, bottom=bottom)
        except Exception:
            pass
        self.canvas.draw_idle()


class M_AnnotatedRenderer:
    def __init__(self, font_scale=1.0):
        self.font_scale = font_scale
        self.fig = Figure(figsize=(6.5, 9.0), dpi=100, facecolor='white')
        self.ax = self.fig.add_subplot(111)

    def render(self, res, img_bgr=None, title_extra=""):
        self.fig.clear()
        ax = self.fig.add_subplot(111)
        self.ax = ax
        fs = self.font_scale
        if res is None or res.img is None:
            ax.axis('off')
            return
        img = img_bgr if img_bgr is not None else res.img
        ih, iw = img.shape[:2]
        ax.imshow(cv2.cvtColor(img, cv2.COLOR_BGR2RGB))
        ax.set_xlim(0, iw)
        ax.set_ylim(ih, 0)

        max_ia, max_ib = res.max_pair_indices
        solo = (getattr(res, 'solo_max_mode', False) and res.confirmed
                and res.cobb_max_pair is not None)
        keep_set = {max_ia, max_ib} if solo else None
        handles, labels = [], []
        for mid, m in enumerate(res.measurements):
            if not (m.ok and m.visible):
                continue
            if solo and mid not in keep_set:
                continue
            is_high = ((mid in (max_ia, max_ib)) and res.confirmed)
            role = res.max_pair_role(mid)
            col = res.render_color_for(mid)
            alpha = 0.32 if m.dimmed else 1.0
            lw = (4.5 if is_high else 2.4) * fs
            p1, p2 = m.points[0], m.points[1]

            ext = max(iw, ih) * 0.22
            a, b = m_line_extended(p1, p2, ext)
            ax.plot([a[0], b[0]], [a[1], b[1]],
                    color=col, lw=0.9, ls=(0, (5, 3)),
                    alpha=alpha * 0.55, zorder=3)

            if is_high:
                glow = _M_HL_A_GLOW if role == 'A' else _M_HL_B_GLOW
                ax.plot([p1[0], p2[0]], [p1[1], p2[1]],
                        color=glow, lw=lw + 9, alpha=0.55,
                        solid_capstyle='round', zorder=5)

            h, = ax.plot([p1[0], p2[0]], [p1[1], p2[1]],
                         color=col, lw=lw, alpha=alpha,
                         zorder=(7 if is_high else 5),
                         solid_capstyle='round')
            handles.append(h)
            mark = (f"  ★{role}" if is_high
                    else ("  ·" if m.dimmed else ""))
            labels.append(f"{m.label} = {m.tilt:.1f}°{mark}")

            for pp in (p1, p2):
                ax.scatter([pp[0]], [pp[1]], c=col,
                           s=(85 if is_high else 50) * fs,
                           edgecolors='white',
                           linewidths=1.6 if is_high else 1.2,
                           alpha=alpha,
                           zorder=(10 if is_high else 8))

        if res.confirmed and res.cobb_max_pair is not None:
            ia, ib, ang = res.cobb_max_pair
            if 0 <= ia < len(res.measurements) and 0 <= ib < len(res.measurements):
                ma = res.measurements[ia]
                mb = res.measurements[ib]
                if ma.ok and mb.ok:
                    self._draw_arc(ax, ma, mb, ang, iw, ih)

        if res.confirmed and res.cobb_max_pair is not None:
            _, _, ang = res.cobb_max_pair
            title = f'★ Cobb 最大值 = {ang:.2f}°   (n = {len(res.ok_list)})'
            tcol = '#991B1B'
        elif res.count > 0:
            title = f'已绘线数 = {len(res.ok_list)}   (未确认)'
            tcol = _M_SCI_AX
        else:
            title = 'Cobb 测量图'
            tcol = _M_SCI_AX
        if title_extra:
            title = f"{title_extra}  ·  {title}"
        ax.set_title(title, fontsize=14 * fs, fontweight='bold',
                     color=tcol, pad=14,
                     fontproperties=m_zhfp(14 * fs, 'bold'))
        ax.axis('off')

        if handles:
            leg = ax.legend(handles, labels,
                            loc='upper left',
                            bbox_to_anchor=(1.01, 1.0),
                            fontsize=10 * fs, framealpha=0.95,
                            facecolor='white', edgecolor='#CCCCCC',
                            prop=m_zhfp(10 * fs, 'bold'),
                            title='线段  (Lines)',
                            title_fontproperties=m_zhfp(10.5 * fs, 'bold'))
            leg.set_draggable(True)
            self.fig.subplots_adjust(right=0.78)
        try:
            self.fig.tight_layout(pad=1.0)
        except Exception:
            pass

    def _draw_arc(self, ax, ma, mb, cobb_val, iw, ih):
        p1, p2 = ma.points[0], ma.points[1]
        p3, p4 = mb.points[0], mb.points[1]
        mx, my = m_line_intersection(p1, p2, p3, p4)
        mx = max(-iw, min(2 * iw, mx))
        my = max(-ih, min(2 * ih, my))
        r = min(iw, ih) * 0.12
        a1 = math.degrees(math.atan2(p2[1] - p1[1], p2[0] - p1[0]))
        a2 = math.degrees(math.atan2(p4[1] - p3[1], p4[0] - p3[0]))
        t1, t2 = min(a1, a2), max(a1, a2)
        if not (0.5 < abs(t2 - t1) < 170):
            return
        ax.add_patch(Arc((mx, my), r * 2, r * 2, angle=0,
                         theta1=t1, theta2=t2,
                         color='#FECACA', lw=6.5, zorder=8, alpha=0.75))
        ax.add_patch(Arc((mx, my), r * 2, r * 2, angle=0,
                         theta1=t1, theta2=t2,
                         color=_M_HL_ARC, lw=3.0, zorder=9))
        ang_mid = math.radians((t1 + t2) / 2)
        tx = mx + r * 1.00 * math.cos(ang_mid)
        ty = my + r * 1.00 * math.sin(ang_mid)
        fsz = 12 * self.font_scale
        ax.annotate(f'★ 最大 Cobb\n{cobb_val:.2f}°',
                    xy=(tx, ty),
                    ha='center', va='center',
                    color='#B91C1C',
                    fontsize=fsz, fontweight='bold',
                    fontproperties=m_zhfp(fsz, 'bold'),
                    bbox=dict(boxstyle='round,pad=0.5',
                              fc='#FFFCEE',
                              edgecolor=_M_HL_ARC, lw=1.6),
                    zorder=12)


class M_AggregateRenderer:


    MODES = ['bar', 'box', 'scatter', 'line']
    MODE_LABELS = {
        'bar':     '柱形图',
        'box':     '箱线图',
        'scatter': '散点图',
        'line':    '折线图',
    }
    MODE_SUBS = {
        'bar':     '每会话 Max Cobb',
        'box':     '每会话倾角分布',
        'scatter': '每会话倾角散点 (★ 为最大对)',
        'line':    'Max Cobb 趋势',
    }

    def __init__(self, parent, font_scale=1.0):
        self.parent = parent
        self.font_scale = font_scale
        self.fig = Figure(figsize=(9.0, 3.8), dpi=100, facecolor=_M_SCI_BG)
        self.ax = self.fig.add_subplot(111)
        self.canvas = FigureCanvasTkAgg(self.fig, master=parent)
        self.widget = self.canvas.get_tk_widget()
        self.widget.configure(bg='white', highlightthickness=0)
        self._last_data = None
        self.mode = 'bar'

        self.widget.bind("<Button-3>", self._on_rclick)
        self.widget.bind("<Button-2>", self._on_rclick)

    def _on_rclick(self, e):
        menu = tk.Menu(self.widget, tearoff=0,
                       bg='white', fg=_M_TW,
                       activebackground=_M_ACC, activeforeground='white',
                       font=(_M_TK_ZH, _M_FS_N))
        menu.add_command(label=f"当前字号: {self.font_scale:.2f}×",
                         state='disabled')
        menu.add_separator()
        menu.add_command(label="🔍+  字号 + (+0.10)",
                         command=lambda: self.set_font_scale(self.font_scale + 0.10))
        menu.add_command(label="🔍++  字号 ++ (+0.25)",
                         command=lambda: self.set_font_scale(self.font_scale + 0.25))
        menu.add_separator()
        menu.add_command(label="🔎-  字号 - (-0.10)",
                         command=lambda: self.set_font_scale(self.font_scale - 0.10))
        menu.add_command(label="🔎--  字号 -- (-0.25)",
                         command=lambda: self.set_font_scale(self.font_scale - 0.25))
        menu.add_separator()
        menu.add_command(label="↺  重置为默认 (1.00×)",
                         command=lambda: self.set_font_scale(1.0))
        try:
            menu.tk_popup(e.x_root, e.y_root)
        finally:
            menu.grab_release()

    def set_font_scale(self, scale):
        scale = max(0.4, min(3.0, float(scale)))
        scale = round(scale, 2)
        if abs(scale - self.font_scale) < 0.005:
            return
        self.font_scale = scale
        if self._last_data is not None:
            self._do_render(self._last_data)

    def set_mode(self, mode):
        if mode not in self.MODES:
            return
        self.mode = mode
        if self._last_data is not None:
            self._do_render(self._last_data)

    def render(self, sessions_info):


        data = []
        for info in sessions_info:
            comps = [m for m in info['ok_list'] if m.ok]
            if comps:
                data.append({
                    'name': info['name'],
                    'comps': comps,
                    'confirmed': info.get('confirmed', False),
                    'max_pair': info.get('max_pair', None),
                })
        self._last_data = data
        self._do_render(data)

    def _do_render(self, data):
        self.fig.clear()
        ax = self.fig.add_subplot(111)
        self.ax = ax
        fs = self.font_scale
        ax.set_facecolor(_M_SCI_BG)

        if not data:
            ax.text(0.5, 0.5,
                    '跨会话汇总将在画线并确认后显示\n'
                    '顶部按钮可切换: 柱形 / 箱线 / 散点 / 折线',
                    ha='center', va='center',
                    transform=ax.transAxes,
                    fontsize=12 * fs, color=_M_TG,
                    fontproperties=m_zhfp(12 * fs),
                    linespacing=1.6)
            ax.axis('off')
            self.canvas.draw_idle()
            return

        dispatch = {
            'bar':     self._render_bar,
            'box':     self._render_box,
            'scatter': self._render_scatter,
            'line':    self._render_line,
        }
        dispatch.get(self.mode, self._render_bar)(ax, data, fs)
        self._polish_axes(ax, fs)
        self._apply_title(ax, data, fs)

        try:
            self.fig.tight_layout(pad=1.4)
        except Exception:
            pass
        self.canvas.draw_idle()


    def _render_bar(self, ax, data, fs):
        n = len(data)
        xs = np.arange(n)
        vals = []
        labels = []
        try:
            base_cm = plt.get_cmap('tab20')
            palette = [base_cm(i / max(n - 1, 1) * 0.95) for i in range(n)]
        except Exception:
            _PALETTE_FALLBACK = ['#2E5BBA', '#A0522D', '#1F8A70', '#B8860B',
                                 '#8B5A8E', '#C0392B', '#16A085', '#D35400',
                                 '#7E57C2', '#00838F', '#5D4037', '#558B2F']
            palette = [_PALETTE_FALLBACK[i % len(_PALETTE_FALLBACK)]
                       for i in range(n)]
        colors = []
        edge_colors = []
        for idx, d in enumerate(data):
            base_col = palette[idx]
            mp = d['max_pair']
            if d['confirmed'] and mp is not None:
                vals.append(float(mp[2]))
                ia = mp[0]; ib = mp[1]
                la = d['comps'][ia].label if 0 <= ia < len(d['comps']) else '—'
                lb = d['comps'][ib].label if 0 <= ib < len(d['comps']) else '—'
                labels.append(f"{la}↔{lb}")
                colors.append(base_col)
                edge_colors.append('#B91C1C')
            else:
                mxm = max(d['comps'], key=lambda m: m.tilt)
                vals.append(float(mxm.tilt))
                labels.append(mxm.label)
                colors.append(base_col if d['confirmed'] else '#D0D0D0')
                edge_colors.append('white')

        bars = ax.bar(xs, vals, color=colors, alpha=0.92,
                      edgecolor='white', linewidth=1.4, width=0.62,
                      zorder=3)
        for bar, ec, d in zip(bars, edge_colors, data):
            if d['confirmed'] and d['max_pair'] is not None:
                bar.set_edgecolor(ec)
                bar.set_linewidth(1.8)

        top = max(vals) if vals else 1.0
        for i, (v, lb) in enumerate(zip(vals, labels)):
            ax.text(i, v + top * 0.025, f'{v:.1f}°',
                    ha='center', va='bottom',
                    fontsize=10 * fs, color='#111', fontweight='bold',
                    fontproperties=m_enfp(10 * fs, 'bold'))
            ax.text(i, -top * 0.045, lb,
                    ha='center', va='top',
                    fontsize=8 * fs, color=_M_SCI_AX_LIGHT,
                    fontproperties=m_enfp(8 * fs))

        conf_vals = [float(d['max_pair'][2]) for d in data
                     if d['confirmed'] and d['max_pair'] is not None]
        if len(conf_vals) > 1:
            mv = float(np.mean(conf_vals))
            ax.axhline(mv, color='#4A6FA5', lw=1.0,
                       ls='--', alpha=0.8, zorder=2,
                       label=f'Mean Max Cobb = {mv:.1f}°')
            leg = ax.legend(loc='upper right', fontsize=8.5 * fs,
                            facecolor='white', edgecolor='#CCCCCC',
                            prop=m_enfp(8.5 * fs))
            leg.set_draggable(True)

        ax.set_xticks(xs)
        ax.set_xticklabels([self._short(d['name']) for d in data],
                           rotation=0 if len(data) <= 6 else 25,
                           ha='right' if len(data) > 6 else 'center',
                           fontproperties=m_zhfp(9 * fs))
        ax.set_xlim(-0.6, len(data) - 0.4)
        ax.set_ylabel('Max Cobb (°)', fontsize=10 * fs,
                      fontproperties=m_enfp(10 * fs),
                      color=_M_SCI_AX, labelpad=6)

    def _render_box(self, ax, data, fs):
        n = len(data)
        xs = list(range(1, n + 1))
        try:
            base_cm = plt.get_cmap('tab20')
            palette = [base_cm(i / max(n - 1, 1) * 0.95) for i in range(n)]
        except Exception:
            _PALETTE_FALLBACK = ['#2E5BBA', '#A0522D', '#1F8A70', '#B8860B',
                                 '#8B5A8E', '#C0392B', '#16A085', '#D35400',
                                 '#7E57C2', '#00838F', '#5D4037', '#558B2F']
            palette = [_PALETTE_FALLBACK[i % len(_PALETTE_FALLBACK)]
                       for i in range(n)]
        box_data = [[m.tilt for m in d['comps']] for d in data]
        bp = ax.boxplot(box_data, positions=xs, widths=0.55,
                        patch_artist=True, showmeans=True,
                        medianprops=dict(color='#111', lw=1.6),
                        meanprops=dict(marker='D',
                                       markerfacecolor='#F59E0B',
                                       markeredgecolor='#B45309',
                                       markersize=6),
                        whiskerprops=dict(color='#888', lw=1.0),
                        capprops=dict(color='#888', lw=1.0),
                        flierprops=dict(marker='o',
                                        markerfacecolor='#EF4444',
                                        markersize=5, alpha=0.65,
                                        markeredgecolor='none'))
        for idx, (patch, d) in enumerate(zip(bp['boxes'], data)):
            patch.set_facecolor(palette[idx])
            patch.set_alpha(0.55 if d['confirmed'] else 0.25)
            patch.set_edgecolor('#1E3A8A')
            patch.set_linewidth(1.2)

        for i, d in enumerate(data):
            if d['confirmed'] and d['max_pair'] is not None:
                mc = float(d['max_pair'][2])
                ax.scatter([xs[i]], [mc], marker='*', s=200,
                           c='#FFD700', edgecolors='#B91C1C',
                           linewidths=1.5, zorder=10)
                ax.text(xs[i], mc, f'  ★{mc:.1f}°',
                        ha='left', va='center',
                        fontsize=9 * fs, color='#991B1B',
                        fontweight='bold',
                        fontproperties=m_zhfp(9 * fs, 'bold'))

        ax.set_xticks(xs)
        ax.set_xticklabels([self._short(d['name']) for d in data],
                           rotation=0 if n <= 6 else 25,
                           ha='right' if n > 6 else 'center',
                           fontproperties=m_zhfp(9 * fs))
        ax.set_ylabel('Line tilt (°)', fontsize=10 * fs,
                      fontproperties=m_enfp(10 * fs),
                      color=_M_SCI_AX, labelpad=6)

    def _render_scatter(self, ax, data, fs):
        n = len(data)
        rng = np.random.default_rng(42)
        for i, d in enumerate(data):
            xs = rng.uniform(i - 0.18, i + 0.18, size=len(d['comps']))
            tilts = [m.tilt for m in d['comps']]
            mp = d['max_pair']
            normal_idx = []
            star_idx = []
            if d['confirmed'] and mp is not None:
                max_set = {mp[0], mp[1]}
                for j in range(len(d['comps'])):
                    if j in max_set:
                        star_idx.append(j)
                    else:
                        normal_idx.append(j)
            else:
                normal_idx = list(range(len(d['comps'])))

            if normal_idx:
                ax.scatter([xs[j] for j in normal_idx],
                           [tilts[j] for j in normal_idx],
                           c=_M_LINE_COLOR, s=42 * fs,
                           alpha=0.75, edgecolors='white',
                           linewidths=0.8, zorder=5)
            if star_idx:
                for j in star_idx:
                    role = 'A' if j == mp[0] else 'B'
                    col = _M_HL_A if role == 'A' else _M_HL_B
                    ax.scatter([xs[j]], [tilts[j]],
                               marker='*', s=260 * fs,
                               c=col, edgecolors='white',
                               linewidths=1.6, zorder=10)

            if len(tilts) > 1:
                mv = float(np.mean(tilts))
                ax.plot([i - 0.25, i + 0.25], [mv, mv],
                        color='#374151', lw=1.4, alpha=0.6, zorder=3)

        ax.set_xticks(range(n))
        ax.set_xticklabels([self._short(d['name']) for d in data],
                           rotation=0 if n <= 6 else 25,
                           ha='right' if n > 6 else 'center',
                           fontproperties=m_zhfp(9 * fs))
        ax.set_xlim(-0.6, n - 0.4)
        ax.set_ylabel('Line tilt (°)', fontsize=10 * fs,
                      fontproperties=m_enfp(10 * fs),
                      color=_M_SCI_AX, labelpad=6)

        leg_items = [
            mlines.Line2D([], [], marker='o', color='w',
                          markerfacecolor=_M_LINE_COLOR, markersize=8,
                          markeredgecolor='white',
                          label='普通线 Line'),
            mlines.Line2D([], [], marker='*', color='w',
                          markerfacecolor=_M_HL_A, markersize=13,
                          markeredgecolor='white',
                          label='Max pair  A'),
            mlines.Line2D([], [], marker='*', color='w',
                          markerfacecolor=_M_HL_B, markersize=13,
                          markeredgecolor='white',
                          label='Max pair  B'),
        ]
        leg = ax.legend(handles=leg_items, loc='upper right',
                        fontsize=9 * fs,
                        facecolor='white', edgecolor='#CCCCCC',
                        prop=m_zhfp(9 * fs))
        leg.set_draggable(True)

    def _render_line(self, ax, data, fs):
        n = len(data)
        xs = np.arange(n)
        vals = []
        for d in data:
            if d['confirmed'] and d['max_pair'] is not None:
                vals.append(float(d['max_pair'][2]))
            else:
                vals.append(float('nan'))

        ax.plot(xs, vals, color=_M_HL_A, lw=2.4, marker='o',
                markersize=9, markerfacecolor='white',
                markeredgecolor=_M_HL_A, markeredgewidth=2.0,
                zorder=5, label='Max Cobb per session')

        for i, v in enumerate(vals):
            if not math.isnan(v):
                ax.annotate(f'{v:.1f}°',
                            xy=(xs[i], v), xytext=(0, 10),
                            textcoords='offset points',
                            ha='center', va='bottom',
                            fontsize=10 * fs, color='#991B1B',
                            fontweight='bold',
                            fontproperties=m_enfp(10 * fs, 'bold'))

        valid = [v for v in vals if not math.isnan(v)]
        if len(valid) > 1:
            mv = float(np.mean(valid))
            ax.axhline(mv, color='#4A6FA5', lw=1.0,
                       ls='--', alpha=0.8, zorder=2,
                       label=f'Mean = {mv:.1f}°')

        if valid:
            vmax = max(valid)
            if vmax > 25:
                ax.axhspan(25, max(vmax * 1.1, 30),
                           facecolor='#FEE2E2', alpha=0.28, zorder=0)

        leg = ax.legend(loc='upper right', fontsize=9 * fs,
                        facecolor='white', edgecolor='#CCCCCC',
                        prop=m_enfp(9 * fs))
        leg.set_draggable(True)

        ax.set_xticks(xs)
        ax.set_xticklabels([self._short(d['name']) for d in data],
                           rotation=0 if n <= 6 else 25,
                           ha='right' if n > 6 else 'center',
                           fontproperties=m_zhfp(9 * fs))
        ax.set_xlim(-0.4, n - 0.6)
        ax.set_ylabel('Max Cobb (°)', fontsize=10 * fs,
                      fontproperties=m_enfp(10 * fs),
                      color=_M_SCI_AX, labelpad=6)


    def _polish_axes(self, ax, fs):
        ax.tick_params(axis='both', labelsize=9 * fs, colors=_M_SCI_AX)
        for sp in ['top', 'right']:
            ax.spines[sp].set_visible(False)
        for sp in ['left', 'bottom']:
            ax.spines[sp].set_color('#BBBBBB')
            ax.spines[sp].set_linewidth(0.8)
        ax.grid(True, axis='y', alpha=0.35, ls='-',
                color=_M_SCI_GRID, lw=0.5, zorder=0)

    def _apply_title(self, ax, data, fs):
        n = len(data)
        n_conf = sum(1 for d in data
                     if d['confirmed'] and d['max_pair'] is not None)
        all_vals = [m.tilt for d in data for m in d['comps']]
        conf_vals = [float(d['max_pair'][2]) for d in data
                     if d['confirmed'] and d['max_pair'] is not None]

        mode_label = self.MODE_LABELS.get(self.mode, '')
        mode_sub = self.MODE_SUBS.get(self.mode, '')

        parts = [f'跨会话汇总 · {mode_label} · {mode_sub}',
                 f'Sessions: {n} (已确认 {n_conf})']
        if all_vals:
            parts.append(f'Max tilt: {max(all_vals):.2f}°')
        if conf_vals:
            parts.append(f'★ Max Cobb: {max(conf_vals):.2f}°')
        title = '  ·  '.join(parts)
        ax.set_title(title, fontsize=11.5 * fs, fontweight='bold',
                     color=_M_SCI_AX, pad=10,
                     fontproperties=m_zhfp(11.5 * fs, 'bold'))

    def _short(self, name, maxlen=14):
        base = os.path.splitext(name)[0] if '.' in name else name
        if len(base) <= maxlen:
            return base
        return base[:maxlen - 1] + '…'

    def export(self, path, dpi=600):
        path = os.path.abspath(str(path))
        d = os.path.dirname(path)
        if d and not os.path.isdir(d):
            os.makedirs(d, exist_ok=True)
        try:
            self.canvas.draw()
        except Exception:
            pass
        last_err = None
        for kw in (
            dict(dpi=dpi, bbox_inches='tight',
                 facecolor='white', edgecolor='none'),
            dict(dpi=dpi, facecolor='white', edgecolor='none'),
            dict(dpi=max(int(dpi // 2), 150),
                 facecolor='white', edgecolor='none'),
        ):
            try:
                self.fig.savefig(path, **kw)
                if os.path.isfile(path) and os.path.getsize(path) > 0:
                    return True
            except Exception as ex:
                last_err = ex
                continue
        if last_err is not None:
            raise last_err
        raise RuntimeError(f"savefig 失败,文件未生成: {path}")


class M_SessionCard:


    def __init__(self, parent, app, session_id,
                 on_focus=None, on_close=None, on_updated=None):
        self.app = app
        self.sid = session_id
        self.res = ManualResult()
        self.on_focus = on_focus
        self.on_close = on_close
        self.on_updated = on_updated
        self.is_active = False


        self.zoom = 1.0
        self.off = [0.0, 0.0]
        self._pan_last = None
        self._tkimg = None


        self.brightness = 0
        self.contrast = 1.0


        self.hist = []
        self.redo_stack = []


        self.canvas_minimized = False
        self.analysis_minimized = False
        self.session_minimized = False
        self._destroyed = False

        self._build_ui(parent)
        self.drawer = M_DrawingController(self)
        self.renderer = M_CanvasRenderer(self)
        self._bind_canvas_events()

    # ----- UI -----
