#    2. 首次启动 (数据库为空) 直接进入 [初始化管理员] 流程
#    3. AdminApp: 管理员模式的第三板块, 包含:
#       - 用户列表 (启用/禁用/删除/重置密码)
#       - 登录日志查看
#       - 操作审计日志查看
#       - 修改自己的密码
# =============================================================================
import tkinter as tk
from tkinter import ttk, messagebox, simpledialog


# ----------------------------------------------------------------------------
#  通用样式
# ----------------------------------------------------------------------------
_AUTH_BG_DARK   = '#0F172A'
_AUTH_BG_PANEL  = '#1E293B'
_AUTH_BG_INPUT  = '#FFFFFF'
_AUTH_FG_LIGHT  = '#E2E8F0'
_AUTH_FG_MUTED  = '#94A3B8'
_AUTH_ACCENT    = '#3B82F6'
_AUTH_ACCENT_H  = '#2563EB'
_AUTH_ADMIN     = '#DC2626'
_AUTH_ADMIN_H   = '#B91C1C'
_AUTH_OK        = '#10B981'
_AUTH_OK_H      = '#059669'
_AUTH_WARN      = '#F59E0B'


def _make_round_button(parent, text, command, bg, bg_h, fg='white',
                       width=200, height=38, font_size=10):
    """绘制圆角按钮 (Canvas 实现)"""
    cv = tk.Canvas(parent, width=width, height=height,
                   bg=parent['bg'], highlightthickness=0,
                   bd=0, cursor='hand2')
    cv._hover = False
    cv._enabled = True
    cv._bg = bg
    cv._bg_h = bg_h
    cv._fg = fg
    cv._text = text

    def _draw():
        cv.delete('all')
        if not cv._enabled:
            fill = '#475569'; tc = '#94A3B8'
        elif cv._hover:
            fill = cv._bg_h; tc = cv._fg
        else:
            fill = cv._bg; tc = cv._fg
        r = 8
        cv.create_arc(0, 0, 2*r, 2*r, start=90, extent=90,
                      fill=fill, outline=fill)
        cv.create_arc(width-2*r, 0, width, 2*r, start=0, extent=90,
                      fill=fill, outline=fill)
        cv.create_arc(0, height-2*r, 2*r, height, start=180, extent=90,
                      fill=fill, outline=fill)
        cv.create_arc(width-2*r, height-2*r, width, height,
                      start=270, extent=90, fill=fill, outline=fill)
        cv.create_rectangle(r, 0, width-r, height, fill=fill, outline=fill)
        cv.create_rectangle(0, r, width, height-r, fill=fill, outline=fill)
        cv.create_text(width/2, height/2, text=cv._text,
                       fill=tc, font=('SimSun', font_size, 'bold'))

    def _enter(_e=None):
        if cv._enabled:
            cv._hover = True; _draw()
    def _leave(_e=None):
        cv._hover = False; _draw()
    def _click(_e=None):
        if cv._enabled:
            command()

    cv.bind('<Enter>', _enter)
    cv.bind('<Leave>', _leave)
    cv.bind('<Button-1>', _click)
    cv._redraw = _draw
    _draw()
    return cv


def _make_entry(parent, show=None, font_size=11):
    e = tk.Entry(parent, font=('SimSun', font_size),
                 bg=_AUTH_BG_INPUT, fg='#0F172A',
                 insertbackground='#0F172A',
                 relief='flat', bd=0,
                 highlightthickness=1,
                 highlightcolor=_AUTH_ACCENT,
                 highlightbackground='#CBD5E1')
    if show:
        e.config(show=show)
    return e


# ============================================================================
#  LicenseDialog  -  激活密钥对话框 (新版主登录方式, 替代账号登录)
# ============================================================================
class LicenseDialog:
    """激活密钥对话框。
    用法:
        ld = LicenseDialog()
        ld.run()  # 阻塞
        if ld.user:
            launcher = Launcher(root, current_user=ld.user)
        else:
            sys.exit(0)
    返回的 ld.user 是一个 dict, 兼容原 Launcher 的 current_user 格式:
        {
            'username': identity 或 'license_user',
            'is_admin': bool,
            'role':     'U' or 'A',
            'identity': str,
            'expiry_ts': int (Unix timestamp),
            'expiry_str': str (YYYYMMDD),
        }
    """

    def __init__(self):
        self.user = None
        self._win = None

    # ----------------------------------------------------------------
    #  入口
    # ----------------------------------------------------------------
    def run(self):
        # 1) 检查本地激活态 (免密钥启动)
        try:
            act = load_activation()
            if act:
                self.user = self._build_user_from_payload(act)
                try:
                    log_audit(self.user.get('username', ''),
                              'auto_activate',
                              f"role={act.get('role')}, "
                              f"expiry={act.get('expiry_str', '')}")
                except Exception: pass
                return
        except Exception: pass

        # 2) 弹出密钥输入窗
        self._build_window()
        self._win.mainloop()

    def _build_user_from_payload(self, payload):
        ident = payload.get('identity', '') or ''
        role = payload.get('role', 'U')
        return {
            'username': ident if ident else (
                'admin_user' if role == 'A' else 'license_user'),
            'is_admin': role == 'A',
            'role':     role,
            'identity': ident,
            'expiry_ts':  payload.get('expiry_ts'),
            'expiry_str': payload.get('expiry_str', ''),
        }

    # ----------------------------------------------------------------
    #  构建窗口
    # ----------------------------------------------------------------
    def _build_window(self):
        self._win = tk.Tk()
        self._win.title('Spine COBB Analyzer · 激活')
        try:
            self._win.geometry('540x600')
            self._win.minsize(480, 540)
            self._win.resizable(True, True)
        except Exception: pass
        self._win.configure(bg=_AUTH_BG_DARK)
        self._win.protocol('WM_DELETE_WINDOW', self._on_close)

        # 居中
        try:
            self._win.update_idletasks()
            sw = self._win.winfo_screenwidth()
            sh = self._win.winfo_screenheight()
            x = (sw - 540) // 2
            y = (sh - 600) // 2
            self._win.geometry(f'540x600+{x}+{y}')
        except Exception: pass

        # 顶部 Logo 区
        top = tk.Frame(self._win, bg=_AUTH_BG_DARK, height=140)
        top.pack(side=tk.TOP, fill=tk.X)
        top.pack_propagate(False)
        tk.Label(top, text='🦴', bg=_AUTH_BG_DARK, fg='white',
                 font=('Segoe UI Emoji', 48)).pack(pady=(20, 0))
        tk.Label(top, text='Spine COBB Analyzer',
                 bg=_AUTH_BG_DARK, fg='white',
                 font=('Times New Roman', 14, 'bold')).pack()
        tk.Label(top, text='脊柱 Cobb 角智能分析系统',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 9)).pack()

        # 主体
        body = tk.Frame(self._win, bg=_AUTH_BG_DARK)
        body.pack(side=tk.TOP, fill=tk.BOTH, expand=True,
                  padx=40, pady=10)

        # 作者微信卡片
        wx_card = tk.Frame(body, bg='#FEF3C7',
                           highlightbackground='#F59E0B',
                           highlightthickness=2)
        wx_card.pack(fill=tk.X, pady=(4, 16))
        tk.Label(wx_card,
                 text='📞  请联系作者获取激活密钥',
                 bg='#FEF3C7', fg='#92400E',
                 font=('SimSun', 10, 'bold')).pack(anchor='w',
                                                     padx=10, pady=(8, 0))
        tk.Label(wx_card,
                 text=f'微信号:  {AUTHOR_WECHAT}',
                 bg='#FEF3C7', fg='#0F172A',
                 font=('Times New Roman', 13, 'bold')).pack(anchor='w',
                                                              padx=10)
        tk.Label(wx_card,
                 text='密钥有效期内可在本机免密钥反复使用, 到期后请索取新密钥',
                 bg='#FEF3C7', fg='#78350F',
                 font=('SimSun', 8)).pack(anchor='w',
                                            padx=10, pady=(0, 8))

        # 标题
        tk.Label(body, text='🔑  激活密钥',
                 bg=_AUTH_BG_DARK, fg='white',
                 font=('SimSun', 13, 'bold')).pack(anchor='w', pady=(6, 4))
        tk.Label(body,
                 text='请粘贴作者发给您的激活密钥到下方输入框',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 9)).pack(anchor='w', pady=(0, 8))

        # 输入框
        self._key_e = _make_entry(body, font_size=11)
        self._key_e.pack(fill=tk.X, ipady=8)
        tk.Label(body,
                 text='格式示例:  U.zhangsan.20260626.A7F2B8D4',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('Times New Roman', 9, 'italic')).pack(
            anchor='w', pady=(4, 0))

        # 错误提示
        self._key_msg = tk.Label(body, text='',
                                  bg=_AUTH_BG_DARK, fg=_AUTH_ADMIN,
                                  font=('SimSun', 9))
        self._key_msg.pack(anchor='w', pady=(8, 0))

        # 激活按钮
        btn = _make_round_button(body, '🚀 激 活 进 入',
                                  self._on_activate,
                                  _AUTH_ACCENT, _AUTH_ACCENT_H,
                                  width=420, height=44, font_size=12)
        btn.pack(pady=(16, 0))

        # 提示
        tip = tk.Label(body,
                       text='💡 激活成功后, 在本机的密钥有效期内打开软件\n'
                            '   将直接进入, 不需要再输入任何密钥',
                       bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                       font=('SimSun', 9), justify=tk.LEFT)
        tip.pack(anchor='w', pady=(16, 0))

        # 底部状态栏
        bot = tk.Frame(self._win, bg=_AUTH_BG_DARK, height=30)
        bot.pack(side=tk.BOTTOM, fill=tk.X)
        bot.pack_propagate(False)
        tk.Label(bot,
                 text='© 2026 Spine COBB Analyzer · 激活密钥由 HMAC-SHA256 签名保护',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 8)).pack(pady=6)

        # 焦点 + 回车提交
        try: self._key_e.focus_set()
        except Exception: pass
        self._key_e.bind('<Return>', lambda e: self._on_activate())

    def _on_activate(self):
        key = self._key_e.get().strip()
        if not key:
            self._key_msg.config(text='✗ 请输入激活密钥')
            return
        ok, info = verify_license_key(key)
        if not ok:
            self._key_msg.config(text='✗ ' + str(info))
            return
        # 验证通过 -> 保存激活态 (用于免密钥启动)
        save_activation(info, original_key=key)
        try:
            log_audit(info.get('identity') or 'license_user',
                      'activate',
                      f"role={info.get('role')}, "
                      f"expiry={info.get('expiry_str')}")
        except Exception: pass
        self.user = self._build_user_from_payload(info)
        self._close_and_continue()

    def _close_and_continue(self):
        try: self._win.quit()
        except Exception: pass
        try: self._win.destroy()
        except Exception: pass

    def _on_close(self):
        self.user = None
        self._close_and_continue()



class LoginDialog:
    """启动时的登录对话框。
    用法:
        ld = LoginDialog()
        ld.run()  # 阻塞等待
        if ld.user:
            launcher = Launcher(root, current_user=ld.user)
            ...
        else:
            sys.exit(0)
    """

    def __init__(self):
        self.user = None      # 登录成功后保存用户 dict
        self._win = None
        self._notebook = None
        self._first_run = not has_any_user()

    # ----------------------------------------------------------------
    #  入口
    # ----------------------------------------------------------------
    def run(self):
        # 1) 先尝试 60 天自动登录
        try:
            auto = load_session()
            if auto:
                self.user = auto
                # 静默更新最后登录时间
                update_last_login(auto['username'])
                log_login_attempt(
                    auto['username'], True, note='60天自动登录')
                return
        except Exception:
            pass

        # 2) 弹出登录窗口
        self._build_window()
        self._win.mainloop()

    # ----------------------------------------------------------------
    #  构建窗口
    # ----------------------------------------------------------------
    def _build_window(self):
        self._win = tk.Tk()
        self._win.title('Spine COBB Analyzer · 登录')
        try:
            self._win.iconbitmap(default='')
        except Exception: pass
        try:
            # 允许用户调整窗口大小, 设置最小尺寸防止挤压
            self._win.geometry('520x680')
            self._win.minsize(480, 600)
            self._win.resizable(True, True)
        except Exception: pass
        self._win.configure(bg=_AUTH_BG_DARK)
        self._win.protocol('WM_DELETE_WINDOW', self._on_close)

        # 居中
        try:
            self._win.update_idletasks()
            sw = self._win.winfo_screenwidth()
            sh = self._win.winfo_screenheight()
            x = (sw - 520) // 2
            y = (sh - 680) // 2
            self._win.geometry(f'520x680+{x}+{y}')
        except Exception: pass

        # 顶部 Logo 区
        top = tk.Frame(self._win, bg=_AUTH_BG_DARK, height=140)
        top.pack(side=tk.TOP, fill=tk.X)
        top.pack_propagate(False)
        tk.Label(top, text='🦴', bg=_AUTH_BG_DARK, fg='white',
                 font=('Segoe UI Emoji', 48)).pack(pady=(20, 0))
        tk.Label(top, text='Spine COBB Analyzer',
                 bg=_AUTH_BG_DARK, fg='white',
                 font=('Times New Roman', 14, 'bold')).pack()
        tk.Label(top, text='脊柱 Cobb 角智能分析系统',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 9)).pack()

        # 主体
        body = tk.Frame(self._win, bg=_AUTH_BG_DARK)
        body.pack(side=tk.TOP, fill=tk.BOTH, expand=True,
                  padx=40, pady=10)

        if self._first_run:
            self._build_first_run(body)
        else:
            self._build_normal(body)

        # 底部状态栏
        bot = tk.Frame(self._win, bg=_AUTH_BG_DARK, height=30)
        bot.pack(side=tk.BOTTOM, fill=tk.X)
        bot.pack_propagate(False)
        tk.Label(bot,
                 text='© 2026 Spine COBB Analyzer · 数据本地加密存储',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 8)).pack(pady=6)

    # ----------------------------------------------------------------
    #  首次运行: Tab 切换 [我是普通使用者] / [我是软件管理员]
    # ----------------------------------------------------------------
    def _build_first_run(self, parent):
        # 顶部说明
        tip = tk.Label(parent,
                       text='欢迎使用！请选择您的身份',
                       bg=_AUTH_BG_DARK, fg=_AUTH_FG_LIGHT,
                       font=('SimSun', 10))
        tip.pack(pady=(2, 8))

        # ---- Tab 切换条 ----
        tab_bar = tk.Frame(parent, bg=_AUTH_BG_DARK, height=36)
        tab_bar.pack(fill=tk.X)
        tab_bar.pack_propagate(False)

        self._fr_tabs = {}

        def _mk(name, label):
            f = tk.Frame(tab_bar, bg=_AUTH_BG_DARK, cursor='hand2')
            lbl = tk.Label(f, text=label, bg=_AUTH_BG_DARK,
                           fg=_AUTH_FG_MUTED,
                           font=('SimSun', 11, 'bold'),
                           padx=14, pady=6)
            lbl.pack()
            ul = tk.Frame(f, bg=_AUTH_BG_DARK, height=2)
            ul.pack(fill=tk.X)
            f._lbl = lbl; f._ul = ul
            f.bind('<Button-1>', lambda e, n=name: self._fr_switch(n))
            lbl.bind('<Button-1>', lambda e, n=name: self._fr_switch(n))
            return f

        self._fr_tabs['user']  = _mk('user',  '👤 我是普通使用者')
        self._fr_tabs['admin'] = _mk('admin', '🛡️ 我是软件管理员')
        self._fr_tabs['user'].pack(side=tk.LEFT, padx=(0, 8))
        self._fr_tabs['admin'].pack(side=tk.LEFT)

        tk.Frame(parent, bg='#334155', height=1).pack(fill=tk.X, pady=(2, 6))

        # ---- 主面板容器 ----
        self._fr_panels = tk.Frame(parent, bg=_AUTH_BG_DARK)
        self._fr_panels.pack(fill=tk.BOTH, expand=True)

        self._fr_panel_user = tk.Frame(self._fr_panels, bg=_AUTH_BG_DARK)
        self._build_first_run_user_panel(self._fr_panel_user)

        self._fr_panel_admin = tk.Frame(self._fr_panels, bg=_AUTH_BG_DARK)
        self._build_first_run_admin_panel(self._fr_panel_admin)

        self._fr_switch('user')  # 默认显示"普通使用者"

    def _fr_switch(self, name):
        for n, f in self._fr_tabs.items():
            if n == name:
                f._lbl.config(fg='white')
                f._ul.config(bg=_AUTH_ACCENT)
            else:
                f._lbl.config(fg=_AUTH_FG_MUTED)
                f._ul.config(bg=_AUTH_BG_DARK)
        try: self._fr_panel_user.pack_forget()
        except Exception: pass
        try: self._fr_panel_admin.pack_forget()
        except Exception: pass
        if name == 'user':
            self._fr_panel_user.pack(fill=tk.BOTH, expand=True)
            try: self._fru_user.focus_set()
            except Exception: pass
        else:
            self._fr_panel_admin.pack(fill=tk.BOTH, expand=True)
            try: self._fr_user.focus_set()
            except Exception: pass

    # ---- 普通使用者注册 panel ----
    def _build_first_run_user_panel(self, parent):
        # ===== 作者微信号提示卡 (黄色高亮) =====
        wx_card = tk.Frame(parent, bg='#FEF3C7',
                           highlightbackground='#F59E0B',
                           highlightthickness=2)
        wx_card.pack(fill=tk.X, pady=(4, 8))
        tk.Label(wx_card,
                 text='📞  注册前请先添加作者微信确认身份',
                 bg='#FEF3C7', fg='#92400E',
                 font=('SimSun', 10, 'bold')).pack(anchor='w',
                                                     padx=10, pady=(6, 0))
        tk.Label(wx_card,
                 text=f'微信号:  {AUTHOR_WECHAT}',
                 bg='#FEF3C7', fg='#0F172A',
                 font=('Times New Roman', 12, 'bold')).pack(anchor='w',
                                                              padx=10)
        tk.Label(wx_card,
                 text='(若需要禁用账号、找回密码、查看使用日志, '
                      '请联系作者协助)',
                 bg='#FEF3C7', fg='#78350F',
                 font=('SimSun', 8)).pack(anchor='w',
                                            padx=10, pady=(0, 6))

        tk.Label(parent, text='👤  普通用户注册',
                 bg=_AUTH_BG_DARK, fg=_AUTH_OK,
                 font=('SimSun', 12, 'bold')).pack(pady=(4, 2))
        tk.Label(parent,
                 text='直接填写以下信息即可开始使用 (无需任何口令)',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 9)).pack(pady=(0, 8))

        def _row(lbl):
            tk.Label(parent, text=lbl, bg=_AUTH_BG_DARK,
                     fg=_AUTH_FG_LIGHT,
                     font=('SimSun', 10)).pack(anchor='w', pady=(6, 2))
            e = _make_entry(parent)
            e.pack(fill=tk.X, ipady=5)
            return e

        self._fru_user  = _row('用户名 (必填)')
        self._fru_full  = _row('真实姓名 (可选)')
        self._fru_cont  = _row('联系方式 邮箱/微信/QQ (可选)')
        self._fru_pass1 = _row('密码 (至少 6 位, 必填)')
        self._fru_pass1.config(show='●')
        self._fru_pass2 = _row('再次输入密码 (必填)')
        self._fru_pass2.config(show='●')

        # ---- 邀请码字段 ----
        if INVITE_REQUIRED:
            tk.Frame(parent, bg='#334155', height=1).pack(
                fill=tk.X, pady=(8, 4))
            tk.Label(parent,
                     text='🎫 邀请码 (必填 - 由作者生成后发给您)',
                     bg=_AUTH_BG_DARK, fg=_AUTH_WARN,
                     font=('SimSun', 10, 'bold')).pack(
                anchor='w', pady=(2, 2))
            self._fru_invite = _make_entry(parent, font_size=10)
            self._fru_invite.pack(fill=tk.X, ipady=5)
            tk.Label(parent,
                     text='格式示例:  zhangsan.20260626.A7F2B8D4',
                     bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                     font=('Times New Roman', 9, 'italic')).pack(
                anchor='w', pady=(2, 0))
        else:
            self._fru_invite = None

        self._fru_msg = tk.Label(parent, text='',
                                 bg=_AUTH_BG_DARK, fg=_AUTH_ADMIN,
                                 font=('SimSun', 9))
        self._fru_msg.pack(pady=(6, 0))

        btn = _make_round_button(parent, '✓ 注 册 并 登 录',
                                  self._on_first_run_user_reg,
                                  _AUTH_OK, _AUTH_OK_H,
                                  width=380, height=42, font_size=11)
        btn.pack(pady=(12, 0))
        if self._fru_invite is not None:
            self._fru_invite.bind('<Return>',
                                   lambda e: self._on_first_run_user_reg())
        else:
            self._fru_pass2.bind('<Return>',
                                  lambda e: self._on_first_run_user_reg())

    def _on_first_run_user_reg(self):
        u  = self._fru_user.get().strip()
        f  = self._fru_full.get().strip()
        c  = self._fru_cont.get().strip()
        p1 = self._fru_pass1.get()
        p2 = self._fru_pass2.get()
        ic = (self._fru_invite.get().strip()
              if self._fru_invite is not None else '')
        if not u:
            self._fru_msg.config(text='✗ 用户名不能为空'); return
        if len(p1) < 6:
            self._fru_msg.config(text='✗ 密码至少 6 位'); return
        if p1 != p2:
            self._fru_msg.config(text='✗ 两次密码不一致'); return
        ok, msg = register_normal_user(u, p1,
                                        full_name=f, contact=c,
                                        invite_code=ic)
        if not ok:
            self._fru_msg.config(text='✗ ' + msg); return
        ok, info = authenticate(u, p1)
        if not ok:
            self._fru_msg.config(text='✗ 注册成功但登录失败: ' + str(info))
            return
        self.user = info
        save_session(u)
        self._close_and_continue()

    # ---- 管理员创建 panel ----
    def _build_first_run_admin_panel(self, parent):
        tk.Label(parent, text='🛡️  创建系统管理员',
                 bg=_AUTH_BG_DARK, fg=_AUTH_WARN,
                 font=('SimSun', 12, 'bold')).pack(pady=(8, 2))
        tk.Label(parent,
                 text='管理员拥有最高权限 (需要管理员注册口令)',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 9)).pack(pady=(0, 10))

        form = tk.Frame(parent, bg=_AUTH_BG_DARK)
        form.pack(fill=tk.X)

        def _row(lbl):
            tk.Label(form, text=lbl, bg=_AUTH_BG_DARK,
                     fg=_AUTH_FG_LIGHT,
                     font=('SimSun', 10)).pack(anchor='w', pady=(6, 2))
            e = _make_entry(form)
            e.pack(fill=tk.X, ipady=6)
            return e

        self._fr_user  = _row('管理员用户名')
        self._fr_pass1 = _row('密码 (至少 6 位)')
        self._fr_pass1.config(show='●')
        self._fr_pass2 = _row('再次输入密码')
        self._fr_pass2.config(show='●')
        self._fr_token = _row('管理员注册口令 (从软件作者处获取)')
        self._fr_token.config(show='●')

        # 默认填入管理员用户名作为提示
        try:
            self._fr_user.insert(0, ADMIN_DEFAULT_USER)
        except Exception: pass

        self._fr_msg = tk.Label(parent, text='', bg=_AUTH_BG_DARK,
                                fg=_AUTH_ADMIN, font=('SimSun', 9))
        self._fr_msg.pack(pady=(8, 0))

        btn = _make_round_button(parent, '🚀 创建管理员账号 并 登录',
                                  self._on_first_run_create,
                                  _AUTH_ADMIN, _AUTH_ADMIN_H,
                                  width=380, height=42, font_size=11)
        btn.pack(pady=(14, 0))
        self._fr_token.bind('<Return>',
                             lambda e: self._on_first_run_create())

    def _on_first_run_create(self):
        u  = self._fr_user.get().strip()
        p1 = self._fr_pass1.get()
        p2 = self._fr_pass2.get()
        tk_= self._fr_token.get()
        if not u:
            self._fr_msg.config(text='✗ 用户名不能为空'); return
        if len(p1) < 6:
            self._fr_msg.config(text='✗ 密码至少 6 位'); return
        if p1 != p2:
            self._fr_msg.config(text='✗ 两次密码不一致'); return
        if not tk_:
            self._fr_msg.config(text='✗ 必须填写管理员注册口令'); return
        ok, msg = register_admin_user(u, p1, tk_)
        if not ok:
            self._fr_msg.config(text='✗ ' + msg); return
        # 自动登录
        ok, user = authenticate(u, p1)
        if not ok:
            self._fr_msg.config(text='✗ 登录失败: ' + str(user)); return
        save_session(u)
        self.user = user
        self._close_and_continue()

    # ----------------------------------------------------------------
    #  正常运行: Tab(登录 / 注册)
    # ----------------------------------------------------------------
    def _build_normal(self, parent):
        # 自定义 Tab 切换条
        tab_bar = tk.Frame(parent, bg=_AUTH_BG_DARK, height=36)
        tab_bar.pack(fill=tk.X, pady=(4, 0))
        tab_bar.pack_propagate(False)

        self._tab_buttons = {}
        self._current_tab = 'login'

        def _make_tab(name, label):
            f = tk.Frame(tab_bar, bg=_AUTH_BG_DARK, cursor='hand2')
            lbl = tk.Label(f, text=label, bg=_AUTH_BG_DARK,
                           fg=_AUTH_FG_LIGHT,
                           font=('SimSun', 11, 'bold'),
                           padx=22, pady=6)
            lbl.pack()
            underline = tk.Frame(f, bg=_AUTH_BG_DARK, height=2)
            underline.pack(fill=tk.X)
            f._lbl = lbl; f._line = underline
            f.bind('<Button-1>',
                   lambda e, n=name: self._switch_tab(n))
            lbl.bind('<Button-1>',
                     lambda e, n=name: self._switch_tab(n))
            return f

        self._tab_buttons['login']    = _make_tab('login',    '登 录')
        self._tab_buttons['register'] = _make_tab('register', '注 册')
        self._tab_buttons['login'].pack(side=tk.LEFT, padx=(0, 14))
        self._tab_buttons['register'].pack(side=tk.LEFT)

        # 分隔线
        tk.Frame(parent, bg='#334155', height=1).pack(fill=tk.X, pady=(0, 6))

        # 主面板容器
        self._tab_panels = tk.Frame(parent, bg=_AUTH_BG_DARK)
        self._tab_panels.pack(fill=tk.BOTH, expand=True)

        self._build_login_panel()
        self._build_register_panel()

        self._switch_tab('login')

    def _switch_tab(self, name):
        for n, f in self._tab_buttons.items():
            if n == name:
                f._lbl.config(fg='white')
                f._line.config(bg=_AUTH_ACCENT)
            else:
                f._lbl.config(fg=_AUTH_FG_MUTED)
                f._line.config(bg=_AUTH_BG_DARK)
        self._current_tab = name
        self._panel_login.pack_forget()
        self._panel_register.pack_forget()
        if name == 'login':
            self._panel_login.pack(fill=tk.BOTH, expand=True)
            try: self._li_user.focus_set()
            except: pass
        else:
            self._panel_register.pack(fill=tk.BOTH, expand=True)
            try: self._rg_user.focus_set()
            except: pass

    # --- 登录面板 ---
    def _build_login_panel(self):
        self._panel_login = tk.Frame(self._tab_panels, bg=_AUTH_BG_DARK)

        def _row(lbl):
            tk.Label(self._panel_login, text=lbl, bg=_AUTH_BG_DARK,
                     fg=_AUTH_FG_LIGHT,
                     font=('SimSun', 10)).pack(anchor='w', pady=(10, 2))
            e = _make_entry(self._panel_login)
            e.pack(fill=tk.X, ipady=6)
            return e

        self._li_user = _row('用户名')
        self._li_pass = _row('密码')
        self._li_pass.config(show='●')

        # 60 天自动登录 checkbox
        cb_frame = tk.Frame(self._panel_login, bg=_AUTH_BG_DARK)
        cb_frame.pack(fill=tk.X, pady=(10, 0))
        self._li_remember = tk.IntVar(value=1)
        cb = tk.Checkbutton(cb_frame,
                            text='  60 天内免登录 (推荐)',
                            variable=self._li_remember,
                            bg=_AUTH_BG_DARK,
                            fg=_AUTH_FG_LIGHT,
                            selectcolor=_AUTH_BG_DARK,
                            activebackground=_AUTH_BG_DARK,
                            activeforeground='white',
                            font=('SimSun', 9), bd=0,
                            highlightthickness=0)
        cb.pack(anchor='w')

        # 错误提示
        self._li_msg = tk.Label(self._panel_login, text='',
                                bg=_AUTH_BG_DARK, fg=_AUTH_ADMIN,
                                font=('SimSun', 9))
        self._li_msg.pack(pady=(8, 0))

        btn = _make_round_button(self._panel_login, '登 录',
                                  self._on_login,
                                  _AUTH_ACCENT, _AUTH_ACCENT_H,
                                  width=380, height=42, font_size=12)
        btn.pack(pady=(15, 0))

        self._li_pass.bind('<Return>', lambda e: self._on_login())
        self._li_user.bind('<Return>',
                            lambda e: self._li_pass.focus_set())

        # 提示信息
        tip = tk.Label(self._panel_login,
                       text='💡 首次使用请切到「注 册」标签页创建账号',
                       bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                       font=('SimSun', 8))
        tip.pack(pady=(15, 0))

    def _on_login(self):
        u = self._li_user.get().strip()
        p = self._li_pass.get()
        ok, info = authenticate(u, p)
        if not ok:
            self._li_msg.config(text='✗ ' + str(info))
            return
        self.user = info
        if self._li_remember.get():
            save_session(u)
        else:
            clear_session()
        self._close_and_continue()

    # --- 注册面板 ---
    def _build_register_panel(self):
        self._panel_register = tk.Frame(self._tab_panels, bg=_AUTH_BG_DARK)

        # 滚动支持 (注册字段较多)
        wrap = tk.Frame(self._panel_register, bg=_AUTH_BG_DARK)
        wrap.pack(fill=tk.BOTH, expand=True)

        # ===== 作者微信号提示卡 (黄色高亮) =====
        wx_card = tk.Frame(wrap, bg='#FEF3C7',
                           highlightbackground='#F59E0B',
                           highlightthickness=2)
        wx_card.pack(fill=tk.X, pady=(2, 8))
        tk.Label(wx_card,
                 text='📞  注册前请先添加作者微信确认身份',
                 bg='#FEF3C7', fg='#92400E',
                 font=('SimSun', 10, 'bold')).pack(anchor='w',
                                                     padx=10, pady=(6, 0))
        tk.Label(wx_card,
                 text=f'微信号:  {AUTHOR_WECHAT}',
                 bg='#FEF3C7', fg='#0F172A',
                 font=('Times New Roman', 12, 'bold')).pack(anchor='w',
                                                              padx=10)
        tk.Label(wx_card,
                 text='(若需要禁用账号、找回密码、查看使用日志, '
                      '请联系作者协助)',
                 bg='#FEF3C7', fg='#78350F',
                 font=('SimSun', 8)).pack(anchor='w',
                                            padx=10, pady=(0, 6))

        def _row(parent, lbl):
            tk.Label(parent, text=lbl, bg=_AUTH_BG_DARK,
                     fg=_AUTH_FG_LIGHT,
                     font=('SimSun', 10)).pack(anchor='w', pady=(8, 2))
            e = _make_entry(parent)
            e.pack(fill=tk.X, ipady=5)
            return e

        self._rg_user  = _row(wrap, '用户名 (必填)')
        self._rg_full  = _row(wrap, '真实姓名 (可选)')
        self._rg_cont  = _row(wrap, '联系方式 (邮箱/微信, 可选)')
        self._rg_pass1 = _row(wrap, '密码 (至少 6 位, 必填)')
        self._rg_pass1.config(show='●')
        self._rg_pass2 = _row(wrap, '再次输入密码 (必填)')
        self._rg_pass2.config(show='●')

        # ---- 邀请码字段 ----
        if INVITE_REQUIRED:
            tk.Frame(wrap, bg='#334155', height=1).pack(
                fill=tk.X, pady=(8, 4))
            tk.Label(wrap,
                     text='🎫 邀请码 (必填 - 由作者生成后发给您)',
                     bg=_AUTH_BG_DARK, fg=_AUTH_WARN,
                     font=('SimSun', 10, 'bold')).pack(
                anchor='w', pady=(2, 2))
            self._rg_invite = _make_entry(wrap, font_size=10)
            self._rg_invite.pack(fill=tk.X, ipady=5)
            tk.Label(wrap,
                     text='格式示例:  zhangsan.20260626.A7F2B8D4',
                     bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                     font=('Times New Roman', 9, 'italic')).pack(
                anchor='w', pady=(2, 0))
        else:
            self._rg_invite = None

        self._rg_msg = tk.Label(wrap, text='',
                                bg=_AUTH_BG_DARK, fg=_AUTH_ADMIN,
                                font=('SimSun', 9))
        self._rg_msg.pack(pady=(6, 0))

        btn = _make_round_button(wrap, '✓ 注 册 并 登 录',
                                  self._on_register,
                                  _AUTH_OK, _AUTH_OK_H,
                                  width=380, height=42, font_size=11)
        btn.pack(pady=(12, 0))

        tk.Label(wrap,
                 text='💡 注册需要管理员发的邀请码。如忘记请联系作者重发。',
                 bg=_AUTH_BG_DARK, fg=_AUTH_FG_MUTED,
                 font=('SimSun', 8)).pack(pady=(10, 0))

    def _on_register(self):
        u  = self._rg_user.get().strip()
        f  = self._rg_full.get().strip()
        c  = self._rg_cont.get().strip()
        p1 = self._rg_pass1.get()
        p2 = self._rg_pass2.get()
        ic = (self._rg_invite.get().strip()
              if self._rg_invite is not None else '')
        if not u:
            self._rg_msg.config(text='✗ 用户名不能为空'); return
        if len(p1) < 6:
            self._rg_msg.config(text='✗ 密码至少 6 位'); return
        if p1 != p2:
            self._rg_msg.config(text='✗ 两次密码不一致'); return
        ok, msg = register_normal_user(u, p1,
                                        full_name=f, contact=c,
                                        invite_code=ic)
        if not ok:
            self._rg_msg.config(text='✗ ' + msg); return
        ok, info = authenticate(u, p1)
        if not ok:
            self._rg_msg.config(text='✗ 注册成功但登录失败: ' + str(info))
            return
        self.user = info
        save_session(u)
        self._close_and_continue()

    # ----------------------------------------------------------------
    #  关闭/退出
    # ----------------------------------------------------------------
    def _close_and_continue(self):
        try: self._win.quit()
        except Exception: pass
        try: self._win.destroy()
        except Exception: pass

    def _on_close(self):
        # 用户主动关闭 -> 退出整个软件
        self.user = None
        self._close_and_continue()


# ============================================================================
#  AdminApp  -  管理员模式 (第三板块)
# ============================================================================
class AdminApp:
    """管理员模式的 UI。
    被 Launcher 实例化为第三个模式 ('admin') 的内容。
    """

    def __init__(self, parent, launcher_ref=None):
        self.parent = parent
        self.launcher_ref = launcher_ref
        self.current_admin = None
        if launcher_ref is not None:
            self.current_admin = getattr(launcher_ref, 'current_user', None)

        self._build_ui()
        self.refresh_all()

    def _admin_username(self):
        if self.current_admin:
            return self.current_admin.get('username', '')
        return ''

    def _build_ui(self):
        BG = '#F5F6F8'
        self.parent.configure(bg=BG)

        # ============================================================
        # 顶部: 渐变深色栏 (高度 64) — 商业级设计
        # 左: 大 Logo + 应用名 + 面包屑
        # 右: 角色徽章 + 头像圆 + 用户名 + 操作按钮
        # ============================================================
        top = tk.Frame(self.parent, bg='#0F172A', height=64)
        top.pack(side=tk.TOP, fill=tk.X)
        top.pack_propagate(False)

        # 顶栏底部一道亮色细线 — 提升层次感
        tk.Frame(self.parent, bg='#3B82F6', height=2).pack(
            side=tk.TOP, fill=tk.X)

        # ---- 左侧: Logo + 应用名 + 面包屑 ----
        lt = tk.Frame(top, bg='#0F172A')
        lt.pack(side=tk.LEFT, padx=20, pady=10, fill=tk.Y)

        # 大盾牌图标
        tk.Label(lt, text='🛡️', bg='#0F172A',
                 font=('Segoe UI Emoji', 22)).pack(side=tk.LEFT)

        # 应用名 + 副标题 (两行)
        ttl_box = tk.Frame(lt, bg='#0F172A')
        ttl_box.pack(side=tk.LEFT, padx=(10, 0))
        tk.Label(ttl_box, text='Spine COBB Analyzer',
                 bg='#0F172A', fg='white',
                 font=('Times New Roman', 14, 'bold')).pack(anchor='w')
        # 面包屑 (将在 _switch_tab 时更新)
        self._breadcrumb_lbl = tk.Label(
            ttl_box, text='管理员控制台  ›  仪表盘',
            bg='#0F172A', fg='#64748B',
            font=('SimSun', 9))
        self._breadcrumb_lbl.pack(anchor='w')

        # ---- 右侧: 操作区 ----
        rt = tk.Frame(top, bg='#0F172A')
        rt.pack(side=tk.RIGHT, padx=14, pady=10)

        # 操作按钮
        for txt, cmd, c, ch in [
            ('🔄 刷新',         self.refresh_all,
             '#475569', '#334155'),
            ('🔑 修改密码',      self._change_my_password,
             '#3B82F6', '#2563EB'),
            ('🚪 退出',          self._logout,
             _AUTH_WARN, '#D97706'),
        ]:
            tk.Button(rt, text=txt, command=cmd,
                      bg=c, fg='white',
                      activebackground=ch, activeforeground='white',
                      relief='flat', bd=0, cursor='hand2',
                      font=('SimSun', 9, 'bold'),
                      padx=10, pady=5).pack(side=tk.RIGHT, padx=3)

        # 用户卡片(头像圆 + 用户名 + 角色徽章)
        u = self._admin_username() or '?'
        avatar_color = '#F59E0B'  # 管理员金色
        # 头像圆 (取用户名首字符)
        avatar_text = (u[:1].upper() if u else '?')

        prof_box = tk.Frame(rt, bg='#1E293B', cursor='hand2')
        prof_box.pack(side=tk.RIGHT, padx=(0, 12), ipadx=2, ipady=2)

        # 圆形头像 (用 Canvas 画)
        ava_size = 32
        ava_cv = tk.Canvas(prof_box, width=ava_size, height=ava_size,
                           bg='#1E293B', highlightthickness=0, bd=0)
        ava_cv.pack(side=tk.LEFT, padx=(6, 8), pady=4)
        ava_cv.create_oval(2, 2, ava_size-2, ava_size-2,
                           fill=avatar_color, outline='')
        ava_cv.create_text(ava_size/2, ava_size/2,
                           text=avatar_text,
                           fill='white',
                           font=('Times New Roman', 13, 'bold'))

        info_col = tk.Frame(prof_box, bg='#1E293B')
        info_col.pack(side=tk.LEFT, padx=(0, 10), pady=4)
        tk.Label(info_col, text=u, bg='#1E293B', fg='white',
                 font=('SimSun', 10, 'bold')).pack(anchor='w')
        # 角色徽章 (仅管理员显示金色徽章)
        tk.Label(info_col, text='👑 SUPER ADMIN', bg='#1E293B', fg='#FBBF24',
                 font=('Times New Roman', 8, 'bold')).pack(anchor='w')

        # ============================================================
        # Tab 导航 (现代浮动卡片风格)
        # ============================================================
        nav = tk.Frame(self.parent, bg=BG, height=46)
        nav.pack(side=tk.TOP, fill=tk.X)
        nav.pack_propagate(False)

        self._tabs = {}
        self._tab_panels = {}
        self._cur_tab = None

        for key, label, icon in [
            ('dashboard', '仪表盘',     '📊'),
            ('users',     '用户管理',   '👥'),
            ('logins',    '登录日志',   '🔐'),
            ('audit',     '审计日志',   '📋'),
            ('tools',     '工具箱',     '🛠️'),
            ('about',     '系统信息',   'ℹ️'),
        ]:
            f = tk.Frame(nav, bg=BG, cursor='hand2')
            l = tk.Label(f, text=f'{icon}  {label}',
                         bg=BG, fg='#475569',
                         font=('SimSun', 11, 'bold'),
                         padx=18, pady=10)
            l.pack()
            ul = tk.Frame(f, bg=BG, height=3); ul.pack(fill=tk.X)
            f._lbl = l; f._ul = ul
            f._key = key
            f._label_text = label
            f.pack(side=tk.LEFT)
            f.bind('<Button-1>',
                   lambda e, k=key: self._switch_tab(k))
            l.bind('<Button-1>',
                   lambda e, k=key: self._switch_tab(k))
            # hover 效果
            def _on_enter(e, lbl=l, frm=f):
                if frm._key != self._cur_tab:
                    lbl.configure(fg='#0F172A')
            def _on_leave(e, lbl=l, frm=f):
                if frm._key != self._cur_tab:
                    lbl.configure(fg='#475569')
            l.bind('<Enter>', _on_enter)
            l.bind('<Leave>', _on_leave)
            self._tabs[key] = f

        # 主体
        body = tk.Frame(self.parent, bg=BG)
        body.pack(side=tk.TOP, fill=tk.BOTH, expand=True,
                  padx=14, pady=(8, 0))

        for k in ('dashboard', 'users', 'logins', 'audit', 'tools', 'about'):
            p = tk.Frame(body, bg='white',
                         highlightbackground='#E2E8F0',
                         highlightthickness=1)
            self._tab_panels[k] = p

        self._build_dashboard_panel(self._tab_panels['dashboard'])
        self._build_users_panel(self._tab_panels['users'])
        self._build_logins_panel(self._tab_panels['logins'])
        self._build_audit_panel(self._tab_panels['audit'])
        self._build_tools_panel(self._tab_panels['tools'])
        self._build_about_panel(self._tab_panels['about'])

        # ============================================================
        # 底部状态栏 — 商业软件标配
        # ============================================================
        statusbar = tk.Frame(self.parent, bg='#E2E8F0', height=24)
        statusbar.pack(side=tk.BOTTOM, fill=tk.X)
        statusbar.pack_propagate(False)
        # 上边框线
        tk.Frame(statusbar, bg='#CBD5E1', height=1).pack(side=tk.TOP, fill=tk.X)

        sb_inner = tk.Frame(statusbar, bg='#E2E8F0')
        sb_inner.pack(fill=tk.X, padx=12, pady=2)

        tk.Label(sb_inner, text='● 已连接',
                 bg='#E2E8F0', fg='#16A34A',
                 font=('SimSun', 8, 'bold')).pack(side=tk.LEFT)

        try:
            db_p = _db_path()
            db_short = '...' + db_p[-40:] if len(db_p) > 40 else db_p
        except Exception:
            db_short = 'spineusers.db'
        tk.Label(sb_inner, text=f'  ·  数据库: {db_short}',
                 bg='#E2E8F0', fg='#475569',
                 font=('SimSun', 8)).pack(side=tk.LEFT)

        # [BUG 修复] 操作提示标签 (替代 messagebox.showinfo, 避免 Windows
        # tkinter 模态弹窗导致 "假死")
        self._sb_msg_lbl = tk.Label(
            sb_inner, text='', bg='#E2E8F0', fg='#10B981',
            font=('SimSun', 9, 'bold'))
        self._sb_msg_lbl.pack(side=tk.LEFT, padx=(20, 0))
        self._sb_msg_after_id = None

        # 右侧: 当前时间(动态更新) + 版本号
        self._sb_time_lbl = tk.Label(
            sb_inner, text='', bg='#E2E8F0', fg='#475569',
            font=('Times New Roman', 8))
        self._sb_time_lbl.pack(side=tk.RIGHT, padx=(0, 4))
        tk.Label(sb_inner, text='V1', bg='#E2E8F0', fg='#3B82F6',
                 font=('Times New Roman', 8, 'bold')).pack(
                     side=tk.RIGHT, padx=(0, 8))

        # 启动时钟 (每 30 秒更新一次, 不影响性能)
        self._update_status_clock()

        self._switch_tab('dashboard')

    def _update_status_clock(self):
        try:
            import time as _t
            now_str = _t.strftime('%Y-%m-%d  %H:%M:%S', _t.localtime())
            if hasattr(self, '_sb_time_lbl') and self._sb_time_lbl.winfo_exists():
                self._sb_time_lbl.configure(text=now_str)
                self.parent.after(1000, self._update_status_clock)
        except Exception: pass

    def _switch_tab(self, key):
        if self._cur_tab == key: return
        # 切换 tab 高亮
        for k, f in self._tabs.items():
            if k == key:
                f._lbl.config(fg='#0F172A')
                f._ul.config(bg=_AUTH_ACCENT)
            else:
                f._lbl.config(fg='#475569')
                f._ul.config(bg=f['bg'])
        # 切换 panel
        for k, p in self._tab_panels.items():
            try: p.pack_forget()
            except: pass
        self._tab_panels[key].pack(fill=tk.BOTH, expand=True)
        self._cur_tab = key
        # 同步面包屑
        try:
            label = self._tabs[key]._label_text
            if hasattr(self, '_breadcrumb_lbl'):
                self._breadcrumb_lbl.configure(
                    text=f'管理员控制台  ›  {label}')
        except Exception: pass
        # 刷新数据
        if key == 'dashboard':  self._refresh_dashboard()
        if key == 'users':      self._reload_users()
        if key == 'logins':     self._reload_logins()
        if key == 'audit':      self._reload_audit()

    # ----------------------------------------------------------------
    #  Tab: 用户管理
    # ----------------------------------------------------------------
    def _build_users_panel(self, parent):
        # 工具栏 (重新设计: 标题+统计在左, 搜索框居中, 操作按钮分组在右)
        tb = tk.Frame(parent, bg='#F8FAFC', height=52)
        tb.pack(side=tk.TOP, fill=tk.X)
        tb.pack_propagate(False)

        # ---- 左侧: 标题 + 用户数量徽章 ----
        left_box = tk.Frame(tb, bg='#F8FAFC')
        left_box.pack(side=tk.LEFT, padx=14, pady=10)
        tk.Label(left_box, text='👥', bg='#F8FAFC',
                 fg='#0F172A', font=('Segoe UI Emoji', 14)).pack(side=tk.LEFT)
        tk.Label(left_box, text='  所有注册用户', bg='#F8FAFC',
                 fg='#0F172A', font=('SimSun', 12, 'bold')).pack(side=tk.LEFT)
        # 用户数量徽章 (动态更新)
        self._user_count_lbl = tk.Label(
            left_box, text='  · 共 0 人',
            bg='#F8FAFC', fg='#64748B',
            font=('SimSun', 10))
        self._user_count_lbl.pack(side=tk.LEFT)

        # ---- 中间: 搜索框 ----
        mid_box = tk.Frame(tb, bg='#F8FAFC')
        mid_box.pack(side=tk.LEFT, padx=20)
        tk.Label(mid_box, text='🔍', bg='#F8FAFC',
                 font=('Segoe UI Emoji', 11)).pack(side=tk.LEFT)
        self._user_search_var = tk.StringVar()
        search_ent = tk.Entry(
            mid_box, textvariable=self._user_search_var,
            font=('SimSun', 10), width=20,
            relief='solid', bd=1, bg='white', fg='#0F172A')
        search_ent.pack(side=tk.LEFT, padx=(4, 0), ipady=2)
        try:
            search_ent.bind('<KeyRelease>',
                            lambda _e: self._reload_users())
        except Exception: pass

        # ---- 右侧: 操作按钮 (分组) ----
        # 分组1: 数据/创建 (蓝青色系)
        # 分组2: 状态变更 (绿橙色系)
        # 分组3: 危险操作 (红色)
        # 分组之间用 vertical separator 隔开,视觉对仗工整

        def _btn(parent, txt, cmd, c, ch, narrow=False):
            return tk.Button(
                parent, text=txt, command=cmd,
                bg=c, fg='white',
                activebackground=ch, activeforeground='white',
                relief='flat', bd=0, cursor='hand2',
                font=('SimSun', 9, 'bold'),
                padx=8 if narrow else 10, pady=4)

        def _sep(parent):
            tk.Frame(parent, bg='#CBD5E1', width=1).pack(
                side=tk.LEFT, fill=tk.Y, padx=6, pady=12)

        right_box = tk.Frame(tb, bg='#F8FAFC')
        right_box.pack(side=tk.RIGHT, padx=14, pady=8)

        # group 3: 危险操作 (放最右边,需要选择某个用户后才能用)
        _btn(right_box, '🗑 删除',  self._delete_selected,
             _AUTH_ADMIN, _AUTH_ADMIN_H).pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '🔑 重置密码', self._reset_pwd_selected,
             '#3B82F6', '#2563EB').pack(side=tk.RIGHT, padx=2)
        _sep(right_box)

        # group 2: 状态变更
        _btn(right_box, '⊘ 禁用',
             lambda: self._set_status_selected('disabled'),
             _AUTH_WARN, '#D97706').pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '✓ 启用',
             lambda: self._set_status_selected('active'),
             _AUTH_OK, _AUTH_OK_H).pack(side=tk.RIGHT, padx=2)
        _sep(right_box)

        # group 1: 数据 / 创建
        _btn(right_box, '➕ 新增用户', self._add_user_dialog,
             _AUTH_OK, _AUTH_OK_H).pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '🎫 邀请码', self._gen_invite_dialog,
             '#A855F7', '#9333EA').pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '🔑 激活密钥', self._gen_license_dialog,
             '#8B5CF6', '#7C3AED').pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '📤 导出', self._export_users_csv,
             '#0EA5E9', '#0284C7').pack(side=tk.RIGHT, padx=2)
        _btn(right_box, '🔄 刷新', self._reload_users,
             '#64748B', '#475569').pack(side=tk.RIGHT, padx=2)

        # Treeview
        tv_frame = tk.Frame(parent, bg='white')
        tv_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 10))

        cols = ('id', 'username', 'role', 'status',
                'full_name', 'contact', 'created', 'last_login')
        self._tv_users = ttk.Treeview(tv_frame, columns=cols,
                                       show='headings', height=18)
        # 排序状态: {col: (ascending_bool)} 切换 asc/desc
        self._tv_users_sort = {}
        col_titles = {
            'id': 'ID', 'username': '用户名', 'role': '角色',
            'status': '状态', 'full_name': '真实姓名',
            'contact': '联系方式', 'created': '注册时间',
            'last_login': '最后登录'
        }
        for c in cols:
            self._tv_users.heading(
                c, text=col_titles[c],
                command=lambda _c=c: self._sort_users(_c))
        self._tv_users.column('id',         width=50,  anchor='center')
        self._tv_users.column('username',   width=140, anchor='w')
        self._tv_users.column('role',       width=80,  anchor='center')
        self._tv_users.column('status',     width=80,  anchor='center')
        self._tv_users.column('full_name',  width=120, anchor='w')
        self._tv_users.column('contact',    width=180, anchor='w')
        self._tv_users.column('created',    width=140, anchor='center')
        self._tv_users.column('last_login', width=140, anchor='center')

        self._tv_users.tag_configure('admin', background='#FEF3C7')
        self._tv_users.tag_configure('disabled', background='#FEE2E2',
                                     foreground='#991B1B')
        self._tv_users.tag_configure('pending', background='#DBEAFE')

        sb = ttk.Scrollbar(tv_frame, orient='vertical',
                            command=self._tv_users.yview)
        self._tv_users.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)
        self._tv_users.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # 双击查看详情
        self._tv_users.bind('<Double-1>', lambda e: self._view_user_detail())

    def _sort_users(self, col):
        """点击列头切换升降序排序"""
        try:
            tv = self._tv_users
            asc = not self._tv_users_sort.get(col, False)
            self._tv_users_sort = {col: asc}  # 只保留当前排序列
            data = [(tv.set(it, col), it) for it in tv.get_children('')]

            # 智能比较: ID 列按数字排序, 时间列保留原文本(YYYY-MM-DD)
            def _key(x):
                v = x[0]
                if col == 'id':
                    try: return int(v)
                    except: return 0
                return v or ''
            data.sort(key=_key, reverse=not asc)
            for idx, (_v, it) in enumerate(data):
                tv.move(it, '', idx)

            # 更新表头显示排序方向 (▲ asc / ▼ desc)
            col_titles = {
                'id': 'ID', 'username': '用户名', 'role': '角色',
                'status': '状态', 'full_name': '真实姓名',
                'contact': '联系方式', 'created': '注册时间',
                'last_login': '最后登录'
            }
            for c in tv['columns']:
                base = col_titles.get(c, c)
                if c == col:
                    arrow = ' ▲' if asc else ' ▼'
                    tv.heading(c, text=base + arrow)
                else:
                    tv.heading(c, text=base)
        except Exception:
            pass

    def _sort_tv(self, tv, col, sort_state, titles):
        """通用 Treeview 列点击排序 (logins / audit 用)"""
        try:
            asc = not sort_state.get(col, False)
            sort_state.clear()
            sort_state[col] = asc
            data = [(tv.set(it, col), it) for it in tv.get_children('')]
            data.sort(key=lambda x: (x[0] or ''), reverse=not asc)
            for idx, (_v, it) in enumerate(data):
                tv.move(it, '', idx)
            for c in tv['columns']:
                base = titles.get(c, c)
                if c == col:
                    arrow = ' ▲' if asc else ' ▼'
                    tv.heading(c, text=base + arrow)
                else:
                    tv.heading(c, text=base)
        except Exception:
            pass

    def _export_users_csv(self):
        """新功能: 一键导出所有用户到 CSV"""
        try:
            from tkinter import filedialog
            import csv, time as _t
            default_name = f'users_{_t.strftime("%Y%m%d_%H%M%S")}.csv'
            path = filedialog.asksaveasfilename(
                title='导出用户列表',
                defaultextension='.csv',
                initialfile=default_name,
                filetypes=[('CSV', '*.csv'), ('All', '*.*')])
            if not path: return
            with open(path, 'w', encoding='utf-8-sig', newline='') as f:
                w = csv.writer(f)
                w.writerow(['ID', '用户名', '角色', '状态',
                            '真实姓名', '联系方式', '注册时间', '最后登录'])
                for u in list_users():
                    role = '管理员' if u.get('is_admin') else '普通用户'
                    w.writerow([
                        u['id'], u['username'], role, u.get('status', ''),
                        u.get('full_name') or '', u.get('contact') or '',
                        fmt_time(u.get('created_at')),
                        fmt_time(u.get('last_login_at')),
                    ])
            messagebox.showinfo('导出成功',
                                f'已导出 {len(list_users())} 个用户到:\n{path}')
            try: log_audit(self._admin_username(), 'export_users', path)
            except Exception: pass
        except Exception as e:
            messagebox.showerror('导出失败', f'{type(e).__name__}: {e}')

    def _reload_users(self):
        for it in self._tv_users.get_children():
            self._tv_users.delete(it)
        # 搜索过滤
        search_q = ''
        try:
            if hasattr(self, '_user_search_var'):
                search_q = (self._user_search_var.get() or '').strip().lower()
        except Exception: pass

        all_users = list_users()
        shown = 0
        admin_cnt = 0
        active_cnt = 0
        disabled_cnt = 0
        for u in all_users:
            if u.get('is_admin'): admin_cnt += 1
            st = u.get('status', '')
            if st == 'active':   active_cnt += 1
            elif st == 'disabled': disabled_cnt += 1

            if search_q:
                hay = ' '.join(str(x or '').lower() for x in [
                    u.get('username'), u.get('full_name'),
                    u.get('contact'), u.get('status'),
                    'admin' if u.get('is_admin') else 'normal',
                ])
                if search_q not in hay:
                    continue

            role = '👑 管理员' if u.get('is_admin') else '普通用户'
            status_zh = {'active': '✓ 正常',
                         'pending': '⏳ 待批准',
                         'disabled': '⊘ 已禁用'}.get(
                             u.get('status', ''), u.get('status', ''))
            tag = ()
            if u.get('is_admin'): tag = ('admin',)
            elif u.get('status') == 'disabled': tag = ('disabled',)
            elif u.get('status') == 'pending':  tag = ('pending',)

            self._tv_users.insert('', 'end', values=(
                u['id'], u['username'], role, status_zh,
                u.get('full_name') or '',
                u.get('contact')   or '',
                fmt_time(u.get('created_at')),
                fmt_time(u.get('last_login_at')),
            ), tags=tag)
            shown += 1

        # 更新计数徽章
        try:
            if hasattr(self, '_user_count_lbl'):
                if search_q:
                    self._user_count_lbl.config(
                        text=f'  · 显示 {shown} / 共 {len(all_users)} 人 '
                             f'(👑 {admin_cnt} · ✓ {active_cnt} · ⊘ {disabled_cnt})')
                else:
                    self._user_count_lbl.config(
                        text=f'  · 共 {len(all_users)} 人 '
                             f'(👑 {admin_cnt} · ✓ {active_cnt} · ⊘ {disabled_cnt})')
        except Exception: pass

    def _selected_username(self):
        sel = self._tv_users.selection()
        if not sel:
            messagebox.showinfo('提示', '请先选中一个用户', parent=self.parent)
            return None
        vals = self._tv_users.item(sel[0], 'values')
        return vals[1] if vals else None

    def _flash_status(self, text, color='#10B981'):
        """[BUG 加固] 在状态栏短暂显示一条消息, 替代 messagebox.showinfo
        理由: Windows tkinter 的 messagebox 在某些情况下会出现窗口层级混乱
        (弹窗被主窗口挡住), 用户视觉上看起来 "软件卡退死机" 但其实在等点击。
        改用状态栏闪烁提示, 避免任何模态弹窗。
        """
        try:
            if hasattr(self, '_sb_msg_lbl'):
                self._sb_msg_lbl.configure(text=text, fg=color)
                # 5 秒后清空
                if hasattr(self, '_sb_msg_after_id') and self._sb_msg_after_id:
                    try: self.parent.after_cancel(self._sb_msg_after_id)
                    except Exception: pass
                self._sb_msg_after_id = self.parent.after(
                    5000, lambda: self._sb_msg_lbl.configure(text=''))
            else:
                # 没有状态栏时回退到 print (至少不会卡 GUI)
                try: print(f'[Status] {text}')
                except Exception: pass
        except Exception: pass

    def _set_status_selected(self, status):
        # ============================================================
        # [BUG 修复 v3] 用户报告"禁用/启用用户时软件卡退死机" - 多重防御
        #
        # 已确认的修复 (此前已部署):
        #   1) Lock -> RLock (修复 log_audit 嵌套死锁)
        #   2) log_audit 全部移出 _DB_LOCK (修复 SQLite BUSY 阻塞)
        #   3) 成功消息改用状态栏 (避免 Windows messagebox 层级假死)
        #
        # 本轮新增防御:
        #   4) 关键步骤都打 _crash_log, 即使再卡死, 用户能看到准确进度
        #   5) UI 刷新 (_reload_users / _refresh_dashboard) 移到 after_idle,
        #      让当前事件回调先返回, mainloop 喘口气, 再做下次 UI 重绘。
        #      这样即使 _reload_users 内部慢, 也不会阻塞当前点击的事件循环。
        # ============================================================
        u = self._selected_username()
        if not u: return
        _crash_log(f'_set_status_selected START: user={u}, status={status}')
        try:
            ok, msg = admin_set_status(u, status, self._admin_username())
        except Exception as ex:
            _crash_log(f'_set_status_selected DB ERROR', err=ex)
            try:
                messagebox.showerror('操作失败',
                                     f'{type(ex).__name__}: {ex}',
                                     parent=self.parent)
            except Exception: pass
            return
        _crash_log(f'_set_status_selected DB DONE: ok={ok}, msg={msg}')
        if ok:
            action_zh = {'active': '启用', 'pending': '设为待审批',
                         'disabled': '禁用'}.get(status, status)
            self._flash_status(f'✓ 已{action_zh}用户 "{u}"', '#10B981')
            # 异步刷新 UI (避免阻塞当前事件)
            def _do_refresh():
                try: self._reload_users()
                except Exception as ex2:
                    _crash_log('_set_status_selected reload_users ERROR', err=ex2)
                try: self._refresh_dashboard()
                except Exception as ex3:
                    _crash_log('_set_status_selected refresh_dashboard ERROR', err=ex3)
            try:
                self.parent.after_idle(_do_refresh)
            except Exception:
                _do_refresh()  # 退化到同步
        else:
            try:
                messagebox.showerror('失败', msg, parent=self.parent)
            except Exception: pass

    def _delete_selected(self):
        # ============================================================
        # [BUG 修复 v3] 同 _set_status_selected: 加诊断日志 + 异步刷新
        # ============================================================
        u = self._selected_username()
        if not u: return
        if not messagebox.askyesno('确认',
                f'确定要删除用户 "{u}" 吗?\n该操作不可恢复!',
                parent=self.parent):
            return
        _crash_log(f'_delete_selected START: user={u}')
        try:
            ok, msg = admin_delete_user(u, self._admin_username())
        except Exception as ex:
            _crash_log(f'_delete_selected DB ERROR', err=ex)
            try:
                messagebox.showerror('删除失败',
                                     f'{type(ex).__name__}: {ex}',
                                     parent=self.parent)
            except Exception: pass
            return
        _crash_log(f'_delete_selected DB DONE: ok={ok}')
        if ok:
            self._flash_status(f'✓ 已删除用户 "{u}"', '#DC2626')
            # 异步刷新 UI
            def _do_refresh():
                try: self._reload_users()
                except Exception as ex2:
                    _crash_log('_delete_selected reload_users ERROR', err=ex2)
                try: self._refresh_dashboard()
                except Exception as ex3:
                    _crash_log('_delete_selected refresh_dashboard ERROR', err=ex3)
            try:
                self.parent.after_idle(_do_refresh)
            except Exception:
                _do_refresh()
        else:
            try:
                messagebox.showerror('失败', msg, parent=self.parent)
            except Exception: pass

    def _reset_pwd_selected(self):
        # ============================================================
        # [BUG 加固] 异常兜底
        # ============================================================
        u = self._selected_username()
        if not u: return
        new_pwd = simpledialog.askstring(
            '重置密码',
            f'为用户 "{u}" 设置新密码 (至少 6 位):',
            parent=self.parent, show='●')
        if not new_pwd: return
        try:
            ok, msg = admin_reset_password(u, new_pwd, self._admin_username())
        except Exception as ex:
            try:
                messagebox.showerror('重置失败',
                                     f'{type(ex).__name__}: {ex}',
                                     parent=self.parent)
            except Exception: pass
            return
        if ok:
            # [BUG 修复 v2] 用状态栏替代成功 messagebox
            self._flash_status(f'✓ 已重置 "{u}" 的密码', '#0EA5E9')
        else:
            try:
                messagebox.showerror('失败', msg, parent=self.parent)
            except Exception: pass

    def _gen_license_dialog(self):
        """生成激活密钥对话框 - 这是新版主要功能, 替代账号注册体系"""
        dlg = tk.Toplevel(self.parent)
        dlg.title('🔑 生成激活密钥')
        dlg.geometry('640x720')
        dlg.minsize(560, 660)
        dlg.configure(bg='white')
        dlg.transient(self.parent)
        dlg.grab_set()

        # 标题
        tk.Label(dlg, text='🔑 生成激活密钥',
                 bg='white', fg='#0F172A',
                 font=('SimSun', 14, 'bold')).pack(pady=(16, 4))
        tk.Label(dlg,
                 text='给对方生成一个激活密钥, 对方输入后可在他电脑上免密钥使用 N 天',
                 bg='white', fg='#64748B',
                 font=('SimSun', 9)).pack(pady=(0, 12))

        body = tk.Frame(dlg, bg='white')
        body.pack(fill=tk.X, padx=24)

        # ==================================================
        #  角色选择
        # ==================================================
        tk.Label(body, text='角色 *',
                 bg='white', font=('SimSun', 10)).pack(anchor='w',
                                                         pady=(4, 4))
        role_var = tk.StringVar(value='U')
        role_frame = tk.Frame(body, bg='white')
        role_frame.pack(fill=tk.X, pady=(0, 8))

        # 占位变量, 后面引用 days_e (Python 闭包)
        days_e_holder = {}

        def _on_role_change():
            """切换角色时, 自动调整默认天数"""
            de = days_e_holder.get('e')
            if de is None: return
            de.delete(0, tk.END)
            if role_var.get() == 'A':
                de.insert(0, str(ADMIN_LICENSE_DAYS))  # 管理员=100年
            else:
                de.insert(0, str(LICENSE_DEFAULT_DAYS))  # 普通=30天
            _update_expiry_preview()

        tk.Radiobutton(role_frame, text='👤 普通用户 (默认 30 天)',
                       variable=role_var, value='U',
                       bg='white', font=('SimSun', 10),
                       command=_on_role_change
                       ).pack(side=tk.LEFT, padx=(0, 16))
        tk.Radiobutton(role_frame,
                       text='🛡️ 管理员 (无限期 - 100 年)',
                       variable=role_var, value='A',
                       bg='white', font=('SimSun', 10),
                       command=_on_role_change
                       ).pack(side=tk.LEFT)

        # ==================================================
        #  接收人标识
        # ==================================================
        tk.Label(body,
                 text='接收人标识 (可选 - 建议填对方微信号/姓名拼音, 便于追溯)',
                 bg='white', font=('SimSun', 10)).pack(anchor='w',
                                                         pady=(8, 2))
        ident_e = tk.Entry(body, font=('SimSun', 11),
                           relief='solid', bd=1)
        ident_e.pack(fill=tk.X, ipady=5)

        # ==================================================
        #  有效期 - 自由输入 + 快捷按钮 + 实时过期日期预览
        # ==================================================
        tk.Label(body,
                 text='有效期 (天) - 可手动输入任意天数, 或点下方快捷按钮',
                 bg='white', font=('SimSun', 10, 'bold')).pack(
            anchor='w', pady=(10, 2))
        days_e = tk.Entry(body, font=('SimSun', 12, 'bold'),
                          relief='solid', bd=1, fg='#7C3AED')
        days_e.insert(0, str(LICENSE_DEFAULT_DAYS))
        days_e.pack(fill=tk.X, ipady=6)
        days_e_holder['e'] = days_e

        # ---- 快捷预设按钮一行 ----
        QUICK_PRESETS = [
            ('1 天',    1,     '#FECACA'),  # 浅红
            ('2 天',    2,     '#FED7AA'),
            ('7 天',    7,     '#FEF3C7'),
            ('14 天',   14,    '#FDE68A'),
            ('30 天',   30,    '#D1FAE5'),  # 浅绿 (默认)
            ('60 天',   60,    '#A7F3D0'),
            ('100 天',  100,   '#BBF7D0'),
            ('180 天',  180,   '#BAE6FD'),
            ('1 年',    365,   '#93C5FD'),
            ('3 年',    1095,  '#A5B4FC'),
            ('永久',    36500, '#C4B5FD'),  # 紫色 = 100 年
        ]

        def _make_preset_handler(d):
            def handler():
                days_e.delete(0, tk.END)
                days_e.insert(0, str(d))
                _update_expiry_preview()
            return handler

        # 按钮分两行排, 每行 6 个左右
        quick_wrap = tk.Frame(body, bg='white')
        quick_wrap.pack(fill=tk.X, pady=(6, 0))
        row1 = tk.Frame(quick_wrap, bg='white'); row1.pack(fill=tk.X)
        row2 = tk.Frame(quick_wrap, bg='white'); row2.pack(fill=tk.X, pady=(4, 0))

        for i, (label, d, color) in enumerate(QUICK_PRESETS):
            target_row = row1 if i < 6 else row2
            tk.Button(target_row, text=label,
                      command=_make_preset_handler(d),
                      bg=color, fg='#0F172A',
                      activebackground='#FBBF24',
                      activeforeground='white',
                      relief='flat', bd=0,
                      cursor='hand2',
                      font=('SimSun', 9, 'bold'),
                      padx=10, pady=4).pack(side=tk.LEFT, padx=(0, 4))

        # ---- 实时过期日期预览 ----
        expiry_preview_var = tk.StringVar(value='')

        def _update_expiry_preview(*_):
            try:
                d = int(days_e.get().strip())
                if d <= 0: raise ValueError
                from datetime import datetime, timedelta
                future = datetime.now() + timedelta(days=d)
                if d >= 365:
                    yrs = d // 365
                    rem = d % 365
                    if rem == 0:
                        suffix = f'  ({yrs} 年)'
                    else:
                        suffix = f'  ({yrs} 年 {rem} 天)'
                else:
                    suffix = f'  ({d} 天)'
                expiry_preview_var.set(
                    f'📅 预计过期日期: {future.strftime("%Y-%m-%d")}{suffix}')
            except Exception:
                expiry_preview_var.set('⚠ 请输入正整数天数')

        tk.Label(body, textvariable=expiry_preview_var,
                 bg='white', fg='#059669',
                 font=('SimSun', 10, 'bold')).pack(anchor='w',
                                                     pady=(8, 0))
        days_e.bind('<KeyRelease>', _update_expiry_preview)
        _update_expiry_preview()  # 初始化显示

        # ==================================================
        #  分隔线 + 结果显示
        # ==================================================
        tk.Frame(body, bg='#E2E8F0', height=1).pack(
            fill=tk.X, pady=(16, 8))
        tk.Label(body, text='生成的激活密钥:',
                 bg='white', font=('SimSun', 10, 'bold')).pack(
            anchor='w', pady=(2, 4))

        result_var = tk.StringVar(value='(填写上方信息后点"生成"按钮)')
        result_e = tk.Entry(body, textvariable=result_var,
                            font=('Consolas', 11, 'bold'),
                            relief='solid', bd=1,
                            fg='#0F172A',
                            readonlybackground='#FEF3C7',
                            state='readonly')
        result_e.pack(fill=tk.X, ipady=8)

        info_var = tk.StringVar(value='')
        tk.Label(body, textvariable=info_var,
                 bg='white', fg='#059669',
                 font=('SimSun', 9)).pack(anchor='w', pady=(4, 0))

        def _do_generate():
            role = role_var.get()
            ident = ident_e.get().strip()
            try:
                days = int(days_e.get().strip() or LICENSE_DEFAULT_DAYS)
            except ValueError:
                info_var.set('✗ 有效期必须是数字'); return
            if days <= 0:
                info_var.set('✗ 有效期必须 > 0'); return
            if days > 36500 * 2:
                info_var.set('✗ 有效期太长 (最多 200 年)'); return
            key = generate_license_key(role=role,
                                        valid_days=days,
                                        identity=ident)
            if not key:
                info_var.set('✗ 生成失败'); return
            result_var.set(key)
            role_zh = '管理员' if role == 'A' else '普通用户'
            if days >= 365:
                yrs = days // 365
                rem = days % 365
                period_zh = (f'{yrs} 年' if rem == 0
                              else f'{yrs} 年 {rem} 天')
                info_var.set(f'✓ 已生成 {role_zh} 密钥, 有效期 {period_zh}')
            else:
                info_var.set(f'✓ 已生成 {role_zh} 密钥, 有效期 {days} 天')
            try:
                log_audit(self._admin_username(),
                          'gen_license',
                          f'role={role}, identity={ident}, days={days}')
            except Exception: pass

        def _do_copy():
            code = result_var.get()
            if not code or '(' in code:
                info_var.set('✗ 请先生成密钥'); return
            try:
                dlg.clipboard_clear()
                dlg.clipboard_append(code)
                dlg.update()
                info_var.set('✓ 已复制到剪贴板')
            except Exception as e:
                info_var.set(f'✗ 复制失败: {e}')

        # 按钮组
        btnbar = tk.Frame(body, bg='white')
        btnbar.pack(fill=tk.X, pady=(16, 0))

        tk.Button(btnbar, text='🎲 生 成',
                  command=_do_generate,
                  bg='#8B5CF6', fg='white',
                  activebackground='#7C3AED',
                  activeforeground='white',
                  relief='flat', font=('SimSun', 11, 'bold'),
                  padx=18, pady=6, cursor='hand2').pack(
            side=tk.LEFT, padx=(0, 8))
        tk.Button(btnbar, text='📋 复制密钥',
                  command=_do_copy,
                  bg='#0EA5E9', fg='white',
                  activebackground='#0284C7',
                  activeforeground='white',
                  relief='flat', font=('SimSun', 11, 'bold'),
                  padx=18, pady=6, cursor='hand2').pack(
            side=tk.LEFT)
        tk.Button(btnbar, text='关闭',
                  command=dlg.destroy,
                  bg='#64748B', fg='white',
                  activebackground='#475569',
                  activeforeground='white',
                  relief='flat', font=('SimSun', 10),
                  padx=14, pady=6, cursor='hand2').pack(side=tk.RIGHT)

        # 帮助文字
        help_frame = tk.Frame(dlg, bg='#F1F5F9')
        help_frame.pack(side=tk.BOTTOM, fill=tk.X, padx=24, pady=12)
        tk.Label(help_frame, text='💡  使用说明',
                 bg='#F1F5F9', fg='#0F172A',
                 font=('SimSun', 9, 'bold')).pack(anchor='w',
                                                    padx=10, pady=(8, 2))
        tk.Label(help_frame,
                 text='1. 选择角色: 👤 普通用户 (给对方) 或 🛡️ 管理员 (给您自己, 永久)\n'
                      '2. 接收人标识填对方微信/姓名拼音 (便于追溯, 可不填)\n'
                      '3. 设置有效期: 直接在框里输入任意天数, 或点下方快捷按钮\n'
                      '   • 1/2/7 天: 短期试用 / 临时使用\n'
                      '   • 30/60/100 天: 常规授权\n'
                      '   • 1/3 年 / 永久: 长期信任的对方\n'
                      '4. 点"生成" -> "复制密钥" -> 微信发给对方',
                 bg='#F1F5F9', fg='#475569',
                 justify=tk.LEFT,
                 font=('SimSun', 9)).pack(anchor='w', padx=10,
                                            pady=(0, 8))

        ident_e.focus_set()
        ident_e.bind('<Return>', lambda e: days_e.focus_set())
        days_e.bind('<Return>', lambda e: _do_generate())

