    def _build_about_panel(self, parent):
        # ============================================================
        # [问题6 修复] 系统信息面板重构 — 仿企业级控制台 (如 Grafana / Datadog):
        #   原本: 一大坨纯文本 Text widget, 信息密集、无视觉层次。
        #   新版:
        #     · 顶部 Hero 区: 应用图标 + 名称 + 版本徽章 + 简介
        #     · 横向 3 卡片: 数据库 / Token / 设备指纹 (用色块 + 等宽字体展示路径)
        #     · "安全机制" 卡片: 用 ✓ 列表展示
        #     · "用户角色" 卡片: 双栏对比 (管理员 vs 普通用户)
        #     · 底部 footer: 版权 / 技术栈
        # ============================================================
        # 用 Canvas + Scrollbar 做一个可滚动容器, 防止内容超出
        out = tk.Frame(parent, bg='white')
        out.pack(fill=tk.BOTH, expand=True)
        cv = tk.Canvas(out, bg='white', highlightthickness=0, bd=0)
        sb = ttk.Scrollbar(out, orient='vertical', command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)
        cv.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        wrap = tk.Frame(cv, bg='white')
        cv_window = cv.create_window((0, 0), window=wrap, anchor='nw')
        def _on_wrap_configure(_e=None):
            cv.configure(scrollregion=cv.bbox('all'))
        def _on_cv_configure(e):
            try: cv.itemconfigure(cv_window, width=e.width)
            except Exception: pass
        wrap.bind('<Configure>', _on_wrap_configure)
        cv.bind('<Configure>', _on_cv_configure)
        # 鼠标滚轮支持
        def _on_wheel(e):
            try:
                d = -1 * (e.delta // 120) if e.delta else (1 if e.num == 5 else -1)
                cv.yview_scroll(d, 'units')
            except Exception: pass
        cv.bind('<MouseWheel>', _on_wheel)
        cv.bind('<Button-4>', _on_wheel)
