# ============================================================================
#  AI ADVISOR MODULE — v3 新增
# ----------------------------------------------------------------------------
#  把本地 Pareto 分析结果发到云端 LLM (Gemini / Claude / SiliconFlow / 自定义
#  OpenAI 兼容端点),获取更深入的"AI 智能临床建议"。同时支持把任何分析建议
#  导出为 .txt 或 .docx。
#
#  设计要点:
#   1. API key 保存在用户主目录的 ~/.spine_cobb_ai_keys.json (本地、不上传)。
#   2. 每个 provider 都是 _BaseAIProvider 的子类,统一 .call() 接口。
#   3. 网络调用使用 urllib.request,避免对 'requests' 第三方包的硬依赖。
#   4. UI: AIAdvisorDialog 提供 provider 下拉、key 输入、上下文预览、
#          模型下拉、提交按钮、回答区、导出 TXT / Word 按钮。
#   5. 不导出 word 时若没装 python-docx 自动 fallback 到 RTF。
# ============================================================================

import json as _ai_json
import urllib.request as _ai_url
import urllib.error  as _ai_urlerr
import ssl as _ai_ssl


_AI_KEYS_FILE = os.path.join(os.path.expanduser('~'), '.spine_cobb_ai_keys.json')


def _ai_load_keys():
    """Load API keys.
    Priority: 1) os.environ (from .env)  2) legacy ~/.spine_cobb_ai_keys.json
    """
    keys = {}
    # 1. Environment variables (populated by config.load_env from .env)
    _ENV_MAP = {
        "gemini":      "GEMINI_API_KEY",
        "siliconflow": "SILICONFLOW_API_KEY",
        "claude":      "CLAUDE_API_KEY",
        "openai":      "OPENAI_API_KEY",
    }
    for code, var in _ENV_MAP.items():
        val = os.environ.get(var, "").strip()
        if val:
            keys[code] = {"api_key": val}
    # 2. Legacy file fallback (~/.spine_cobb_ai_keys.json)
    try:
        if os.path.isfile(_AI_KEYS_FILE):
            with open(_AI_KEYS_FILE, "r", encoding="utf-8") as f:
                legacy = _ai_json.load(f)
            if isinstance(legacy, dict):
                for k, v in legacy.items():
                    if k not in keys:
                        keys[k] = v
    except Exception:
        pass
    return keys
def _ai_save_keys(keys_dict):
    """把 API key 字典保存到本地文件 (mode 0600)"""
    try:
        with open(_AI_KEYS_FILE, 'w', encoding='utf-8') as f:
            _ai_json.dump(keys_dict, f, ensure_ascii=False, indent=2)
        try:
            if sys.platform != 'win32':
                os.chmod(_AI_KEYS_FILE, 0o600)
        except Exception:
            pass
        return True
    except Exception:
        return False


class _BaseAIProvider:
    """所有 AI provider 的统一基类"""
    code = "base"
    display_name = "Base"
    needs_key = True
    default_models = []     # list of (model_id, display_label)
    key_help = ""           # 显示给用户的"如何申请密钥"提示

    # [v4 新增] 临时性/可重试错误码集合
    _RETRYABLE_HTTP = {408, 425, 429, 500, 502, 503, 504, 520, 522, 524, 529}

    @classmethod
    def call(cls, prompt, api_key, model=None, timeout=60, **kwargs):
        """同步调用 LLM 并返回纯文本回答。出错时 raise.

        kwargs 可包含 proxy_url (例如 'http://127.0.0.1:7890') 覆盖系统代理。
        """
        raise NotImplementedError

    # ----------------------------------------------------------------
    # [v4 大幅强化] _post_json:
    #   1) 自动重试: 对 5xx / 429 / 网络超时, 最多重试 3 次, 指数退避
    #      (1.5s, 3s, 6s) — 用户报告的 503 大多是 Gemini 临时过载, 重试
    #      通常就能成功
    #   2) 显式代理支持: 优先 proxy_url, 否则读 HTTPS_PROXY / HTTP_PROXY
    #      环境变量 (Windows 用户常忘了把"梯子"配置到环境变量, 导致
    #      urllib 不走代理 → 连接超时)
    #   3) 错误信息中文化, 区分:
    #       • 服务器临时过载  (重试已耗尽: 503 / 502 / 504)
    #       • 鉴权失败       (401 / 403): "密钥可能错了"
    #       • 速率限制       (429): "请稍候 / 升级套餐"
    #       • 模型不存在     (404)
    #       • 网络超时       (URLError TimeoutError): "可能需要梯子或代理"
    # ----------------------------------------------------------------
    @staticmethod
    def _post_json(url, headers, body_dict, timeout, proxy_url=None,
                   max_retries=3):
        import time as _time

        data = _ai_json.dumps(body_dict).encode('utf-8')

        # 准备 opener (含代理). 优先 explicit proxy_url, 其次环境变量
        # (Windows IE 系统代理 也会经 urllib.getproxies() 自动读到, 但
        #  从经验看在某些梯子软件 + Windows 上读不到, 所以显式优先)
        proxy_url = (proxy_url or
                     os.environ.get('HTTPS_PROXY') or
                     os.environ.get('https_proxy') or
                     os.environ.get('HTTP_PROXY') or
                     os.environ.get('http_proxy') or '')
        ctx = _ai_ssl.create_default_context()
        if proxy_url:
            handler = _ai_url.ProxyHandler({
                'http':  proxy_url,
                'https': proxy_url})
            opener = _ai_url.build_opener(
                handler, _ai_url.HTTPSHandler(context=ctx))
        else:
            opener = _ai_url.build_opener(_ai_url.HTTPSHandler(context=ctx))

        last_err_text = ''
        last_err_code = None
        for attempt in range(max_retries):
            req = _ai_url.Request(url, data=data, method='POST')
            for k, v in headers.items():
                req.add_header(k, v)
            try:
                with opener.open(req, timeout=timeout) as resp:
                    raw = resp.read().decode('utf-8', errors='replace')
                    return _ai_json.loads(raw)

            except _ai_urlerr.HTTPError as e:
                try: body = e.read().decode('utf-8', errors='replace')
                except Exception: body = ''
                last_err_code = e.code
                last_err_text = body[:800]
                if e.code in _BaseAIProvider._RETRYABLE_HTTP and \
                   attempt < max_retries - 1:
                    delay = 1.5 * (2 ** attempt)   # 1.5s -> 3s -> 6s
                    _time.sleep(delay)
                    continue
                # 不可重试, 立刻报中文错误
                raise RuntimeError(
                    _BaseAIProvider._friendly_http_msg(e.code, body)) from e

            except _ai_urlerr.URLError as e:
                # 网络层错误: 超时 / DNS / 拒绝连接 等
                reason = getattr(e, 'reason', e)
                last_err_text = str(reason)
                if attempt < max_retries - 1:
                    delay = 1.5 * (2 ** attempt)
                    _time.sleep(delay)
                    continue
                raise RuntimeError(
                    _BaseAIProvider._friendly_network_msg(reason,
                                                          proxy_url)) from e

            except Exception as e:
                # 其他: JSON 解析失败、context 错误等, 不重试
                raise RuntimeError(f"调用出错: {type(e).__name__}: {e}") from e

        # 不会到达这里, 但为保险
        raise RuntimeError(
            f"重试 {max_retries} 次仍失败. 最近错误: "
            f"HTTP {last_err_code}: {last_err_text[:300]}")

    @staticmethod
    def _friendly_http_msg(code, body):
        """把 HTTP 错误码转成中文友好提示。

        [v9 增强]
          - 401/403 不再一刀切说"密钥错误", 先扫描响应体里的关键词:
              * "balance" / "余额" / "insufficient"  → 账户余额不足
              * "expired" / "过期"                   → 密钥过期
              * "invalid"/"unauthorized"/"无效"/"权限" → 密钥/权限错误
              * 否则                                  → 通用鉴权失败
        """
        head = f"HTTP {code}"
        body_l = (body or '').lower()

        if code in (401, 403):
            if ('balance' in body_l or 'insufficient' in body_l
                    or '余额' in body or 'recharge' in body_l):
                return (f"{head}: 账户余额不足 💰\n"
                        f"  服务商账户的余额 / 免费额度已用完, 跟密钥本身没关系。\n"
                        f"  处理办法:\n"
                        f"    • SiliconFlow: 登录 https://cloud.siliconflow.cn/\n"
                        f"      → 「钱包」/「充值」, 充几块钱就够测试很久。\n"
                        f"    • Gemini 免费版用尽 → 等 24 小时, 或升级到付费。\n"
                        f"    • Claude → 登录 https://console.anthropic.com 充值\n"
                        f"    • 或者临时换一个还有余额的服务商。\n\n"
                        f"  服务器原文: {body[:400]}")
            if 'expired' in body_l or '过期' in body:
                return (f"{head}: API 密钥已过期 ⏰\n"
                        f"  请去服务商后台重新生成一个新密钥, 粘贴到 ③ 即可\n"
                        f"  (粘贴后会自动保存, 不需要点任何按钮)。\n\n"
                        f"  服务器原文: {body[:400]}")
            if ('invalid' in body_l or 'unauthorized' in body_l or
                    'no permission' in body_l or '无效' in body or '权限' in body):
                return (f"{head}: 密钥或权限错误 ❌\n"
                        f"  常见原因:\n"
                        f"    • 复制密钥时粘漏了前缀(如 sk-...)或末尾字符\n"
                        f"    • 这个密钥没有访问当前所选模型的权限\n"
                        f"    • 项目/工作区被禁用\n"
                        f"  处理: 回到 ③ 重新粘贴密钥; 或换一个模型 (②) 试试。\n\n"
                        f"  服务器原文: {body[:400]}")
            return (f"{head}: 鉴权失败 ❌\n"
                    f"  可能原因: API 密钥错误 / 过期 / 被吊销, 或账户欠费。\n"
                    f"  请先看服务器原文判断具体原因, 再回到 ① ② ③ 处理。\n\n"
                    f"  服务器原文: {body[:400]}")
        if code == 404:
            return (f"{head}: 模型不存在 ❌\n"
                    f"  这个模型名在该服务商下没找到, 可能已下线或拼错。\n"
                    f"  回到 ② 选另一个模型试试。\n\n"
                    f"  服务器原文: {body[:400]}")
        if code == 429:
            return (f"{head}: 请求太频繁 / 超出配额 ⏳\n"
                    f"  • 免费额度用完了 → 等 1 小时, 或升级套餐\n"
                    f"  • 短时间发太多 → 等几秒再点\n\n"
                    f"  服务器原文: {body[:400]}")
        if code in (500, 502, 503, 504):
            return (f"{head}: 服务商临时过载 / 维护中 ⚠\n"
                    f"  这是 AI 服务商那边的问题, 跟你无关。\n"
                    f"  程序已经自动重试 3 次还是失败 → 建议:\n"
                    f"    • 等 2 ~ 5 分钟再点「🚀 生成 AI 建议」\n"
                    f"    • 或换个模型 (比如 Gemini 503 时换 Claude / SiliconFlow)\n\n"
                    f"  服务器原文: {body[:400]}")
        return f"{head}: {body[:600]}"

    @staticmethod
    def _friendly_network_msg(reason, proxy_url):
        """把网络层错误 (URLError) 转成中文友好提示"""
        rs = str(reason)
        is_timeout = ('timed out' in rs.lower() or 'timeout' in rs.lower()
                      or '10060' in rs or '10054' in rs)
        is_dns = ('Name or service not known' in rs
                  or 'getaddrinfo' in rs.lower())
        is_refused = ('Connection refused' in rs or '10061' in rs)

        lines = ['网络连接失败 🌐  (程序已自动重试 3 次)']
        lines.append(f'  错误明细: {rs}')
        lines.append('')
        if is_timeout:
            lines.append('  ⏱  「连接超时」(WinError 10060)。常见原因:')
            lines.append('    1. 没开梯子, 或梯子断了 (Gemini / Claude 需要)')
            lines.append('    2. 梯子开着, 但 Python urllib 没用到代理 ←')
            lines.append('       这是 Windows 上最常见的情况。解决办法:')
            lines.append('       A. (推荐) 在「④ 代理」框直接填:')
            lines.append('          http://127.0.0.1:7890  (Clash)')
            lines.append('          http://127.0.0.1:10809 (v2rayN)')
            lines.append('       B. 在 cmd 里设环境变量:')
            lines.append('          set HTTPS_PROXY=http://127.0.0.1:7890')
            lines.append('          再从这个 cmd 启动软件')
            lines.append('    3. 服务器负载高, 5 分钟后再试')
            lines.append('    4. 实在不想折腾 → 改用「SiliconFlow (国内)」')
        elif is_dns:
            lines.append('  🔍  DNS 解析失败:')
            lines.append('    1. 先检查电脑能不能上网')
            lines.append('    2. 域名被屏蔽 → 开梯子, 或换 SiliconFlow')
        elif is_refused:
            lines.append('  ❌  连接被拒绝:')
            lines.append('    1. 如果填了代理地址, 看看梯子是不是在跑')
            lines.append('    2. 端口对不对 (常见 7890 / 1080 / 10809)')
        else:
            lines.append('  其他建议:')
            lines.append('    1. 试一下能不能访问 google.com (开梯子时)')
            lines.append('    2. 在「④ 代理」填上梯子地址')
            lines.append('    3. 改用「SiliconFlow (国内)」无需梯子')

        if proxy_url:
            lines.append('')
            lines.append(f'  当前代理: {proxy_url}')
        else:
            lines.append('')
            lines.append('  当前没用代理 (HTTPS_PROXY 环境变量为空)')

        return '\n'.join(lines)


class GeminiProvider(_BaseAIProvider):
    code = "gemini"
    display_name = "Google Gemini"
    default_models = [
        ("gemini-2.5-flash",  "Gemini 2.5 Flash  (快、便宜)"),
        ("gemini-2.5-pro",    "Gemini 2.5 Pro    (更强)"),
        ("gemini-1.5-flash",  "Gemini 1.5 Flash"),
        ("gemini-1.5-pro",    "Gemini 1.5 Pro"),
    ]
    key_help = ("在 https://aistudio.google.com/ 登录后,左侧 \"Get API key\" "
                "免费获取,粘贴到下方。")

    @classmethod
    def call(cls, prompt, api_key, model=None, timeout=60, proxy_url=None):
        model = model or cls.default_models[0][0]
        url = (f"https://generativelanguage.googleapis.com/v1beta/"
               f"models/{model}:generateContent?key={api_key}")
        # [v9.2 修复] Gemini 2.5 Flash / 2.5 Pro 默认会启用 "thinking" 模式,
        # 把内部推理过程也计入 max_output_tokens 配额。一份 ~1200 字的中文
        # 临床报告需要 ~2000 真实输出 tokens, 但 Gemini 会先用 3000-5000
        # tokens 做"思考", 总配额 8000 就被吃光 → 输出被截断。
        # 修复:
        #   1) thinkingConfig: {thinkingBudget: 0} 显式禁用 thinking, 节省
        #      所有 token 给最终输出。对于纯写作任务效果更好。
        #   2) maxOutputTokens 8000 → 16000, 防止极端情况。
        body = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "temperature": 0.4,
                "maxOutputTokens": 16000,
                "thinkingConfig": {"thinkingBudget": 0},
            },
        }
        rsp = cls._post_json(url, {"Content-Type": "application/json"},
                              body, timeout, proxy_url=proxy_url)
        try:
            return rsp["candidates"][0]["content"]["parts"][0]["text"]
        except Exception:
            return _ai_json.dumps(rsp, ensure_ascii=False, indent=2)


class ClaudeProvider(_BaseAIProvider):
    code = "claude"
    display_name = "Anthropic Claude"
    default_models = [
        ("claude-sonnet-4-5",         "Claude Sonnet 4.5"),
        ("claude-opus-4-5",           "Claude Opus 4.5     (最强,贵)"),
        ("claude-3-5-sonnet-latest",  "Claude 3.5 Sonnet"),
        ("claude-3-5-haiku-latest",   "Claude 3.5 Haiku    (快)"),
    ]
    key_help = ("在 https://console.anthropic.com/ 注册账号,在 API Keys "
                "页面创建 sk-ant-... 开头的密钥,粘贴到下方。")

    @classmethod
    def call(cls, prompt, api_key, model=None, timeout=60, proxy_url=None):
        model = model or cls.default_models[0][0]
        url = "https://api.anthropic.com/v1/messages"
        body = {
            "model": model,
            "max_tokens": 8000,
            "messages": [{"role": "user", "content": prompt}],
        }
        rsp = cls._post_json(url, {
            "x-api-key":         api_key,
            "anthropic-version": "2023-06-01",
            "Content-Type":      "application/json",
        }, body, timeout, proxy_url=proxy_url)
        try:
            parts = rsp.get("content", [])
            return "\n".join(
                p.get("text", "") for p in parts if p.get("type") == "text")
        except Exception:
            return _ai_json.dumps(rsp, ensure_ascii=False, indent=2)


